import{O as e,f as t,u as n}from"./runtime-core.esm-bundler-DwmdDY9i.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/01-Infrastructure/Quantum/Business/review.html","title":"Review(복습): 양자 비즈니스 기초","lang":"ko-KR","frontmatter":{"description":"양자 비즈니스 기초 복습 문제 풀이","tag":["quantum","business","review","practice"],"head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Review(복습): 양자 비즈니스 기초\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2025-12-13T06:09:04.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://docmoa.github.io/01-Infrastructure/Quantum/Business/review.html"}],["meta",{"property":"og:site_name","content":"docmoa"}],["meta",{"property":"og:title","content":"Review(복습): 양자 비즈니스 기초"}],["meta",{"property":"og:description","content":"양자 비즈니스 기초 복습 문제 풀이"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"ko-KR"}],["meta",{"property":"og:updated_time","content":"2025-12-13T06:09:04.000Z"}],["meta",{"property":"article:tag","content":"practice"}],["meta",{"property":"article:tag","content":"review"}],["meta",{"property":"article:tag","content":"business"}],["meta",{"property":"article:tag","content":"quantum"}],["meta",{"property":"article:modified_time","content":"2025-12-13T06:09:04.000Z"}]]},"git":{"createdTime":1765606144000,"updatedTime":1765606144000,"contributors":[{"name":"Great-Stone","username":"Great-Stone","email":"hahohh@gmail.com","commits":1,"url":"https://github.com/Great-Stone"}]},"readingTime":{"minutes":95.22,"words":5713},"filePathRelative":"01-Infrastructure/Quantum/Business/review.md","excerpt":"\\n<div class=\\"hint-container caution\\">\\n<p class=\\"hint-container-title\\">NOTE</p>\\n<p>이 문서는 양자 비즈니스 기초 복습 문제 풀이를 위한 문서입니다.</p>\\n</div>\\n<h2>문제 1: Moore's Law와 Classical Computing의 한계</h2>\\n<div class=\\"hint-container tip\\">\\n<p class=\\"hint-container-title\\">문제 제시</p>\\n<p>다음 진술이 참인지 거짓인지 선택하세요:</p>\\n<p>&quot;Current classical computing power has reached a level of saturation showing that Moore's Law is coming (or has come) to an end.&quot;</p>\\n<p>(현재 고전 컴퓨팅 성능은 Moore's Law가 끝나가고 있거나(또는 이미 끝났음을) 보여주는 포화 수준에 도달했습니다)</p>\\n<ul>\\n<li>A. False (거짓)</li>\\n<li>B. True (참)</li>\\n</ul>\\n</div>"}`),a={name:`review.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="review-복습-양자-비즈니스-기초" tabindex="-1"><a class="header-anchor" href="#review-복습-양자-비즈니스-기초"><span>Review(복습): 양자 비즈니스 기초</span></a></h1><div class="hint-container caution"><p class="hint-container-title">NOTE</p><p>이 문서는 양자 비즈니스 기초 복습 문제 풀이를 위한 문서입니다.</p></div><h2 id="문제-1-moore-s-law와-classical-computing의-한계" tabindex="-1"><a class="header-anchor" href="#문제-1-moore-s-law와-classical-computing의-한계"><span>문제 1: Moore&#39;s Law와 Classical Computing의 한계</span></a></h2><div class="hint-container tip"><p class="hint-container-title">문제 제시</p><p>다음 진술이 참인지 거짓인지 선택하세요:</p><p>&quot;Current classical computing power has reached a level of saturation showing that Moore&#39;s Law is coming (or has come) to an end.&quot;</p><p>(현재 고전 컴퓨팅 성능은 Moore&#39;s Law가 끝나가고 있거나(또는 이미 끝났음을) 보여주는 포화 수준에 도달했습니다)</p><ul><li>A. False (거짓)</li><li>B. True (참)</li></ul></div><h3 id="필요한-기반-지식" tabindex="-1"><a class="header-anchor" href="#필요한-기반-지식"><span>필요한 기반 지식</span></a></h3><h4 id="_1-moore-s-law-무어의-법칙" tabindex="-1"><a class="header-anchor" href="#_1-moore-s-law-무어의-법칙"><span>1. Moore&#39;s Law (무어의 법칙)</span></a></h4><p><strong>정의:</strong></p><ul><li>Moore&#39;s Law는 Intel의 공동 설립자인 Gordon Moore가 1965년에 제시한 관찰입니다</li><li>반도체 집적 회로의 트랜지스터 수가 약 2년마다 2배씩 증가한다는 법칙입니다</li><li>이는 컴퓨팅 성능의 지수적 성장을 의미합니다</li></ul><p><strong>역사적 배경:</strong></p><ul><li>1965년부터 약 50년간 지속적으로 유지되었습니다</li><li>반도체 산업의 기술 로드맵과 투자 전략의 기초가 되었습니다</li><li>컴퓨터 성능 향상의 주요 동력으로 작용했습니다</li></ul><h4 id="_2-classical-computing의-한계" tabindex="-1"><a class="header-anchor" href="#_2-classical-computing의-한계"><span>2. Classical Computing의 한계</span></a></h4><p><strong>물리적 한계:</strong></p><ul><li><strong>원자 크기 한계</strong>: 트랜지스터가 원자 크기에 근접하면서 더 이상 축소가 어려워졌습니다</li><li><strong>열 발생 문제</strong>: 트랜지스터 밀도가 증가하면서 열 발생이 급증하여 냉각이 어려워졌습니다</li><li><strong>양자 효과</strong>: 나노 스케일에서 양자 터널링과 같은 양자 효과가 나타나기 시작했습니다</li></ul><p><strong>경제적 한계:</strong></p><ul><li><strong>제조 비용 증가</strong>: 더 작은 트랜지스터를 만드는 데 필요한 제조 시설 비용이 기하급수적으로 증가했습니다</li><li><strong>수익성 저하</strong>: 새로운 제조 공정 개발에 대한 투자 대비 수익이 감소했습니다</li></ul><p><strong>성능 향상 둔화:</strong></p><ul><li>2000년대 중반부터 Moore&#39;s Law의 속도가 둔화되기 시작했습니다</li><li>단일 프로세서의 클럭 속도 향상이 정체되었습니다</li><li>멀티코어 아키텍처로 전환하여 병렬 처리로 성능을 향상시키려는 시도가 이루어졌습니다</li></ul><h4 id="_3-quantum-computing의-등장-배경" tabindex="-1"><a class="header-anchor" href="#_3-quantum-computing의-등장-배경"><span>3. Quantum Computing의 등장 배경</span></a></h4><p><strong>Classical Computing의 한계 극복 필요성:</strong></p><ul><li>복잡한 문제 해결을 위한 새로운 컴퓨팅 패러다임이 필요했습니다</li><li>Quantum Computing (양자 컴퓨팅)은 quantum mechanics (양자 역학)의 법칙을 활용하여 정보를 처리합니다</li><li>특정 문제에서 classical computer (고전 컴퓨터)보다 지수적으로 빠른 성능을 제공할 수 있습니다</li></ul><p><strong>Quantum-Centric Supercomputing (양자 중심 슈퍼컴퓨팅):</strong></p><ul><li>Quantum computer (양자 컴퓨터)와 classical computer (고전 컴퓨터)를 결합한 하이브리드 시스템</li><li>Quantum Computing (양자 컴퓨팅), AI (인공지능), classical computing (고전 컴퓨팅)을 통합한 hybrid multi-cloud (하이브리드 멀티 클라우드) workflow (워크플로우)</li><li>지난 60년 동안 가장 중요한 컴퓨팅 혁명을 이끌어낼 것으로 예상됩니다</li></ul><h4 id="_4-현재-상황" tabindex="-1"><a class="header-anchor" href="#_4-현재-상황"><span>4. 현재 상황</span></a></h4><p><strong>Moore&#39;s Law의 상태:</strong></p><ul><li>많은 전문가들이 Moore&#39;s Law가 끝나거나 끝나가고 있다고 평가합니다</li><li>일부는 &quot;Moore&#39;s Law가 느려지고 있다&quot;고 표현합니다</li><li>일부는 &quot;Moore&#39;s Law가 다른 형태로 진화하고 있다&quot;고 주장합니다</li></ul><p><strong>Classical Computing의 포화:</strong></p><ul><li>Classical supercomputer (고전 슈퍼컴퓨터)는 특정 유형의 문제를 해결하는 데는 뛰어나지만, 복잡하게 상호 작용하는 수많은 변수가 있는 문제를 해결하는 데는 어려움을 겪습니다</li><li>계산 집약적 문제에 대한 해결책으로 Quantum Computing (양자 컴퓨팅)이 주목받고 있습니다</li></ul><h3 id="풀이-과정" tabindex="-1"><a class="header-anchor" href="#풀이-과정"><span>풀이 과정</span></a></h3><ol><li><p><strong>Moore&#39;s Law의 역사적 맥락 이해</strong></p><ul><li>1965년부터 약 50년간 지속되었지만, 2000년대 중반부터 둔화되기 시작했습니다</li><li>물리적, 경제적 한계로 인해 더 이상 지수적 성장을 유지하기 어려워졌습니다</li></ul></li><li><p><strong>Classical Computing의 포화 상태 확인</strong></p><ul><li>트랜지스터 크기가 원자 크기에 근접하면서 물리적 한계에 도달했습니다</li><li>제조 비용의 기하급수적 증가로 경제적 한계에 도달했습니다</li><li>단일 프로세서 성능 향상이 정체되었습니다</li></ul></li><li><p><strong>Quantum Computing의 필요성</strong></p><ul><li>복잡한 문제를 해결하기 위한 새로운 패러다임이 필요합니다</li><li>Quantum Computing (양자 컴퓨팅)은 classical computing (고전 컴퓨팅)의 한계를 극복할 수 있는 잠재력을 가지고 있습니다</li></ul></li><li><p><strong>결론 도출</strong></p><ul><li>현재 classical computing power (고전 컴퓨팅 성능)는 포화 상태에 도달했습니다</li><li>Moore&#39;s Law는 끝나가고 있거나 이미 끝났다고 평가됩니다</li></ul></li></ol><details class="hint-container details"><summary>최종 답안</summary><p><strong>B. True</strong></p><p>현재 classical computing power (고전 컴퓨팅 성능)는 포화 상태에 도달했으며, Moore&#39;s Law는 끝나가고 있거나 이미 끝났다고 평가됩니다. 이는 물리적 한계(원자 크기), 경제적 한계(제조 비용 증가), 그리고 성능 향상의 둔화로 인한 것입니다. 이러한 상황이 Quantum Computing (양자 컴퓨팅)과 같은 새로운 컴퓨팅 패러다임의 필요성을 만들어냈습니다.</p></details><h2 id="문제-2-quantum-volume-양자-볼륨-의-의존-요소" tabindex="-1"><a class="header-anchor" href="#문제-2-quantum-volume-양자-볼륨-의-의존-요소"><span>문제 2: Quantum Volume (양자 볼륨)의 의존 요소</span></a></h2><div class="hint-container tip"><p class="hint-container-title">문제 제시</p><p>다음 중 Quantum Volume (양자 볼륨)이 의존하지 않는 것은 무엇인가?</p><p>Which of the following does Quantum Volume NOT depend on?</p><ul><li>A. Error rates (오류율)</li><li>B. Qubit connectivity (큐비트 연결성)</li><li>C. Number of qubits (큐비트 수)</li><li>D. The physical dimensions of the quantum processing unit (양자 처리 장치의 물리적 크기)</li></ul></div><h3 id="필요한-기반-지식-1" tabindex="-1"><a class="header-anchor" href="#필요한-기반-지식-1"><span>필요한 기반 지식</span></a></h3><h4 id="_1-quantum-volume-양자-볼륨-의-정의" tabindex="-1"><a class="header-anchor" href="#_1-quantum-volume-양자-볼륨-의-정의"><span>1. Quantum Volume (양자 볼륨)의 정의</span></a></h4><p><strong>개념:</strong></p><ul><li>Quantum Volume (양자 볼륨)은 IBM이 제안한 양자 컴퓨터의 전체 성능을 종합적으로 평가하는 지표입니다</li><li>단순히 qubit (큐비트) 수만으로는 양자 컴퓨터의 성능을 완전히 평가할 수 없기 때문에 도입되었습니다</li><li>Quantum Volume (양자 볼륨)은 양자 컴퓨터가 실제로 해결할 수 있는 문제의 복잡도를 측정합니다</li></ul><p><strong>목적:</strong></p><ul><li>다양한 양자 컴퓨터의 성능을 공정하게 비교할 수 있도록 합니다</li><li>하드웨어의 실제 성능을 더 정확하게 반영합니다</li><li>양자 컴퓨터의 발전을 추적하는 표준 지표로 사용됩니다</li></ul><h4 id="_2-quantum-volume-양자-볼륨-에-영향을-미치는-요소" tabindex="-1"><a class="header-anchor" href="#_2-quantum-volume-양자-볼륨-에-영향을-미치는-요소"><span>2. Quantum Volume (양자 볼륨)에 영향을 미치는 요소</span></a></h4><p><strong>A. Error Rates (오류율)</strong></p><ul><li><strong>Gate error rate (게이트 오류율)</strong>: Gate (게이트) 연산 중 발생하는 오류의 비율</li><li><strong>Measurement error (측정 오류)</strong>: Qubit (큐비트) 상태를 측정할 때 발생하는 오류</li><li><strong>Coherence error (결맞음 오류)</strong>: Qubit (큐비트)의 양자 상태가 환경과의 상호작용으로 인해 손실되는 오류</li><li>낮은 error rate (오류율)은 더 높은 Quantum Volume (양자 볼륨)을 의미합니다</li></ul><p><strong>B. Qubit Connectivity (큐비트 연결성)</strong></p><ul><li><strong>정의</strong>: Qubit (큐비트) 간의 물리적 연결 구조</li><li><strong>중요성</strong>: Qubit (큐비트) 간의 연결성이 높을수록 더 복잡한 양자 회로를 구현할 수 있습니다</li><li><strong>예시</strong>: <ul><li>완전 연결 (Fully connected): 모든 qubit (큐비트)가 서로 직접 연결됨</li><li>선형 연결 (Linear): 인접한 qubit (큐비트)만 연결됨</li><li>격자 연결 (Lattice): 특정 패턴으로 연결됨</li></ul></li><li>높은 connectivity (연결성)은 더 높은 Quantum Volume (양자 볼륨)을 가능하게 합니다</li></ul><p><strong>C. Number of Qubits (큐비트 수)</strong></p><ul><li><strong>정의</strong>: 양자 컴퓨터에 있는 qubit (큐비트)의 총 개수</li><li><strong>역할</strong>: 더 많은 qubit (큐비트)는 더 큰 양자 상태 공간을 의미합니다</li><li><strong>한계</strong>: Qubit (큐비트) 수만으로는 성능을 완전히 평가할 수 없습니다</li><li>Quantum Volume (양자 볼륨) 계산에 직접적으로 포함됩니다</li></ul><p><strong>D. Physical Dimensions (물리적 크기)</strong></p><ul><li><strong>정의</strong>: 양자 처리 장치의 실제 물리적 크기 (길이, 너비, 높이)</li><li><strong>특징</strong>: <ul><li>Quantum Volume (양자 볼륨)은 논리적 성능 지표입니다</li><li>물리적 크기는 성능에 직접적인 영향을 미치지 않습니다</li><li>같은 성능을 가진 양자 컴퓨터라도 구현 방식에 따라 크기가 다를 수 있습니다</li></ul></li><li><strong>결론</strong>: Quantum Volume (양자 볼륨)은 물리적 크기에 의존하지 않습니다</li></ul><h4 id="_3-quantum-volume-양자-볼륨-계산-방법" tabindex="-1"><a class="header-anchor" href="#_3-quantum-volume-양자-볼륨-계산-방법"><span>3. Quantum Volume (양자 볼륨) 계산 방법</span></a></h4><p><strong>기본 원리:</strong></p><ul><li>Quantum Volume (양자 볼륨)은 특정 깊이와 너비를 가진 양자 회로를 얼마나 정확하게 실행할 수 있는지를 측정합니다</li><li>회로의 깊이(depth)와 너비(width)를 증가시키면서 성공적으로 실행할 수 있는 최대 크기를 찾습니다</li><li>공식: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mi>V</mi><mo>=</mo><msup><mn>2</mn><mi>n</mi></msup></mrow><annotation encoding="application/x-tex">QV = 2^n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span> (여기서 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>n</mi></mrow><annotation encoding="application/x-tex">n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span>은 성공적으로 실행할 수 있는 최대 회로 크기)</li></ul><p><strong>고려 사항:</strong></p><ul><li>Qubit (큐비트) 수가 많아도 error rate (오류율)이 높으면 Quantum Volume (양자 볼륨)이 낮을 수 있습니다</li><li>Connectivity (연결성)가 낮으면 더 많은 gate (게이트)가 필요하여 오류가 누적될 수 있습니다</li><li>Coherence time (결맞음 시간)이 짧으면 깊은 회로를 실행할 수 없습니다</li></ul><h4 id="_4-quantum-volume-양자-볼륨-의-중요성" tabindex="-1"><a class="header-anchor" href="#_4-quantum-volume-양자-볼륨-의-중요성"><span>4. Quantum Volume (양자 볼륨)의 중요성</span></a></h4><p><strong>비즈니스 관점:</strong></p><ul><li>양자 컴퓨터의 실제 성능을 평가하는 표준 지표입니다</li><li>투자 결정과 기술 선택에 도움을 줍니다</li><li>양자 컴퓨터의 발전을 추적하는 데 사용됩니다</li></ul><p><strong>기술적 관점:</strong></p><ul><li>하드웨어 개발 방향을 제시합니다</li><li>성능 병목을 식별하는 데 도움을 줍니다</li><li>알고리즘 개발에 필요한 리소스를 평가하는 데 사용됩니다</li></ul><h3 id="풀이-과정-1" tabindex="-1"><a class="header-anchor" href="#풀이-과정-1"><span>풀이 과정</span></a></h3><ol><li><p><strong>Quantum Volume (양자 볼륨)의 정의 확인</strong></p><ul><li>Quantum Volume (양자 볼륨)은 양자 컴퓨터의 전체 성능을 종합적으로 평가하는 지표입니다</li><li>논리적 성능 지표이지, 물리적 특성을 측정하는 것이 아닙니다</li></ul></li><li><p><strong>각 옵션 분석</strong></p><ul><li><strong>A. Error rates (오류율)</strong>: Quantum Volume (양자 볼륨)에 직접적으로 영향을 미칩니다. 낮은 오류율은 더 높은 Quantum Volume (양자 볼륨)을 의미합니다.</li><li><strong>B. Qubit connectivity (큐비트 연결성)</strong>: Quantum Volume (양자 볼륨) 계산에 포함됩니다. 높은 연결성은 더 복잡한 회로를 가능하게 합니다.</li><li><strong>C. Number of qubits (큐비트 수)</strong>: Quantum Volume (양자 볼륨) 계산의 기본 요소입니다.</li><li><strong>D. Physical dimensions (물리적 크기)</strong>: Quantum Volume (양자 볼륨)은 논리적 성능 지표이므로 물리적 크기에 의존하지 않습니다.</li></ul></li><li><p><strong>결론 도출</strong></p><ul><li>Quantum Volume (양자 볼륨)은 성능 지표이므로 논리적 특성(qubit 수, 오류율, 연결성)에 의존합니다</li><li>물리적 크기는 성능에 직접적인 영향을 미치지 않으므로 Quantum Volume (양자 볼륨)에 의존하지 않습니다.</li></ul></li></ol><h3 id="최종-답안" tabindex="-1"><a class="header-anchor" href="#최종-답안"><span>최종 답안</span></a></h3><p><strong>D. The physical dimensions of the quantum processing unit (양자 처리 장치의 물리적 크기)</strong></p><p>Quantum Volume (양자 볼륨)은 양자 컴퓨터의 논리적 성능을 평가하는 지표로, qubit (큐비트) 수, error rates (오류율), qubit connectivity (큐비트 연결성) 등에 의존합니다. 그러나 물리적 크기는 성능에 직접적인 영향을 미치지 않으므로 Quantum Volume (양자 볼륨)에 의존하지 않습니다. 같은 성능을 가진 양자 컴퓨터라도 구현 방식에 따라 물리적 크기가 다를 수 있습니다.</p><h2 id="문제-3-quantum-readiness-양자-준비-상태-의-정의" tabindex="-1"><a class="header-anchor" href="#문제-3-quantum-readiness-양자-준비-상태-의-정의"><span>문제 3: Quantum Readiness (양자 준비 상태)의 정의</span></a></h2><div class="hint-container tip"><p class="hint-container-title">문제 제시</p><p>다음 진술이 참인지 거짓인지 선택하세요:</p><p>&quot;Quantum readiness is when quantum computers are ready to run commercial applications.&quot;</p><p>(양자 준비 상태는 양자 컴퓨터가 상업적 애플리케이션을 실행할 준비가 되었을 때입니다)</p><ul><li>A. True (참)</li><li>B. False (거짓)</li></ul></div><h3 id="필요한-기반-지식-2" tabindex="-1"><a class="header-anchor" href="#필요한-기반-지식-2"><span>필요한 기반 지식</span></a></h3><h4 id="_1-quantum-readiness-양자-준비-상태-의-정의" tabindex="-1"><a class="header-anchor" href="#_1-quantum-readiness-양자-준비-상태-의-정의"><span>1. Quantum Readiness (양자 준비 상태)의 정의</span></a></h4><p><strong>정의:</strong></p><ul><li><strong>Quantum readiness (양자 준비 상태)</strong>는 Quantum Computing (양자 컴퓨팅) 전략, 기술 및 운영에서 <strong>조직의 숙련도</strong>를 지속적으로 진화하는 측정입니다</li><li>이것은 산업을 혁신하고, 경쟁 우위를 창출하며, 양자에 능숙한 경쟁자로부터의 위협에 대응하기 위해 quantum technology (양자 기술)를 활용하는 <strong>회사의 점진적 역량</strong>을 특징짓습니다</li></ul><p><strong>핵심 개념:</strong></p><ul><li>Quantum Readiness (양자 준비 상태)는 <strong>조직의 역량</strong>에 관한 것입니다</li><li>양자 컴퓨터의 기술적 준비 상태가 아닙니다</li><li>지속적으로 진화하는 측정 지표입니다</li></ul><h4 id="_2-quantum-readiness-양자-준비-상태-의-구성-요소" tabindex="-1"><a class="header-anchor" href="#_2-quantum-readiness-양자-준비-상태-의-구성-요소"><span>2. Quantum Readiness (양자 준비 상태)의 구성 요소</span></a></h4><p><strong>Strategy (전략):</strong></p><ul><li>Quantum market information (양자 시장 정보)를 기회와 위협에 대한 실행 가능한 통찰력으로 전환하는 능력</li><li>Quantum-triggered strategy (양자 트리거 전략), 역량 및 혁신 이니셔티브에서 비즈니스 가치를 포착하는 숙련도</li><li>Quantum technology (양자 기술)에 대한 Intellectual Property (IP, 지적 재산권)를 보호하고 보호하는 전문성</li><li>Quantum Computing (양자 컴퓨팅)의 의도된 사용과 관련된 규제 및 표준의 영향</li></ul><p><strong>Technology (기술):</strong></p><ul><li>Quantum application (양자 애플리케이션)을 구축, 테스트, 배포 및 업데이트하기 위한 DevSecOps framework (DevSecOps 프레임워크)</li><li>Quantum addressable workflow (양자 주소 지정 가능한 워크플로우)를 지원하기 위한 AI 및 기타 고급 계산 모델 성숙도</li><li>Quantum-classical workload (양자-고전 워크로드)의 오케스트레이션 및 상호 운용을 가능하게 하는 hybrid cloud architecture (하이브리드 클라우드 아키텍처)</li></ul><p><strong>Operations (운영):</strong></p><ul><li>Quantum roadmap (양자 로드맵)의 성공적인 실행을 보장하기 위한 거버넌스 및 감독</li><li>Quantum fluency (양자 유창성)를 가진 고성능 팀을 구축하기 위한 talent strategy (인재 전략) 및 문화</li><li>비즈니스 요구를 충족하는 quantum-enabled solution (양자 활성화 솔루션)을 만드는 혁신 프로세스</li><li>높은 R&amp;D 속도와 반복적인 솔루션 설계를 결과로 하는 agile practice (애자일 실천)</li></ul><h4 id="_3-quantum-readiness-양자-준비-상태-의-목적" tabindex="-1"><a class="header-anchor" href="#_3-quantum-readiness-양자-준비-상태-의-목적"><span>3. Quantum Readiness (양자 준비 상태)의 목적</span></a></h4><p><strong>조직 역량 강화:</strong></p><ul><li>Quantum Computing (양자 컴퓨팅)의 미래 컴퓨팅 능력을 시각화하고 사용할 수 있도록 준비하는 데 도움을 줍니다</li><li>고객과 협력하여 기술을 구축하고 높은 비즈니스 영향을 가진 사용 사례를 탐색합니다</li><li>현재 quantum computer (양자 컴퓨터)에서 실행할 수 있을 만큼 작은 사용 사례를 실행함으로써 핵심 통찰력을 개발할 수 있습니다</li></ul><p><strong>지속적 발전:</strong></p><ul><li>기술이 계속 개선됨에 따라, 사용 사례의 범위를 확장하고 비즈니스 이점을 위해 Quantum Computing (양자 컴퓨팅)을 사용할 수 있습니다</li><li>Quantum Readiness (양자 준비 상태)는 정적이지 않고 지속적으로 진화하는 측정입니다</li></ul><h4 id="_4-quantum-computers의-상업적-애플리케이션-준비-상태" tabindex="-1"><a class="header-anchor" href="#_4-quantum-computers의-상업적-애플리케이션-준비-상태"><span>4. Quantum Computers의 상업적 애플리케이션 준비 상태</span></a></h4><p><strong>현재 상태:</strong></p><ul><li>Quantum computer (양자 컴퓨터)는 이미 일부 상업적 애플리케이션을 실행할 수 있습니다</li><li>하지만 이것은 Quantum Readiness (양자 준비 상태)의 정의가 아닙니다</li><li>Quantum Readiness (양자 준비 상태)는 하드웨어의 준비 상태가 아니라 조직의 준비 상태를 측정합니다</li></ul><p><strong>구분:</strong></p><ul><li><strong>Quantum computer readiness (양자 컴퓨터 준비 상태)</strong>: 하드웨어가 상업적 애플리케이션을 실행할 수 있는 기술적 준비 상태</li><li><strong>Quantum readiness (양자 준비 상태)</strong>: 조직이 양자 컴퓨팅을 활용할 수 있는 조직적 역량</li></ul><h3 id="풀이-과정-2" tabindex="-1"><a class="header-anchor" href="#풀이-과정-2"><span>풀이 과정</span></a></h3><ol><li><p><strong>Quantum Readiness (양자 준비 상태)의 정의 확인</strong></p><ul><li>Quantum Readiness (양자 준비 상태)는 조직의 숙련도를 측정하는 지표입니다</li><li>양자 컴퓨터의 기술적 준비 상태를 측정하는 것이 아닙니다</li></ul></li><li><p><strong>문제의 진술 분석</strong></p><ul><li>&quot;Quantum readiness is when quantum computers are ready to run commercial applications.&quot;</li><li>이 진술은 Quantum Readiness (양자 준비 상태)를 양자 컴퓨터의 기술적 준비 상태로 정의하고 있습니다</li><li>하지만 실제 정의는 조직의 역량에 관한 것입니다</li></ul></li><li><p><strong>구성 요소 확인</strong></p><ul><li>Quantum Readiness (양자 준비 상태)는 Strategy (전략), Technology (기술), Operations (운영) 세 가지 영역의 조직 역량을 포함합니다</li><li>이것들은 모두 조직의 역량에 관한 것이지, 하드웨어의 준비 상태에 관한 것이 아닙니다</li></ul></li><li><p><strong>결론 도출</strong></p><ul><li>Quantum Readiness (양자 준비 상태)는 양자 컴퓨터가 상업적 애플리케이션을 실행할 준비가 되었는지가 아니라, 조직이 양자 컴퓨팅을 활용할 수 있는 역량을 측정하는 것입니다.</li></ul></li></ol><details class="hint-container details"><summary>최종 답안</summary><p><strong>B. False</strong></p><p>Quantum Readiness (양자 준비 상태)는 양자 컴퓨터가 상업적 애플리케이션을 실행할 준비가 되었는지가 아니라, Quantum Computing (양자 컴퓨팅) 전략, 기술 및 운영에서 <strong>조직의 숙련도</strong>를 지속적으로 진화하는 측정입니다. 이것은 산업을 혁신하고, 경쟁 우위를 창출하며, 양자에 능숙한 경쟁자로부터의 위협에 대응하기 위해 quantum technology (양자 기술)를 활용하는 회사의 점진적 역량을 특징짓습니다. Quantum Readiness (양자 준비 상태)는 Strategy (전략), Technology (기술), Operations (운영) 세 가지 영역의 조직 역량을 포함하며, 하드웨어의 기술적 준비 상태와는 구분됩니다.</p></details><h2 id="문제-4-responsible-quantum-computing-책임-있는-양자-컴퓨팅" tabindex="-1"><a class="header-anchor" href="#문제-4-responsible-quantum-computing-책임-있는-양자-컴퓨팅"><span>문제 4: Responsible Quantum Computing (책임 있는 양자 컴퓨팅)</span></a></h2><div class="hint-container tip"><p class="hint-container-title">문제 제시</p><p>다음 중 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)이 무엇을 의미하는지 선택하세요:</p><p>What does Responsible Quantum Computing entail?</p><ul><li>A. Responsible QC is solely about making sure that in using Quantum, one is compliant with existing laws and regulations. (책임 있는 양자 컴퓨팅은 양자를 사용할 때 기존 법률 및 규제를 준수하는 것에만 관한 것입니다)</li><li>B. Making sure quantum use cases have high return on investment. (양자 사용 사례가 높은 투자 수익을 가지는 것을 보장하는 것입니다)</li><li>C. Being aware of the power of the effects of QC and mitigating potential harms by promoting solutions that are proactively inclusive and accountable. (양자 컴퓨팅의 힘과 영향을 인식하고, 적극적으로 포용적이고 책임 있는 솔루션을 촉진하여 잠재적 해를 완화하는 것입니다)</li></ul></div><h3 id="필요한-기반-지식-3" tabindex="-1"><a class="header-anchor" href="#필요한-기반-지식-3"><span>필요한 기반 지식</span></a></h3><h4 id="_1-responsible-quantum-computing-책임-있는-양자-컴퓨팅-의-정의" tabindex="-1"><a class="header-anchor" href="#_1-responsible-quantum-computing-책임-있는-양자-컴퓨팅-의-정의"><span>1. Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 정의</span></a></h4><p><strong>정의:</strong></p><ul><li>Responsible Quantum Computing (책임 있는 양자 컴퓨팅)은 <strong>그 힘과 잠재적 영향을 인식하면서 Quantum Computing (양자 컴퓨팅)을 개발하는 것</strong>으로 이해됩니다</li><li>사용 사례는 비즈니스 가치를 제공하고 그 개념과 실행에 대해 책임져야 합니다</li><li>단순히 법률 준수나 수익성에만 국한되지 않습니다</li></ul><p><strong>핵심 개념:</strong></p><ul><li><strong>인식 (Awareness)</strong>: Quantum Computing (양자 컴퓨팅)의 힘과 잠재적 영향을 인식합니다</li><li><strong>완화 (Mitigation)</strong>: 잠재적 해를 완화하기 위한 조치를 취합니다</li><li><strong>포용성 (Inclusivity)</strong>: 적극적으로 포용적인 솔루션을 촉진합니다</li><li><strong>책임성 (Accountability)</strong>: 솔루션에 대한 책임을 가집니다</li></ul><h4 id="_2-responsible-quantum-computing-책임-있는-양자-컴퓨팅-의-원칙" tabindex="-1"><a class="header-anchor" href="#_2-responsible-quantum-computing-책임-있는-양자-컴퓨팅-의-원칙"><span>2. Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 원칙</span></a></h4><p>IBM Quantum은 양자를 책임 있게 개발하기 위한 다섯 가지 원칙을 지지합니다:</p><p><strong>1. Make a positive societal impact (긍정적인 사회적 영향을 만듭니다)</strong></p><ul><li>Quantum Computing (양자 컴퓨팅)이 사회에 긍정적인 영향을 미치도록 합니다</li><li>개인과 사회 전체의 이익을 고려합니다</li></ul><p><strong>2. Explore use cases with foresight (선견지명으로 사용 사례를 탐색합니다)</strong></p><ul><li>사용 사례를 선택할 때 장기적인 영향을 고려합니다</li><li>잠재적 부작용을 사전에 예측하고 대응합니다</li></ul><p><strong>3. Promote our products accurately (제품을 정확하게 홍보합니다)</strong></p><ul><li>Quantum Computing (양자 컴퓨팅)의 능력과 한계를 정확하게 표현합니다</li><li>과장된 주장을 피하고 현실적인 기대를 설정합니다</li></ul><p><strong>4. Make consistent and transparent principled decisions (일관되고 투명한 원칙적 결정을 내립니다)</strong></p><ul><li>결정 과정이 일관되고 투명해야 합니다</li><li>원칙에 기반한 의사결정을 합니다</li></ul><p><strong>5. Build a diverse and inclusive quantum community (다양하고 포용적인 양자 커뮤니티를 구축합니다)</strong></p><ul><li>다양한 배경의 사람들이 양자 컴퓨팅에 참여할 수 있도록 합니다</li><li>포용적인 환경을 조성합니다</li></ul><h4 id="_3-responsible-quantum-computing-책임-있는-양자-컴퓨팅-의-실천" tabindex="-1"><a class="header-anchor" href="#_3-responsible-quantum-computing-책임-있는-양자-컴퓨팅-의-실천"><span>3. Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 실천</span></a></h4><p><strong>계약 조항:</strong></p><ul><li>IBM Quantum은 계약서에 IBM Quantum 고객이 quantum computer (양자 컴퓨터)를 책임 있게 사용하고, 악의적이거나 불법적인 목적으로 quantum computer (양자 컴퓨터)를 사용하지 않도록 요구하는 언어가 있습니다</li><li>이것을 <strong>responsible use (책임 있는 사용)</strong> 및 <strong>acceptable use (허용 가능한 사용)</strong> 조항이라고 합니다</li></ul><p><strong>커뮤니티 참여:</strong></p><ul><li>Quantum Computing (양자 컴퓨팅) 커뮤니티의 구성원으로서, 탐색하는 사용 사례에 대해 중요한 결정을 내립니다</li><li>책임 있는 Quantum Computing (양자 컴퓨팅) 개발에 참여하는 것이 기대됩니다</li></ul><h4 id="_4-responsible-quantum-computing-책임-있는-양자-컴퓨팅-의-범위" tabindex="-1"><a class="header-anchor" href="#_4-responsible-quantum-computing-책임-있는-양자-컴퓨팅-의-범위"><span>4. Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 범위</span></a></h4><p><strong>법률 준수 이상:</strong></p><ul><li>Responsible Quantum Computing (책임 있는 양자 컴퓨팅)은 단순히 기존 법률 및 규제를 준수하는 것을 넘어섭니다</li><li>법률이 아직 명확하지 않은 영역에서도 책임 있는 행동을 취해야 합니다</li><li>선제적이고 윤리적인 접근이 필요합니다</li></ul><p><strong>수익성 이상:</strong></p><ul><li>Responsible Quantum Computing (책임 있는 양자 컴퓨팅)은 단순히 높은 투자 수익을 보장하는 것이 아닙니다</li><li>비즈니스 가치는 중요하지만, 사회적 영향과 윤리적 고려사항도 동등하게 중요합니다</li></ul><p><strong>포용성과 책임성:</strong></p><ul><li>적극적으로 포용적인 솔루션을 촉진합니다</li><li>솔루션에 대한 책임을 가집니다</li><li>잠재적 해를 완화하기 위한 조치를 취합니다</li></ul><h3 id="풀이-과정-3" tabindex="-1"><a class="header-anchor" href="#풀이-과정-3"><span>풀이 과정</span></a></h3><ol><li><p><strong>Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 정의 확인</strong></p><ul><li>Responsible Quantum Computing (책임 있는 양자 컴퓨팅)은 그 힘과 잠재적 영향을 인식하면서 Quantum Computing (양자 컴퓨팅)을 개발하는 것입니다</li><li>단순히 법률 준수나 수익성에만 국한되지 않습니다</li></ul></li><li><p><strong>각 옵션 분석</strong></p><ul><li><strong>A. 법률 및 규제 준수</strong>: Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 일부이지만 전부는 아닙니다. 법률 준수는 기본 요구사항이지만, 책임 있는 개발은 그 이상을 포함합니다.</li><li><strong>B. 높은 투자 수익</strong>: 비즈니스 가치는 중요하지만, Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 핵심이 아닙니다. 사회적 영향과 윤리적 고려사항이 더 중요합니다.</li><li><strong>C. 힘과 영향을 인식하고 잠재적 해를 완화하며 포용적이고 책임 있는 솔루션을 촉진</strong>: 이것이 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 핵심 정의와 가장 일치합니다.</li></ul></li><li><p><strong>원칙 확인</strong></p><ul><li>IBM Quantum의 다섯 가지 원칙은 모두 사회적 영향, 포용성, 책임성에 초점을 맞추고 있습니다</li><li>법률 준수나 수익성에만 초점을 맞추지 않습니다</li></ul></li><li><p><strong>결론 도출</strong></p><ul><li>Responsible Quantum Computing (책임 있는 양자 컴퓨팅)은 양자 컴퓨팅의 힘과 영향을 인식하고, 잠재적 해를 완화하며, 적극적으로 포용적이고 책임 있는 솔루션을 촉진하는 것입니다.</li></ul></li></ol><details class="hint-container details"><summary>최종 답안</summary><p><strong>C. Being aware of the power of the effects of QC and mitigating potential harms by promoting solutions that are proactively inclusive and accountable. (양자 컴퓨팅의 힘과 영향을 인식하고, 적극적으로 포용적이고 책임 있는 솔루션을 촉진하여 잠재적 해를 완화하는 것입니다)</strong></p><p>Responsible Quantum Computing (책임 있는 양자 컴퓨팅)은 그 힘과 잠재적 영향을 인식하면서 Quantum Computing (양자 컴퓨팅)을 개발하는 것으로 이해됩니다. 이것은 단순히 법률 준수나 높은 투자 수익을 보장하는 것을 넘어서, 양자 컴퓨팅의 힘과 영향을 인식하고, 잠재적 해를 완화하며, 적극적으로 포용적이고 책임 있는 솔루션을 촉진하는 것을 포함합니다. IBM Quantum의 다섯 가지 원칙(긍정적인 사회적 영향, 선견지명, 정확한 홍보, 일관되고 투명한 결정, 다양하고 포용적인 커뮤니티)은 모두 이러한 개념을 반영합니다.</p></details><h2 id="문제-5-responsible-quantum-computing-책임-있는-양자-컴퓨팅-의-원칙" tabindex="-1"><a class="header-anchor" href="#문제-5-responsible-quantum-computing-책임-있는-양자-컴퓨팅-의-원칙"><span>문제 5: Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 원칙</span></a></h2><div class="hint-container tip"><p class="hint-container-title">문제 제시</p><p>다음 중 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 다섯 가지 원칙에 포함되지 않는 것은 무엇인가?</p><p>Which of the following is NOT one of the five stated principles for Responsible Quantum Computing?</p><ul><li>A. Make a positive societal impact. (긍정적인 사회적 영향을 만듭니다)</li><li>B. Maximize quantum computing performance at all costs. (모든 비용을 들여 양자 컴퓨팅 성능을 극대화합니다)</li><li>C. Promote our products accurately. (제품을 정확하게 홍보합니다)</li><li>D. Build a diverse and inclusive quantum community. (다양하고 포용적인 양자 커뮤니티를 구축합니다)</li></ul></div><h3 id="필요한-기반-지식-4" tabindex="-1"><a class="header-anchor" href="#필요한-기반-지식-4"><span>필요한 기반 지식</span></a></h3><h4 id="_1-responsible-quantum-computing-책임-있는-양자-컴퓨팅-의-다섯-가지-원칙" tabindex="-1"><a class="header-anchor" href="#_1-responsible-quantum-computing-책임-있는-양자-컴퓨팅-의-다섯-가지-원칙"><span>1. Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 다섯 가지 원칙</span></a></h4><p>IBM Quantum은 양자를 책임 있게 개발하기 위한 다섯 가지 원칙을 지지합니다:</p><p><strong>원칙 1: Make a positive societal impact (긍정적인 사회적 영향을 만듭니다)</strong></p><ul><li>Quantum Computing (양자 컴퓨팅)이 사회에 긍정적인 영향을 미치도록 합니다</li><li>개인과 사회 전체의 이익을 고려합니다</li><li>해로운 사용을 방지합니다</li></ul><p><strong>원칙 2: Explore use cases with foresight (선견지명으로 사용 사례를 탐색합니다)</strong></p><ul><li>사용 사례를 선택할 때 장기적인 영향을 고려합니다</li><li>잠재적 부작용을 사전에 예측하고 대응합니다</li><li>미래 세대를 위한 책임을 가집니다</li></ul><p><strong>원칙 3: Promote our products accurately (제품을 정확하게 홍보합니다)</strong></p><ul><li>Quantum Computing (양자 컴퓨팅)의 능력과 한계를 정확하게 표현합니다</li><li>과장된 주장을 피하고 현실적인 기대를 설정합니다</li><li>투명성과 정직성을 유지합니다</li></ul><p><strong>원칙 4: Make consistent and transparent principled decisions (일관되고 투명한 원칙적 결정을 내립니다)</strong></p><ul><li>결정 과정이 일관되고 투명해야 합니다</li><li>원칙에 기반한 의사결정을 합니다</li><li>이해관계자들에게 결정의 근거를 명확히 설명합니다</li></ul><p><strong>원칙 5: Build a diverse and inclusive quantum community (다양하고 포용적인 양자 커뮤니티를 구축합니다)</strong></p><ul><li>다양한 배경의 사람들이 양자 컴퓨팅에 참여할 수 있도록 합니다</li><li>포용적인 환경을 조성합니다</li><li>기회의 평등을 보장합니다</li></ul><h4 id="_2-성능-극대화와-responsible-quantum-computing-책임-있는-양자-컴퓨팅" tabindex="-1"><a class="header-anchor" href="#_2-성능-극대화와-responsible-quantum-computing-책임-있는-양자-컴퓨팅"><span>2. 성능 극대화와 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)</span></a></h4><p><strong>성능 극대화의 한계:</strong></p><ul><li>&quot;모든 비용을 들여 성능을 극대화&quot;하는 것은 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 원칙이 아닙니다</li><li>성능 향상은 중요하지만, 그것이 유일한 목표가 되어서는 안 됩니다</li><li>사회적 영향, 윤리적 고려사항, 포용성 등이 성능보다 우선시될 수 있습니다</li></ul><p><strong>균형잡힌 접근:</strong></p><ul><li>Responsible Quantum Computing (책임 있는 양자 컴퓨팅)은 성능과 책임 사이의 균형을 추구합니다</li><li>성능 향상이 다른 원칙들을 희생시키는 것을 허용하지 않습니다</li><li>지속 가능하고 책임 있는 방식으로 성능을 향상시킵니다</li></ul><h4 id="_3-원칙-간의-관계" tabindex="-1"><a class="header-anchor" href="#_3-원칙-간의-관계"><span>3. 원칙 간의 관계</span></a></h4><p><strong>상호 보완적 관계:</strong></p><ul><li>다섯 가지 원칙은 서로 독립적이지 않고 상호 보완적입니다</li><li>모든 원칙을 함께 고려해야 완전한 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)을 실현할 수 있습니다</li><li>한 원칙을 다른 원칙보다 우선시하는 것은 바람직하지 않습니다</li></ul><p><strong>통합적 접근:</strong></p><ul><li>성능, 사회적 영향, 정확성, 투명성, 포용성을 모두 고려해야 합니다</li><li>단일 목표에만 집중하는 것은 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)과 모순됩니다</li></ul><h3 id="풀이-과정-4" tabindex="-1"><a class="header-anchor" href="#풀이-과정-4"><span>풀이 과정</span></a></h3><ol><li><p><strong>다섯 가지 원칙 확인</strong></p><ul><li>원칙 1: Make a positive societal impact (긍정적인 사회적 영향을 만듭니다) - <strong>A에 해당</strong></li><li>원칙 2: Explore use cases with foresight (선견지명으로 사용 사례를 탐색합니다)</li><li>원칙 3: Promote our products accurately (제품을 정확하게 홍보합니다) - <strong>C에 해당</strong></li><li>원칙 4: Make consistent and transparent principled decisions (일관되고 투명한 원칙적 결정을 내립니다)</li><li>원칙 5: Build a diverse and inclusive quantum community (다양하고 포용적인 양자 커뮤니티를 구축합니다) - <strong>D에 해당</strong></li></ul></li><li><p><strong>각 옵션 분석</strong></p><ul><li><strong>A. Make a positive societal impact</strong>: 원칙 1번에 해당합니다</li><li><strong>B. Maximize quantum computing performance at all costs</strong>: 이것은 다섯 가지 원칙 중 어느 것에도 해당하지 않습니다. 오히려 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 정신과 모순됩니다</li><li><strong>C. Promote our products accurately</strong>: 원칙 3번에 해당합니다</li><li><strong>D. Build a diverse and inclusive quantum community</strong>: 원칙 5번에 해당합니다</li></ul></li><li><p><strong>성능 극대화의 문제점</strong></p><ul><li>&quot;모든 비용을 들여 성능을 극대화&quot;하는 것은 사회적 영향, 윤리적 고려사항, 포용성 등을 무시할 수 있습니다</li><li>Responsible Quantum Computing (책임 있는 양자 컴퓨팅)은 성능과 책임 사이의 균형을 추구합니다</li></ul></li><li><p><strong>결론 도출</strong></p><ul><li>A, C, D는 모두 다섯 가지 원칙에 포함됩니다</li><li>B는 원칙에 포함되지 않으며, 오히려 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 정신과 모순됩니다.</li></ul></li></ol><details class="hint-container details"><summary>최종 답안</summary><p><strong>B. Maximize quantum computing performance at all costs. (모든 비용을 들여 양자 컴퓨팅 성능을 극대화합니다)</strong></p><p>IBM Quantum의 Responsible Quantum Computing (책임 있는 양자 컴퓨팅) 다섯 가지 원칙은 다음과 같습니다: (1) 긍정적인 사회적 영향을 만듭니다, (2) 선견지명으로 사용 사례를 탐색합니다, (3) 제품을 정확하게 홍보합니다, (4) 일관되고 투명한 원칙적 결정을 내립니다, (5) 다양하고 포용적인 양자 커뮤니티를 구축합니다. &quot;모든 비용을 들여 성능을 극대화&quot;하는 것은 이 원칙들에 포함되지 않으며, 오히려 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 정신과 모순됩니다. Responsible Quantum Computing (책임 있는 양자 컴퓨팅)은 성능과 책임 사이의 균형을 추구하며, 성능 향상이 사회적 영향, 윤리적 고려사항, 포용성 등을 희생시키는 것을 허용하지 않습니다.</p></details><h2 id="문제-6-유망한-양자-컴퓨팅-사용-사례의-특성" tabindex="-1"><a class="header-anchor" href="#문제-6-유망한-양자-컴퓨팅-사용-사례의-특성"><span>문제 6: 유망한 양자 컴퓨팅 사용 사례의 특성</span></a></h2><div class="hint-container tip"><p class="hint-container-title">문제 제시</p><p>다음 중 유망한 양자 컴퓨팅 사용 사례의 특성은 무엇인가?</p><p>Which of the following is an attribute of a promising quantum computing use case?</p><ul><li>A. Require quantum fault tolerance to achieve a result. (결과를 달성하기 위해 양자 오류 허용이 필요합니다)</li><li>B. Includes invention or re-design a quantum algorithm. (양자 알고리즘을 발명하거나 재설계하는 것을 포함합니다)</li><li>C. Could be explored with a near-term classical-quantum hybrid approach. (단기 고전-양자 하이브리드 접근 방식으로 탐색할 수 있습니다)</li><li>D. Involve the use of large volumes of data for inputs or processing. (입력 또는 처리에 대용량 데이터 사용을 포함합니다)</li></ul></div><h3 id="필요한-기반-지식-5" tabindex="-1"><a class="header-anchor" href="#필요한-기반-지식-5"><span>필요한 기반 지식</span></a></h3><h4 id="_1-좋은-양자-사용-사례의-특성" tabindex="-1"><a class="header-anchor" href="#_1-좋은-양자-사용-사례의-특성"><span>1. 좋은 양자 사용 사례의 특성</span></a></h4><p><strong>정의:</strong></p><ul><li>좋은 사용 사례는 비즈니스에 전략적으로 중요할 것으로 예상됩니다</li><li>사용 가능한 Qiskit routine (Qiskit 루틴)으로 탐색할 수 있습니다</li><li>Quantum technology (양자 기술)가 발전함에 따라 실험할 수 있는 유연성을 제공합니다</li></ul><p><strong>핵심 원칙:</strong></p><ul><li>현재 기술로 실현 가능해야 합니다</li><li>확장 가능해야 합니다</li><li>비즈니스 가치를 제공해야 합니다</li><li>유연하고 적응 가능해야 합니다</li></ul><h4 id="_2-good-choices-좋은-선택-의-특성" tabindex="-1"><a class="header-anchor" href="#_2-good-choices-좋은-선택-의-특성"><span>2. Good Choices (좋은 선택)의 특성</span></a></h4><p><strong>1. Qiskit library 및 교육에서 사용 가능한 루틴에 의존합니다</strong></p><ul><li>기존에 검증된 도구와 방법을 활용합니다</li><li>새로운 알고리즘을 발명할 필요가 없습니다</li><li>학습 곡선이 낮습니다</li></ul><p><strong>2. 실용적인 크기로 축소할 수 있는 문제를 기반으로 합니다</strong></p><ul><li>현재 양자 컴퓨터의 제약사항을 고려합니다</li><li>작은 규모로 시작하여 점진적으로 확장할 수 있습니다</li><li>즉시 실험할 수 있습니다</li></ul><p><strong>3. 확장성이 결과를 개선하는 문제를 기반으로 합니다</strong></p><ul><li>문제가 커질수록 양자 컴퓨팅의 이점이 더 명확해집니다</li><li>미래의 더 큰 양자 컴퓨터에서 더 큰 가치를 제공할 수 있습니다</li></ul><p><strong>4. 혁신적이거나 차별화된 솔루션을 예상합니다</strong></p><ul><li>기존 방법으로는 달성하기 어려운 결과를 제공합니다</li><li>경쟁 우위를 창출할 수 있습니다</li></ul><p><strong>5. 단기 classical-quantum hybrid approach (고전-양자 하이브리드 접근 방식)로 탐색할 수 있습니다</strong></p><ul><li>현재 기술로 실현 가능합니다</li><li>고전 컴퓨터와 양자 컴퓨터를 결합하여 사용할 수 있습니다</li><li>점진적으로 양자 컴퓨팅의 역할을 확대할 수 있습니다</li></ul><h4 id="_3-risky-choices-위험한-선택-의-특성" tabindex="-1"><a class="header-anchor" href="#_3-risky-choices-위험한-선택-의-특성"><span>3. Risky Choices (위험한 선택)의 특성</span></a></h4><p><strong>특징:</strong></p><ul><li>연구 출판물에서 테스트되지 않은 아이디어를 실험합니다</li><li>유용한 결과를 얻기 위해 변수를 신중하게 선택해야 합니다</li><li>성장하거나 더 복잡해질 것으로 예상되지 않는 문제를 기반으로 합니다</li><li>비즈니스의 mission-critical (미션 크리티컬) 부분과 관련된 문제를 기반으로 합니다</li><li><strong>결과를 달성하기 위해 quantum fault tolerance (양자 오류 허용)가 필요합니다</strong> - 이것은 현재 기술로는 실현 불가능합니다</li></ul><h4 id="_4-poor-choices-나쁜-선택-의-특성" tabindex="-1"><a class="header-anchor" href="#_4-poor-choices-나쁜-선택-의-특성"><span>4. Poor Choices (나쁜 선택)의 특성</span></a></h4><p><strong>특징:</strong></p><ul><li><strong>Quantum algorithm (양자 알고리즘)을 발명하거나 재설계합니다</strong> - 전문 지식과 시간이 많이 필요합니다</li><li><strong>입력 또는 처리에 대용량 데이터 사용이 필요합니다</strong> - 양자 컴퓨터는 현재 제한된 데이터 처리 능력을 가지고 있습니다</li><li>특정 수준의 성능을 얻기 위해 솔루션이 필요합니다</li><li>비즈니스의 핵심 부분을 다루지 않습니다</li><li>Fail-safe (안전 장치) 또는 임시 솔루션으로 classical alternative (고전적 대안)가 없습니다</li></ul><h4 id="_5-classical-quantum-hybrid-approach-고전-양자-하이브리드-접근-방식" tabindex="-1"><a class="header-anchor" href="#_5-classical-quantum-hybrid-approach-고전-양자-하이브리드-접근-방식"><span>5. Classical-Quantum Hybrid Approach (고전-양자 하이브리드 접근 방식)</span></a></h4><p><strong>개념:</strong></p><ul><li>고전 컴퓨터와 양자 컴퓨터를 결합하여 사용하는 접근 방식입니다</li><li>각각의 장점을 활용합니다</li><li>현재 기술로 실현 가능합니다</li></ul><p><strong>장점:</strong></p><ul><li>현재 사용 가능한 양자 컴퓨터의 제약사항을 고려합니다</li><li>고전 컴퓨터의 강점과 양자 컴퓨터의 강점을 결합합니다</li><li>점진적으로 양자 컴퓨팅의 역할을 확대할 수 있습니다</li><li>실용적이고 즉시 적용 가능합니다</li></ul><p><strong>예시:</strong></p><ul><li>고전 컴퓨터가 데이터 전처리를 수행하고, 양자 컴퓨터가 특정 계산을 수행합니다</li><li>양자 컴퓨터의 결과를 고전 컴퓨터가 후처리합니다</li><li>반복적인 최적화 과정에서 양자와 고전 컴퓨터를 번갈아 사용합니다</li></ul><h3 id="풀이-과정-5" tabindex="-1"><a class="header-anchor" href="#풀이-과정-5"><span>풀이 과정</span></a></h3><ol><li><p><strong>좋은 사용 사례의 특성 확인</strong></p><ul><li>좋은 사용 사례는 단기 classical-quantum hybrid approach (고전-양자 하이브리드 접근 방식)로 탐색할 수 있습니다</li><li>이것은 현재 기술로 실현 가능하고, 점진적으로 확장할 수 있습니다</li></ul></li><li><p><strong>각 옵션 분석</strong></p><ul><li><strong>A. Require quantum fault tolerance</strong>: 이것은 Risky choice (위험한 선택)에 해당합니다. 현재 기술로는 실현 불가능하며, 미래의 기술에 의존합니다.</li><li><strong>B. Includes invention or re-design a quantum algorithm</strong>: 이것은 Poor choice (나쁜 선택)에 해당합니다. 전문 지식과 시간이 많이 필요하며, 기존 도구를 활용하는 것이 좋습니다.</li><li><strong>C. Could be explored with a near-term classical-quantum hybrid approach</strong>: 이것은 Good choice (좋은 선택)에 해당합니다. 현재 기술로 실현 가능하고, 점진적으로 확장할 수 있습니다.</li><li><strong>D. Involve the use of large volumes of data</strong>: 이것은 Poor choice (나쁜 선택)에 해당합니다. 양자 컴퓨터는 현재 제한된 데이터 처리 능력을 가지고 있습니다.</li></ul></li><li><p><strong>하이브리드 접근 방식의 장점</strong></p><ul><li>현재 기술로 실현 가능합니다</li><li>고전 컴퓨터와 양자 컴퓨터의 장점을 결합합니다</li><li>점진적으로 양자 컴퓨팅의 역할을 확대할 수 있습니다</li></ul></li><li><p><strong>결론 도출</strong></p><ul><li>유망한 양자 컴퓨팅 사용 사례는 단기 classical-quantum hybrid approach (고전-양자 하이브리드 접근 방식)로 탐색할 수 있어야 합니다.</li></ul></li></ol><details class="hint-container details"><summary>최종 답안</summary><p><strong>C. Could be explored with a near-term classical-quantum hybrid approach. (단기 고전-양자 하이브리드 접근 방식으로 탐색할 수 있습니다)</strong></p><p>유망한 양자 컴퓨팅 사용 사례는 단기 classical-quantum hybrid approach (고전-양자 하이브리드 접근 방식)로 탐색할 수 있어야 합니다. 이것은 현재 기술로 실현 가능하고, 고전 컴퓨터와 양자 컴퓨터의 장점을 결합하여 사용할 수 있으며, 점진적으로 양자 컴퓨팅의 역할을 확대할 수 있습니다. 반면, quantum fault tolerance (양자 오류 허용)가 필요하거나, 양자 알고리즘을 발명하거나 재설계해야 하거나, 대용량 데이터를 사용해야 하는 사용 사례는 현재 기술로는 실현하기 어렵거나 비효율적이므로 유망하지 않습니다.</p></details><h2 id="문제-7-harvest-now-decrypt-later-사이버-공격-전략" tabindex="-1"><a class="header-anchor" href="#문제-7-harvest-now-decrypt-later-사이버-공격-전략"><span>문제 7: &quot;Harvest Now, Decrypt Later&quot; 사이버 공격 전략</span></a></h2><div class="hint-container tip"><p class="hint-container-title">문제 제시</p><p>&quot;Harvest now, decrypt later (지금 수확, 나중에 해독)&quot; 사이버 공격 전략은 사이버 범죄자가 오늘 암호화된 데이터를 수집하고, 다음 중 어떤 일이 발생할 때 해독할 수 있다는 의미인가?</p><p>The cyber attack strategy known as &quot;harvest now, decrypt later&quot; means cyber criminals could harvest encrypted data today, and decrypt it when which of the following happen?</p><ul><li>A. None of these. (이 중 어느 것도 아닙니다)</li><li>B. Quantum computers break modern encryption like RSA. (양자 컴퓨터가 RSA와 같은 현대 암호화를 깨뜨릴 때)</li><li>C. Quantum computers reach utility scale. (양자 컴퓨터가 실용적 규모에 도달할 때)</li><li>D. Quantum computers break 1000 qubits. (양자 컴퓨터가 1000 큐비트를 돌파할 때)</li></ul></div><h3 id="필요한-기반-지식-6" tabindex="-1"><a class="header-anchor" href="#필요한-기반-지식-6"><span>필요한 기반 지식</span></a></h3><h4 id="_1-harvest-now-decrypt-later-전략의-정의" tabindex="-1"><a class="header-anchor" href="#_1-harvest-now-decrypt-later-전략의-정의"><span>1. &quot;Harvest Now, Decrypt Later&quot; 전략의 정의</span></a></h4><p><strong>개념:</strong></p><ul><li>&quot;Harvest now, decrypt later (지금 수확, 나중에 해독)&quot;은 사이버 범죄자가 사용하는 장기적 공격 전략입니다</li><li>오늘 암호화된 데이터를 수집하고 저장한 후, 미래에 양자 컴퓨터가 충분히 강력해지면 해독하는 전략입니다</li><li>현재는 안전한 암호화된 데이터도 미래에는 취약해질 수 있습니다</li></ul><p><strong>동기:</strong></p><ul><li>오늘 수집한 데이터가 미래에 가치가 있을 수 있습니다</li><li>양자 컴퓨터가 현대 암호화를 깨뜨릴 수 있을 때까지 기다립니다</li><li>장기적인 투자 관점에서 데이터를 수집합니다</li></ul><h4 id="_2-현대-암호화와-양자-컴퓨팅의-위협" tabindex="-1"><a class="header-anchor" href="#_2-현대-암호화와-양자-컴퓨팅의-위협"><span>2. 현대 암호화와 양자 컴퓨팅의 위협</span></a></h4><p><strong>현대 암호화 알고리즘:</strong></p><ul><li><strong>RSA (Rivest-Shamir-Adleman)</strong>: 공개키 암호화 알고리즘으로, 개인 통신 보안에 널리 사용됩니다</li><li><strong>ECC (Elliptic Curve Cryptography)</strong>: 타원 곡선 암호화</li><li><strong>AES (Advanced Encryption Standard)</strong>: 대칭키 암호화 알고리즘</li></ul><p><strong>양자 컴퓨팅의 위협:</strong></p><ul><li>Quantum computer (양자 컴퓨터)가 성숙해짐에 따라, 현대 사이버 보안이 의존하는 classical encryption algorithm (고전 암호화 알고리즘) 및 protocol (프로토콜)에 도전을 제시할 것입니다</li><li>Shor&#39;s algorithm (쇼어 알고리즘)은 RSA와 같은 공개키 암호화를 깨뜨릴 수 있습니다</li><li>1994년 Peter Shor는 완벽하게 작동하는 quantum computer (양자 컴퓨터)가 RSA 암호를 해독할 수 있음을 증명했습니다</li></ul><h4 id="_3-shor-s-algorithm-쇼어-알고리즘-과-rsa" tabindex="-1"><a class="header-anchor" href="#_3-shor-s-algorithm-쇼어-알고리즘-과-rsa"><span>3. Shor&#39;s Algorithm (쇼어 알고리즘)과 RSA</span></a></h4><p><strong>Shor&#39;s Algorithm (쇼어 알고리즘):</strong></p><ul><li>1994년 Peter Shor가 개발한 양자 알고리즘입니다</li><li>RSA 암호화를 깨뜨릴 수 있습니다</li><li>일반 컴퓨터로는 우주의 수명만큼 걸릴 작업을 단 몇 분 만에 해낼 수 있습니다</li></ul><p><strong>RSA 암호화:</strong></p><ul><li>개인 통신 보안에 널리 사용되는 공개키 암호화 알고리즘입니다</li><li>큰 수의 소인수분해의 어려움에 기반합니다</li><li>양자 컴퓨터가 Shor&#39;s algorithm (쇼어 알고리즘)을 사용하면 RSA를 깨뜨릴 수 있습니다</li></ul><h4 id="_4-quantum-safe-cryptography-양자-안전-암호화-의-필요성" tabindex="-1"><a class="header-anchor" href="#_4-quantum-safe-cryptography-양자-안전-암호화-의-필요성"><span>4. Quantum-Safe Cryptography (양자 안전 암호화)의 필요성</span></a></h4><p><strong>위험의 시기:</strong></p><ul><li>위험이 아직 몇 년은 남아 있을 가능성이 높지만, 사이버 범죄자는 이미 &quot;harvest now, decrypt later (지금 수확, 나중에 해독)&quot; 계획을 사용할 수 있습니다</li><li>고객이 오늘 저장하는 데이터는 최대 30년 이상 기간 동안 기밀로 유지해야 할 수 있습니다</li><li>양자 컴퓨터가 RSA를 깨뜨릴 수 있을 때까지 데이터를 보호해야 합니다</li></ul><p><strong>대응 방안:</strong></p><ul><li>Quantum-safe security solution (양자 안전 보안 솔루션)으로 전환해야 합니다</li><li>Post-quantum cryptographic standard (포스트 양자 암호화 표준)을 채택해야 합니다</li><li>IBM Quantum Safe™ 기술 및 서비스를 활용할 수 있습니다</li></ul><h4 id="_5-qubit-수와-암호화-해독" tabindex="-1"><a class="header-anchor" href="#_5-qubit-수와-암호화-해독"><span>5. Qubit 수와 암호화 해독</span></a></h4><p><strong>Qubit 수의 역할:</strong></p><ul><li>Qubit (큐비트) 수는 양자 컴퓨터의 성능에 영향을 미칩니다</li><li>하지만 특정 수의 qubit (큐비트)를 돌파하는 것 자체가 암호화를 깨뜨리는 것은 아닙니다</li><li>RSA를 깨뜨리려면 Shor&#39;s algorithm (쇼어 알고리즘)을 실행할 수 있는 충분한 qubit (큐비트)와 낮은 오류율이 필요합니다</li></ul><p><strong>Utility Scale (실용적 규모):</strong></p><ul><li>Utility scale은 양자 컴퓨터가 실용적인 문제를 해결할 수 있는 규모를 의미합니다</li><li>하지만 이것이 반드시 RSA를 깨뜨릴 수 있다는 것을 의미하는 것은 아닙니다</li><li>RSA를 깨뜨리는 것은 특정 알고리즘(Shor&#39;s algorithm)을 실행할 수 있는 능력에 달려 있습니다</li></ul><h3 id="풀이-과정-6" tabindex="-1"><a class="header-anchor" href="#풀이-과정-6"><span>풀이 과정</span></a></h3><ol><li><p><strong>&quot;Harvest Now, Decrypt Later&quot; 전략의 목적 확인</strong></p><ul><li>사이버 범죄자는 오늘 암호화된 데이터를 수집하고, 미래에 양자 컴퓨터가 충분히 강력해지면 해독합니다</li><li>핵심은 양자 컴퓨터가 현대 암호화를 깨뜨릴 수 있을 때입니다</li></ul></li><li><p><strong>현대 암호화와 양자 컴퓨팅의 관계</strong></p><ul><li>Quantum computer (양자 컴퓨터)가 성숙해짐에 따라, 현대 사이버 보안이 의존하는 classical encryption algorithm (고전 암호화 알고리즘)에 도전을 제시할 것입니다</li><li>Shor&#39;s algorithm (쇼어 알고리즘)은 RSA와 같은 공개키 암호화를 깨뜨릴 수 있습니다</li></ul></li><li><p><strong>각 옵션 분석</strong></p><ul><li><strong>A. None of these</strong>: 문서에서 명확히 &quot;harvest now, decrypt later&quot; 전략이 언급되므로 틀렸습니다</li><li><strong>B. Quantum computers break modern encryption like RSA</strong>: 이것이 정확한 답입니다. Shor&#39;s algorithm (쇼어 알고리즘)을 사용하여 RSA를 깨뜨릴 수 있을 때를 의미합니다</li><li><strong>C. Quantum computers reach utility scale</strong>: Utility scale은 실용적 규모를 의미하지만, RSA를 깨뜨리는 것과 직접적인 관련이 없습니다</li><li><strong>D. Quantum computers break 1000 qubits</strong>: Qubit 수는 중요하지만, RSA를 깨뜨리는 것은 특정 알고리즘을 실행할 수 있는 능력에 달려 있으며, 단순히 qubit 수에만 의존하지 않습니다</li></ul></li><li><p><strong>결론 도출</strong></p><ul><li>&quot;Harvest now, decrypt later&quot; 전략은 양자 컴퓨터가 RSA와 같은 현대 암호화를 깨뜨릴 수 있을 때를 기다리는 것입니다</li></ul></li></ol><details class="hint-container details"><summary>최종 답안</summary><p><strong>B. Quantum computers break modern encryption like RSA. (양자 컴퓨터가 RSA와 같은 현대 암호화를 깨뜨릴 때)</strong></p><p>&quot;Harvest now, decrypt later (지금 수확, 나중에 해독)&quot; 전략은 사이버 범죄자가 오늘 암호화된 데이터를 수집하고, 양자 컴퓨터가 RSA와 같은 현대 암호화를 깨뜨릴 수 있을 때까지 저장한 후 해독하는 전략입니다. Quantum computer (양자 컴퓨터)가 성숙해짐에 따라, 현대 사이버 보안이 의존하는 classical encryption algorithm (고전 암호화 알고리즘)에 도전을 제시할 것입니다. Shor&#39;s algorithm (쇼어 알고리즘)은 RSA 암호를 해독할 수 있으며, 1994년 Peter Shor가 완벽하게 작동하는 quantum computer (양자 컴퓨터)가 RSA 암호를 해독할 수 있음을 증명했습니다. 따라서 사이버 범죄자는 양자 컴퓨터가 현대 암호화를 깨뜨릴 수 있을 때를 기다리며 데이터를 수집하고 저장합니다.</p></details><h2 id="문제-8-현대-양자-컴퓨터의-특성과-오류-처리" tabindex="-1"><a class="header-anchor" href="#문제-8-현대-양자-컴퓨터의-특성과-오류-처리"><span>문제 8: 현대 양자 컴퓨터의 특성과 오류 처리</span></a></h2><div class="hint-container tip"><p class="hint-container-title">문제 제시</p><p>다음 중 올바르게 문장을 완성하는 것은 무엇인가?</p><p>Which of the following words correctly complete the statement: &quot;Modern quantum computers are ________________, which requires that we use ________________.&quot;</p><p>(현대 양자 컴퓨터는 ________________이며, 이는 우리가 ________________을 사용해야 함을 요구합니다)</p><ul><li>A. noisy, error mitigation (잡음이 있는, 오류 완화)</li><li>B. noisy, variational algorithms (잡음이 있는, 변분 알고리즘)</li><li>C. fault-tolerant, error correction (내결함성, 오류 수정)</li><li>D. fault-tolerant, error mitigation (내결함성, 오류 완화)</li></ul></div><h3 id="필요한-기반-지식-7" tabindex="-1"><a class="header-anchor" href="#필요한-기반-지식-7"><span>필요한 기반 지식</span></a></h3><h4 id="_1-현대-양자-컴퓨터의-특성-noisy-잡음이-있는" tabindex="-1"><a class="header-anchor" href="#_1-현대-양자-컴퓨터의-특성-noisy-잡음이-있는"><span>1. 현대 양자 컴퓨터의 특성: Noisy (잡음이 있는)</span></a></h4><p><strong>Noisy Quantum Devices (잡음이 있는 양자 장치):</strong></p><ul><li>현대 양자 컴퓨터는 <strong>noisy (잡음이 있는)</strong> 상태입니다</li><li>Qubit (큐비트)는 환경과의 상호작용으로 인해 오류가 발생합니다</li><li>Decoherence (결맞음 상실), gate error (게이트 오류), measurement error (측정 오류) 등이 발생합니다</li></ul><p><strong>오류의 원인:</strong></p><ul><li><strong>Decoherence (결맞음 상실)</strong>: Qubit (큐비트)가 환경과 상호작용하여 양자 상태를 잃는 현상</li><li><strong>Gate error (게이트 오류)</strong>: Gate (게이트) 연산이 완벽하게 수행되지 않는 경우</li><li><strong>Measurement error (측정 오류)</strong>: Qubit (큐비트) 상태를 측정할 때 발생하는 오류</li><li><strong>Crosstalk (크로스토크)</strong>: 인접한 qubit (큐비트) 간의 원치 않는 상호작용</li></ul><p><strong>현재 상태:</strong></p><ul><li>UC Berkeley와의 작업은 <strong>fault tolerance (오류 허용) 시대 이전에</strong> 의미 있는 계산과 현실적인 애플리케이션을 탐색하기 위해 현재 사용 가능한 Quantum processor (양자 프로세서)의 힘을 입증합니다</li><li>이것은 현대 양자 컴퓨터가 아직 fault-tolerant (내결함성)가 아니라는 것을 의미합니다</li></ul><h4 id="_2-fault-tolerant-내결함성-vs-noisy-잡음이-있는" tabindex="-1"><a class="header-anchor" href="#_2-fault-tolerant-내결함성-vs-noisy-잡음이-있는"><span>2. Fault-Tolerant (내결함성) vs Noisy (잡음이 있는)</span></a></h4><p><strong>Fault-Tolerant (내결함성):</strong></p><ul><li><strong>정의</strong>: 오류가 발생해도 올바른 결과를 얻을 수 있는 시스템</li><li><strong>현재 상태</strong>: 아직 달성되지 않은 미래의 목표입니다</li><li><strong>목표</strong>: Quantum error correction (양자 오류 수정)을 통해 내결함성 quantum computer (양자 컴퓨터)를 구축하는 것이 목표입니다</li></ul><p><strong>Noisy (잡음이 있는):</strong></p><ul><li><strong>정의</strong>: 오류가 발생하는 현재의 양자 컴퓨터 상태</li><li><strong>현재 상태</strong>: 모든 현대 양자 컴퓨터는 noisy (잡음이 있는) 상태입니다</li><li><strong>대응</strong>: Error mitigation (오류 완화)을 사용하여 오류의 영향을 줄입니다</li></ul><h4 id="_3-error-mitigation-오류-완화-vs-error-correction-오류-수정" tabindex="-1"><a class="header-anchor" href="#_3-error-mitigation-오류-완화-vs-error-correction-오류-수정"><span>3. Error Mitigation (오류 완화) vs Error Correction (오류 수정)</span></a></h4><p><strong>Error Mitigation (오류 완화):</strong></p><ul><li><strong>정의</strong>: 오류의 영향을 줄이기 위한 기술입니다</li><li><strong>특징</strong>: <ul><li>고전 컴퓨터를 활용한 오류 보정입니다</li><li>완벽한 오류 제거가 아닌 오류의 영향을 완화합니다</li><li>현재 noisy (잡음이 있는) 양자 컴퓨터에서 사용됩니다</li></ul></li><li><strong>사용 시기</strong>: Fault tolerance (오류 허용) 시대 이전, 즉 현재입니다</li></ul><p><strong>Error Correction (오류 수정):</strong></p><ul><li><strong>정의</strong>: 오류를 완전히 수정하는 기술입니다</li><li><strong>특징</strong>: <ul><li>Quantum error correction (양자 오류 수정)은 quantum computer (양자 컴퓨터)의 실용화를 위한 핵심 기술입니다</li><li>내결함성(fault-tolerant) quantum computer (양자 컴퓨터)를 구축하는 것이 목표입니다</li><li>아직 실현되지 않은 미래의 기술입니다</li></ul></li><li><strong>사용 시기</strong>: Fault-tolerant (내결함성) 시스템에서 사용됩니다</li></ul><h4 id="_4-variational-algorithms-변분-알고리즘" tabindex="-1"><a class="header-anchor" href="#_4-variational-algorithms-변분-알고리즘"><span>4. Variational Algorithms (변분 알고리즘)</span></a></h4><p><strong>정의:</strong></p><ul><li>Variational algorithms (변분 알고리즘)은 양자-고전 하이브리드 알고리즘의 한 유형입니다</li><li>양자 컴퓨터와 고전 컴퓨터를 결합하여 사용합니다</li><li>하지만 이것은 오류 처리 방법이 아니라 알고리즘 유형입니다</li></ul><p><strong>특징:</strong></p><ul><li>Noisy (잡음이 있는) 양자 컴퓨터에서도 사용할 수 있습니다</li><li>하지만 &quot;noisy&quot;에 대한 직접적인 대응책은 아닙니다</li><li>Error mitigation (오류 완화)과 함께 사용될 수 있습니다</li></ul><h4 id="_5-현재-양자-컴퓨팅의-실용적-접근" tabindex="-1"><a class="header-anchor" href="#_5-현재-양자-컴퓨팅의-실용적-접근"><span>5. 현재 양자 컴퓨팅의 실용적 접근</span></a></h4><p><strong>Fault Tolerance 이전의 활용:</strong></p><ul><li>UC Berkeley와의 작업은 fault tolerance (오류 허용) 시대 이전에 의미 있는 계산과 현실적인 애플리케이션을 탐색하기 위해 현재 사용 가능한 Quantum processor (양자 프로세서)의 힘을 입증합니다</li><li>이것은 noisy (잡음이 있는) 양자 컴퓨터를 error mitigation (오류 완화)과 함께 사용할 수 있음을 보여줍니다</li></ul><p><strong>Error Mitigation의 역할:</strong></p><ul><li>Error mitigation (오류 완화)은 고전 컴퓨터를 활용한 오류 보정입니다</li><li>Quantum-classical integration (양자-고전 통합)의 일부입니다</li><li>현재 noisy (잡음이 있는) 양자 컴퓨터에서 실용적인 결과를 얻기 위해 필수적입니다</li></ul><h3 id="풀이-과정-7" tabindex="-1"><a class="header-anchor" href="#풀이-과정-7"><span>풀이 과정</span></a></h3><ol><li><p><strong>현대 양자 컴퓨터의 현재 상태 확인</strong></p><ul><li>현대 양자 컴퓨터는 <strong>noisy (잡음이 있는)</strong> 상태입니다</li><li>Fault-tolerant (내결함성)는 아직 달성되지 않은 미래의 목표입니다</li><li>UC Berkeley와의 작업은 fault tolerance (오류 허용) 시대 이전에 의미 있는 계산을 탐색합니다</li></ul></li><li><p><strong>오류 처리 방법 확인</strong></p><ul><li><strong>Error mitigation (오류 완화)</strong>: 현재 noisy (잡음이 있는) 양자 컴퓨터에서 사용됩니다</li><li><strong>Error correction (오류 수정)</strong>: Fault-tolerant (내결함성) 시스템에서 사용되며, 아직 실현되지 않았습니다</li></ul></li><li><p><strong>각 옵션 분석</strong></p><ul><li><strong>A. noisy, error mitigation</strong>: 현대 양자 컴퓨터는 noisy (잡음이 있는) 상태이며, error mitigation (오류 완화)을 사용합니다. 이것이 정확한 답입니다.</li><li><strong>B. noisy, variational algorithms</strong>: 현대 양자 컴퓨터는 noisy (잡음이 있는) 상태이지만, variational algorithms (변분 알고리즘)은 오류 처리 방법이 아니라 알고리즘 유형입니다.</li><li><strong>C. fault-tolerant, error correction</strong>: 현대 양자 컴퓨터는 아직 fault-tolerant (내결함성)가 아니며, error correction (오류 수정)은 미래의 기술입니다.</li><li><strong>D. fault-tolerant, error mitigation</strong>: 현대 양자 컴퓨터는 아직 fault-tolerant (내결함성)가 아닙니다.</li></ul></li><li><p><strong>결론 도출</strong></p><ul><li>현대 양자 컴퓨터는 noisy (잡음이 있는) 상태이며, error mitigation (오류 완화)을 사용해야 합니다</li></ul></li></ol><details class="hint-container details"><summary>최종 답안</summary><p><strong>A. noisy, error mitigation (잡음이 있는, 오류 완화)</strong></p><p>현대 양자 컴퓨터는 <strong>noisy (잡음이 있는)</strong> 상태이며, 이는 우리가 <strong>error mitigation (오류 완화)</strong>을 사용해야 함을 요구합니다. UC Berkeley와의 작업은 fault tolerance (오류 허용) 시대 이전에 의미 있는 계산과 현실적인 애플리케이션을 탐색하기 위해 현재 사용 가능한 Quantum processor (양자 프로세서)의 힘을 입증합니다. Error mitigation (오류 완화)은 고전 컴퓨터를 활용한 오류 보정으로, 현재 noisy (잡음이 있는) 양자 컴퓨터에서 실용적인 결과를 얻기 위해 필수적입니다. 반면, fault-tolerant (내결함성)와 error correction (오류 수정)은 아직 달성되지 않은 미래의 목표입니다.</p></details><h2 id="문제-9-양자-생태계의-구성원" tabindex="-1"><a class="header-anchor" href="#문제-9-양자-생태계의-구성원"><span>문제 9: 양자 생태계의 구성원</span></a></h2><div class="hint-container tip"><p class="hint-container-title">문제 제시</p><p>다음 진술이 참인지 거짓인지 선택하세요:</p><p>&quot;Since quantum computers have not yet reached quantum advantage for commercial applications, the only relevant members of a quantum ecosystem are universities and research labs.&quot;</p><p>(양자 컴퓨터가 아직 상업적 애플리케이션에서 양자 우위에 도달하지 않았기 때문에, 양자 생태계의 관련 구성원은 대학과 연구소뿐입니다)</p><ul><li>A. True (참)</li><li>B. False (거짓)</li></ul></div><h3 id="필요한-기반-지식-8" tabindex="-1"><a class="header-anchor" href="#필요한-기반-지식-8"><span>필요한 기반 지식</span></a></h3><h4 id="_1-quantum-ecosystem-양자-생태계-의-구성원" tabindex="-1"><a class="header-anchor" href="#_1-quantum-ecosystem-양자-생태계-의-구성원"><span>1. Quantum Ecosystem (양자 생태계)의 구성원</span></a></h4><p><strong>다양한 구성원:</strong></p><ul><li>Quantum ecosystem (양자 생태계)는 대학과 연구소뿐만 아니라 다양한 조직으로 구성됩니다</li><li>IBM Quantum Network의 250개 이상의 파트너에는 <strong>Fortune 500 기업, 대학, 연구소 및 스타트업</strong>이 포함되어 있습니다</li><li>모두 quantum economy (양자 경제)를 구축하는 데 도움을 주고 있습니다</li></ul><p><strong>기업의 참여:</strong></p><ul><li>많은 기업들이 이미 Quantum Computing (양자 컴퓨팅)을 탐색하고 있습니다</li><li>JPMorgan Chase, Goldman Sachs, PayPal, HSBC와 같은 금융 기업</li><li>Daimler Mercedes-Benz와 같은 자동차 기업</li><li>ExxonMobil, bp와 같은 에너지 기업</li><li>Cleveland Clinic, Amgen과 같은 헬스케어 및 생명과학 기업</li><li>Mitsubishi Chemical과 같은 화학 기업</li></ul><h4 id="_2-quantum-advantage-양자-우위-이전의-활동" tabindex="-1"><a class="header-anchor" href="#_2-quantum-advantage-양자-우위-이전의-활동"><span>2. Quantum Advantage (양자 우위) 이전의 활동</span></a></h4><p><strong>현재 상태:</strong></p><ul><li>Quantum computer (양자 컴퓨터)가 아직 상업적 애플리케이션에서 quantum advantage (양자 우위)에 도달하지 않았더라도, 기업들은 이미 활동하고 있습니다</li><li>UC Berkeley와의 작업은 fault tolerance (오류 허용) 시대 이전에 의미 있는 계산과 현실적인 애플리케이션을 탐색하기 위해 현재 사용 가능한 Quantum processor (양자 프로세서)의 힘을 입증합니다</li></ul><p><strong>조기 참여의 중요성:</strong></p><ul><li>지금 뛰어들어 quantum ready (양자 준비)가 되는 조직은 이러한 기술이 발전함에 따라 뚜렷한 이점을 가질 것입니다</li><li>Quantum Computing (양자 컴퓨팅)은 학습 곡선이 가파르기 때문에, 조기에 학습하고 실험하는 것이 경쟁 우위로 이어질 수 있습니다</li></ul><h4 id="_3-ibm-quantum-network의-사명" tabindex="-1"><a class="header-anchor" href="#_3-ibm-quantum-network의-사명"><span>3. IBM Quantum Network의 사명</span></a></h4><p><strong>세 가지 주요 사명:</strong></p><ol><li><strong>Accelerate research (연구 가속화)</strong> – Quantum Computing (양자 컴퓨팅) 기술을 발전시키기 위해 선도적인 학술 및 연구 조직과 협력합니다</li><li><strong>Educate and prepare (교육 및 준비)</strong> – Quantum Computing (양자 컴퓨팅)의 채택 및 확장에 필수적인 사용자, 개발자 및 애플리케이션 전문가의 생태계를 확장하고 훈련합니다</li><li><strong>Develop and launch commercial applications (상업적 애플리케이션 개발 및 출시)</strong> – 산업 리더와 협력하여 IBM Quantum Computing (양자 컴퓨팅) 전문성과 산업별 전문성을 결합하여 첫 번째 상업적 사용 사례의 개발을 가속화합니다</li></ol><p><strong>핵심 포인트:</strong></p><ul><li>세 번째 사명은 명확히 <strong>산업 리더</strong>와의 협력을 언급합니다</li><li>이것은 대학과 연구소뿐만 아니라 기업도 양자 생태계의 중요한 구성원임을 보여줍니다</li></ul><h4 id="_4-quantum-ecosystem-양자-생태계-확장" tabindex="-1"><a class="header-anchor" href="#_4-quantum-ecosystem-양자-생태계-확장"><span>4. Quantum Ecosystem (양자 생태계) 확장</span></a></h4><p><strong>개방형 혁신:</strong></p><ul><li>개방형 혁신은 협력적 학습을 촉진합니다</li><li>실무자와 과학자는 Quantum Computing (양자 컴퓨팅)을 실제 문제에 적용할 수 있도록 훈련받아야 합니다</li><li>물리학자와 엔지니어는 특정 분야 전문 지식을 바탕으로 하드웨어와 소프트웨어를 개발할 수 있어야 합니다</li></ul><p><strong>다양한 참여자:</strong></p><ul><li><strong>대학 및 연구소</strong>: 연구와 교육을 담당합니다</li><li><strong>기업</strong>: 실제 문제에 양자 컴퓨팅을 적용하고 상업적 사용 사례를 개발합니다</li><li><strong>스타트업</strong>: 혁신적인 솔루션과 새로운 접근 방식을 제공합니다</li><li><strong>시스템 통합업체 및 컨설팅 회사</strong>: 기업이 양자 컴퓨팅을 채택하는 것을 돕습니다</li><li><strong>Quantum Innovation Center (양자 혁신 센터)</strong>: 엘리트 전문성 센터 역할을 합니다</li></ul><h4 id="_5-실제-기업-참여-사례" tabindex="-1"><a class="header-anchor" href="#_5-실제-기업-참여-사례"><span>5. 실제 기업 참여 사례</span></a></h4><p><strong>금융 서비스:</strong></p><ul><li>JPMorgan Chase: 금융 옵션의 가격을 예측하고 사기 탐지 및 신용도 결정을 개선</li><li>PayPal: 사기 탐지, 신용 리스크 운영 및 전체 보안 태세에 Quantum Computing (양자 컴퓨팅) 사용</li><li>HSBC: 가격 및 포트폴리오 최적화, 순 제로 목표 달성</li></ul><p><strong>제조업:</strong></p><ul><li>Daimler Mercedes-Benz: 운송 물류 및 차량 배터리의 화학을 최적화</li><li>Mitsubishi Chemical: OLED 재료의 분자 구조를 모델링하고 분석</li></ul><p><strong>에너지:</strong></p><ul><li>ExxonMobil: 열역학적 관측 가능량을 정확하게 계산</li><li>bp: 순 제로 목표 달성</li><li>E.ON: 분산 에너지 인프라를 최적화</li></ul><p><strong>헬스케어:</strong></p><ul><li>Cleveland Clinic: 헬스케어 및 생명과학에서 발견의 속도를 발전</li><li>Amgen: 인구 건강 모델링을 위한 quantum machine learning (양자 머신러닝) 탐색</li></ul><h3 id="풀이-과정-8" tabindex="-1"><a class="header-anchor" href="#풀이-과정-8"><span>풀이 과정</span></a></h3><ol><li><p><strong>Quantum Ecosystem (양자 생태계)의 구성원 확인</strong></p><ul><li>IBM Quantum Network의 250개 이상의 파트너에는 Fortune 500 기업, 대학, 연구소 및 스타트업이 포함되어 있습니다</li><li>대학과 연구소뿐만 아니라 다양한 기업들도 포함됩니다</li></ul></li><li><p><strong>Quantum Advantage 이전의 활동 확인</strong></p><ul><li>Quantum advantage (양자 우위)에 도달하지 않았더라도, 많은 기업들이 이미 양자 컴퓨팅을 탐색하고 있습니다</li><li>UC Berkeley와의 작업은 fault tolerance (오류 허용) 시대 이전에 의미 있는 계산을 탐색합니다</li></ul></li><li><p><strong>IBM Quantum Network의 사명 확인</strong></p><ul><li>세 번째 사명은 &quot;상업적 애플리케이션 개발 및 출시&quot;로, 산업 리더와의 협력을 명시합니다</li><li>이것은 기업이 양자 생태계의 중요한 구성원임을 보여줍니다</li></ul></li><li><p><strong>실제 기업 참여 사례 확인</strong></p><ul><li>많은 Fortune 500 기업들이 이미 양자 컴퓨팅을 탐색하고 있습니다</li><li>다양한 산업 분야에서 양자 사용 사례를 개발하고 있습니다</li></ul></li><li><p><strong>결론 도출</strong></p><ul><li>양자 생태계는 대학과 연구소뿐만 아니라 기업, 스타트업, 시스템 통합업체 등 다양한 구성원으로 이루어져 있습니다</li><li>Quantum advantage (양자 우위)에 도달하지 않았더라도, 기업들은 이미 양자 컴퓨팅을 탐색하고 있습니다</li></ul></li></ol><details class="hint-container details"><summary>최종 답안</summary><p><strong>B. False</strong></p><p>양자 생태계는 대학과 연구소뿐만 아니라 다양한 구성원으로 이루어져 있습니다. IBM Quantum Network의 250개 이상의 파트너에는 Fortune 500 기업, 대학, 연구소 및 스타트업이 포함되어 있으며, 모두 quantum economy (양자 경제)를 구축하는 데 도움을 주고 있습니다. IBM Quantum Network의 사명 중 하나는 &quot;상업적 애플리케이션 개발 및 출시&quot;로, 산업 리더와 협력하여 첫 번째 상업적 사용 사례의 개발을 가속화하는 것입니다. Quantum advantage (양자 우위)에 도달하지 않았더라도, 많은 기업들(JPMorgan Chase, Goldman Sachs, Daimler Mercedes-Benz, ExxonMobil 등)이 이미 양자 컴퓨팅을 탐색하고 있으며, UC Berkeley와의 작업은 fault tolerance (오류 허용) 시대 이전에 의미 있는 계산과 현실적인 애플리케이션을 탐색하기 위해 현재 사용 가능한 Quantum processor (양자 프로세서)의 힘을 입증합니다. 따라서 양자 생태계의 관련 구성원은 대학과 연구소뿐만 아니라 기업, 스타트업, 시스템 통합업체 등 다양한 조직을 포함합니다.</p></details><h2 id="문제-10-양자-컴퓨터-성능-측정-지표" tabindex="-1"><a class="header-anchor" href="#문제-10-양자-컴퓨터-성능-측정-지표"><span>문제 10: 양자 컴퓨터 성능 측정 지표</span></a></h2><div class="hint-container tip"><p class="hint-container-title">문제 제시</p><p>다음 진술이 참인지 거짓인지 선택하세요:</p><p>&quot;To measure the performance of how good a quantum computer is, you only need to look at the qubit count.&quot;</p><p>(양자 컴퓨터가 얼마나 좋은지 성능을 측정하려면, qubit count (큐비트 수)만 보면 됩니다)</p><ul><li>A. False (거짓)</li><li>B. True (참)</li></ul></div><h3 id="필요한-기반-지식-9" tabindex="-1"><a class="header-anchor" href="#필요한-기반-지식-9"><span>필요한 기반 지식</span></a></h3><h4 id="_1-qubit-count-큐비트-수-의-역할과-한계" tabindex="-1"><a class="header-anchor" href="#_1-qubit-count-큐비트-수-의-역할과-한계"><span>1. Qubit Count (큐비트 수)의 역할과 한계</span></a></h4><p><strong>Qubit Count (큐비트 수)의 역할:</strong></p><ul><li>Qubit (큐비트)의 수는 quantum computer (양자 컴퓨터)가 처리할 수 있는 정보의 양을 결정합니다</li><li>더 많은 qubit (큐비트)는 더 큰 양자 상태 공간을 의미합니다</li><li>Qubit count (큐비트 수)는 양자 컴퓨터 성능의 기본 요소입니다</li></ul><p><strong>Qubit Count (큐비트 수)의 한계:</strong></p><ul><li><strong>Qubit (큐비트) 수만으로는 성능을 완전히 평가할 수 없습니다</strong></li><li>많은 qubit (큐비트)를 가지고 있어도 오류율이 높으면 실제 성능이 낮을 수 있습니다</li><li>Qubit (큐비트) 간의 연결성이 낮으면 복잡한 연산을 수행하기 어렵습니다</li><li>Qubit (큐비트)의 품질이 낮으면 많은 qubit (큐비트)를 가져도 유용하지 않을 수 있습니다</li></ul><h4 id="_2-quantum-system-양자-시스템-의-성능-지표" tabindex="-1"><a class="header-anchor" href="#_2-quantum-system-양자-시스템-의-성능-지표"><span>2. Quantum System (양자 시스템)의 성능 지표</span></a></h4><p><strong>다양한 성능 지표:</strong></p><p><strong>1. Qubit Count (큐비트 수)</strong></p><ul><li>Quantum computer (양자 컴퓨터)가 처리할 수 있는 정보의 양을 결정합니다</li><li>하지만 이것만으로는 성능을 완전히 평가할 수 없습니다</li></ul><p><strong>2. Coherence Time (결맞음 시간)</strong></p><ul><li>Qubit (큐비트)가 quantum state (양자 상태)를 유지할 수 있는 시간입니다</li><li>이 시간이 길수록 더 복잡한 연산을 수행할 수 있습니다</li><li>짧은 coherence time (결맞음 시간)은 깊은 회로를 실행할 수 없게 만듭니다</li></ul><p><strong>3. Gate Fidelity (게이트 충실도)</strong></p><ul><li>Gate (게이트) 연산이 얼마나 정확하게 수행되는지를 나타냅니다</li><li>높은 fidelity (충실도)는 더 정확한 계산 결과를 의미합니다</li><li>낮은 fidelity (충실도)는 오류가 누적되어 결과를 신뢰할 수 없게 만듭니다</li></ul><p><strong>4. Error Rate (오류율)</strong></p><ul><li>연산 중 발생하는 오류의 비율입니다</li><li>낮은 error rate (오류율)은 더 신뢰할 수 있는 결과를 의미합니다</li><li>높은 error rate (오류율)은 많은 qubit (큐비트)를 가져도 실용적이지 않게 만듭니다</li></ul><p><strong>5. Qubit Connectivity (큐비트 연결성)</strong></p><ul><li>Qubit (큐비트) 간의 물리적 연결 구조입니다</li><li>높은 connectivity (연결성)은 더 복잡한 양자 회로를 구현할 수 있게 합니다</li><li>낮은 connectivity (연결성)은 더 많은 gate (게이트)가 필요하여 오류가 누적될 수 있습니다</li></ul><h4 id="_3-quantum-volume-양자-볼륨-의-중요성" tabindex="-1"><a class="header-anchor" href="#_3-quantum-volume-양자-볼륨-의-중요성"><span>3. Quantum Volume (양자 볼륨)의 중요성</span></a></h4><p><strong>종합적 평가 지표:</strong></p><ul><li>Quantum volume (양자 볼륨)은 quantum computer (양자 컴퓨터)의 전체 성능을 종합적으로 평가하는 지표입니다</li><li>Qubit (큐비트) 수, gate fidelity (게이트 충실도), connectivity (연결성) 등을 종합적으로 고려합니다</li><li>단순히 qubit count (큐비트 수)만으로는 양자 컴퓨터의 실제 성능을 평가할 수 없기 때문에 도입되었습니다</li></ul><p><strong>Quantum Volume (양자 볼륨)의 목적:</strong></p><ul><li>다양한 양자 컴퓨터의 성능을 공정하게 비교할 수 있도록 합니다</li><li>하드웨어의 실제 성능을 더 정확하게 반영합니다</li><li>양자 컴퓨터의 발전을 추적하는 표준 지표로 사용됩니다</li></ul><h4 id="_4-qubit-count-큐비트-수-만으로-평가할-때의-문제점" tabindex="-1"><a class="header-anchor" href="#_4-qubit-count-큐비트-수-만으로-평가할-때의-문제점"><span>4. Qubit Count (큐비트 수)만으로 평가할 때의 문제점</span></a></h4><p><strong>예시 시나리오:</strong></p><ul><li><strong>시나리오 1</strong>: 1000개의 qubit (큐비트)를 가진 양자 컴퓨터가 있지만, gate error rate (게이트 오류율)이 매우 높습니다. 이 경우 많은 qubit (큐비트)를 가져도 실제로는 유용한 계산을 수행할 수 없을 수 있습니다.</li><li><strong>시나리오 2</strong>: 100개의 qubit (큐비트)를 가진 양자 컴퓨터가 있지만, gate fidelity (게이트 충실도)가 매우 높고 connectivity (연결성)가 좋습니다. 이 경우 더 적은 qubit (큐비트)를 가져도 더 나은 성능을 발휘할 수 있습니다.</li></ul><p><strong>핵심 포인트:</strong></p><ul><li>Qubit count (큐비트 수)는 양자 컴퓨터 성능의 한 측면일 뿐입니다</li><li>실제 성능은 qubit count (큐비트 수), gate fidelity (게이트 충실도), connectivity (연결성), coherence time (결맞음 시간) 등을 종합적으로 고려해야 합니다</li></ul><h4 id="_5-실제-성능-평가의-필요성" tabindex="-1"><a class="header-anchor" href="#_5-실제-성능-평가의-필요성"><span>5. 실제 성능 평가의 필요성</span></a></h4><p><strong>종합적 접근:</strong></p><ul><li>Quantum system (양자 시스템)의 성능은 qubit count (큐비트 수), coherence time (결맞음 시간), gate fidelity (게이트 충실도) 등으로 평가됩니다</li><li>Quantum Volume (양자 볼륨)과 같은 종합적인 지표를 사용해야 합니다</li><li>실제 문제를 해결할 수 있는 능력을 평가해야 합니다</li></ul><h3 id="풀이-과정-9" tabindex="-1"><a class="header-anchor" href="#풀이-과정-9"><span>풀이 과정</span></a></h3><ol><li><p><strong>Qubit Count (큐비트 수)의 역할과 한계 확인</strong></p><ul><li>Qubit (큐비트)의 수는 quantum computer (양자 컴퓨터)가 처리할 수 있는 정보의 양을 결정합니다</li><li>하지만 qubit (큐비트) 수만으로는 성능을 완전히 평가할 수 없습니다</li></ul></li><li><p><strong>다양한 성능 지표 확인</strong></p><ul><li>Coherence time (결맞음 시간), Gate fidelity (게이트 충실도), Error rate (오류율), Qubit connectivity (큐비트 연결성) 등도 중요합니다</li><li>Quantum Volume (양자 볼륨)은 이러한 요소들을 종합적으로 고려합니다</li></ul></li><li><p><strong>Qubit Count만으로 평가할 때의 문제점</strong></p><ul><li>많은 qubit (큐비트)를 가져도 오류율이 높으면 실제 성능이 낮을 수 있습니다</li><li>적은 qubit (큐비트)를 가져도 높은 fidelity (충실도)와 좋은 connectivity (연결성)을 가지면 더 나은 성능을 발휘할 수 있습니다</li></ul></li><li><p><strong>결론 도출</strong></p><ul><li>양자 컴퓨터의 성능을 측정하려면 qubit count (큐비트 수)뿐만 아니라 다양한 지표를 종합적으로 고려해야 합니다</li><li>Quantum Volume (양자 볼륨)과 같은 종합적인 지표를 사용해야 합니다</li></ul></li></ol><details class="hint-container details"><summary>최종 답안</summary><p><strong>A. False</strong></p><p>양자 컴퓨터의 성능을 측정하려면 qubit count (큐비트 수)만으로는 충분하지 않습니다. Qubit (큐비트)의 수는 quantum computer (양자 컴퓨터)가 처리할 수 있는 정보의 양을 결정하지만, qubit (큐비트) 수만으로는 성능을 완전히 평가할 수 없습니다. Quantum system (양자 시스템)의 성능은 qubit count (큐비트 수), coherence time (결맞음 시간), gate fidelity (게이트 충실도), error rate (오류율), qubit connectivity (큐비트 연결성) 등을 종합적으로 고려해야 합니다. Quantum Volume (양자 볼륨)은 이러한 요소들을 종합적으로 고려하는 지표로, qubit (큐비트) 수, gate fidelity (게이트 충실도), connectivity (연결성) 등을 종합적으로 평가합니다. 많은 qubit (큐비트)를 가져도 오류율이 높거나 연결성이 낮으면 실제 성능이 낮을 수 있으며, 반대로 적은 qubit (큐비트)를 가져도 높은 fidelity (충실도)와 좋은 connectivity (연결성)을 가지면 더 나은 성능을 발휘할 수 있습니다.</p></details><h2 id="문제-11-양자-컴퓨팅의-상대적-잠재적-힘" tabindex="-1"><a class="header-anchor" href="#문제-11-양자-컴퓨팅의-상대적-잠재적-힘"><span>문제 11: 양자 컴퓨팅의 상대적 잠재적 힘</span></a></h2><div class="hint-container tip"><p class="hint-container-title">문제 제시</p><p>다음 중 양자 컴퓨팅의 상대적 잠재적 힘을 가장 잘 반영하는 진술은 무엇입니까?</p><p>Which of the following statements best reflects the relative potential power of quantum computing?</p><ul><li>A. Quantum computing is less powerful than classical probabilistic computing. (양자 컴퓨팅은 고전 확률적 컴퓨팅보다 덜 강력합니다)</li><li>B. Quantum computing is more powerful than classical probabilistic computing for many problems, but is still weaker than exponential classical parallelism. (양자 컴퓨팅은 많은 문제에서 고전 확률적 컴퓨팅보다 강력하지만, 지수적 고전 병렬 처리보다는 여전히 약합니다)</li><li>C. Quantum computing is basically the same as exponential classical parallelism. (양자 컴퓨팅은 기본적으로 지수적 고전 병렬 처리와 같습니다)</li><li>D. Quantum computing is basically the same as probabilistic classical computing. (양자 컴퓨팅은 기본적으로 확률적 고전 컴퓨팅과 같습니다)</li></ul></div><h3 id="필요한-기반-지식-10" tabindex="-1"><a class="header-anchor" href="#필요한-기반-지식-10"><span>필요한 기반 지식</span></a></h3><h4 id="_1-quantum-computing-양자-컴퓨팅-의-고유한-힘" tabindex="-1"><a class="header-anchor" href="#_1-quantum-computing-양자-컴퓨팅-의-고유한-힘"><span>1. Quantum Computing (양자 컴퓨팅)의 고유한 힘</span></a></h4><p><strong>지수적 중첩 (Exponential Superposition):</strong></p><ul><li>Quantum computer (양자 컴퓨터)는 한 번에 지수적으로 많은 논리적 상태를 허용하는 특별한 종류의 superposition (중첩)을 활용합니다</li><li>이것은 강력한 업적이며, 어떤 classical computer (고전 컴퓨터)도 이를 달성할 수 없습니다</li><li><em>n</em>개의 qubit (큐비트)는 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mi>n</mi></msup></mrow><annotation encoding="application/x-tex">2^n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span>개의 상태를 동시에 중첩할 수 있습니다</li></ul><p><strong>Entanglement (얽힘)의 역할:</strong></p><ul><li>Quantum computation (양자 계산)에 가장 유용한 것들은 entangled (얽혀 있습니다)</li><li>이것은 개별 qubit (큐비트)의 digital (디지털) 또는 analog (아날로그) 상태의 할당에 해당하지 않는 전체 컴퓨터의 상태입니다</li><li>Entanglement (얽힘)는 양자 컴퓨팅의 고유한 힘의 핵심입니다</li></ul><h4 id="_2-classical-probabilistic-computing-고전-확률적-컴퓨팅-과의-비교" tabindex="-1"><a class="header-anchor" href="#_2-classical-probabilistic-computing-고전-확률적-컴퓨팅-과의-비교"><span>2. Classical Probabilistic Computing (고전 확률적 컴퓨팅)과의 비교</span></a></h4><p><strong>Classical Probabilistic Computing (고전 확률적 컴퓨팅)의 한계:</strong></p><ul><li>Classical computer (고전 컴퓨터)는 bit (비트)로 정보를 처리하며, bit (비트)는 0 또는 1의 값을 가질 수 있습니다</li><li>Probabilistic classical computing (확률적 고전 컴퓨팅)은 확률 분포를 사용하지만, 여전히 각 상태를 개별적으로 처리해야 합니다</li><li>지수적으로 많은 상태를 동시에 처리할 수 없습니다</li></ul><p><strong>Quantum Computing (양자 컴퓨팅)의 우위:</strong></p><ul><li>Quantum computer (양자 컴퓨터)는 지수적으로 많은 상태를 동시에 중첩할 수 있습니다</li><li>Entanglement (얽힘)를 통해 상태 간의 상관관계를 활용할 수 있습니다</li><li>많은 문제에서 classical probabilistic computing (고전 확률적 컴퓨팅)보다 강력합니다</li></ul><h4 id="_3-exponential-classical-parallelism-지수적-고전-병렬-처리-과의-비교" tabindex="-1"><a class="header-anchor" href="#_3-exponential-classical-parallelism-지수적-고전-병렬-처리-과의-비교"><span>3. Exponential Classical Parallelism (지수적 고전 병렬 처리)과의 비교</span></a></h4><p><strong>Exponential Classical Parallelism (지수적 고전 병렬 처리)의 개념:</strong></p><ul><li>지수적으로 많은 classical processor (고전 프로세서)를 병렬로 사용하는 것을 의미합니다</li><li>각 processor (프로세서)는 하나의 상태를 처리합니다</li><li>이론적으로는 가능하지만, 실제로는 물리적으로 불가능합니다 (너무 많은 프로세서가 필요함)</li></ul><p><strong>Quantum Computing (양자 컴퓨팅)의 우위:</strong></p><ul><li>Quantum computer (양자 컴퓨터)는 지수적으로 많은 상태를 하나의 시스템에서 동시에 처리할 수 있습니다</li><li>이것은 exponential classical parallelism (지수적 고전 병렬 처리)보다 더 강력합니다</li><li>Quantum computer (양자 컴퓨터)는 지수적으로 많은 논리적 상태를 허용하는 특별한 종류의 superposition (중첩)을 활용하며, 어떤 classical computer (고전 컴퓨터)도 이를 달성할 수 없습니다</li></ul><h4 id="_4-bqp-bounded-error-quantum-polynomial-time-유계-오차-양자-다항-시간" tabindex="-1"><a class="header-anchor" href="#_4-bqp-bounded-error-quantum-polynomial-time-유계-오차-양자-다항-시간"><span>4. BQP (Bounded-error Quantum Polynomial time, 유계 오차 양자 다항 시간)</span></a></h4><p><strong>BQP의 의미:</strong></p><ul><li>BQP는 quantum computer (양자 컴퓨터)가 쉽게 해결할 수 있는 문제 목록입니다</li><li>이것은 양자 컴퓨팅이 해결할 수 있는 문제 클래스를 나타냅니다</li><li>BQP는 classical probabilistic computing (고전 확률적 컴퓨팅)보다 더 넓은 문제 클래스를 포함합니다</li></ul><p><strong>계산 복잡도 클래스:</strong></p><ul><li>BPP (Bounded-error Probabilistic Polynomial time): 확률적 고전 컴퓨팅으로 해결 가능한 문제</li><li>BQP: 양자 컴퓨팅으로 해결 가능한 문제</li><li>BQP는 BPP보다 더 넓은 문제 클래스를 포함합니다</li></ul><h4 id="_5-양자-컴퓨팅의-실제-힘" tabindex="-1"><a class="header-anchor" href="#_5-양자-컴퓨팅의-실제-힘"><span>5. 양자 컴퓨팅의 실제 힘</span></a></h4><p><strong>이론적 우위:</strong></p><ul><li>Quantum computer (양자 컴퓨터)는 지수적으로 많은 논리적 상태를 동시에 처리할 수 있습니다</li><li>이것은 exponential classical parallelism (지수적 고전 병렬 처리)보다 더 강력합니다</li><li>어떤 classical computer (고전 컴퓨터)도 이를 달성할 수 없습니다</li></ul><p><strong>실제 적용:</strong></p><ul><li>Quantum computer (양자 컴퓨터)는 특정 문제에서 classical computer (고전 컴퓨터)보다 상당한 성능 이점을 제공할 수 있습니다</li><li>Quantum computation (양자 계산)이 수백 배 또는 수천 배 더 빠르거나, 메모리의 더 작은 부분만 필요하거나, 불가능해 보이는 것을 가능하게 만들 수 있습니다</li></ul><h3 id="풀이-과정-10" tabindex="-1"><a class="header-anchor" href="#풀이-과정-10"><span>풀이 과정</span></a></h3><ol><li><p><strong>Classical Probabilistic Computing (고전 확률적 컴퓨팅)과의 비교</strong></p><ul><li>Quantum computer (양자 컴퓨터)는 지수적으로 많은 논리적 상태를 동시에 처리할 수 있습니다</li><li>Classical probabilistic computing (고전 확률적 컴퓨팅)은 각 상태를 개별적으로 처리해야 합니다</li><li>따라서 양자 컴퓨팅은 고전 확률적 컴퓨팅보다 강력합니다</li></ul></li><li><p><strong>Exponential Classical Parallelism (지수적 고전 병렬 처리)과의 비교</strong></p><ul><li>Quantum computer (양자 컴퓨터)는 지수적으로 많은 논리적 상태를 하나의 시스템에서 동시에 처리할 수 있습니다</li><li>이것은 exponential classical parallelism (지수적 고전 병렬 처리)보다 더 강력합니다</li><li>Quantum computer (양자 컴퓨터)는 한 번에 지수적으로 많은 논리적 상태를 허용하는 특별한 종류의 superposition (중첩)을 활용하며, 어떤 classical computer (고전 컴퓨터)도 이를 달성할 수 없습니다</li></ul></li><li><p><strong>각 옵션 분석</strong></p><ul><li><strong>A. Quantum computing is less powerful than classical probabilistic computing</strong>: 양자 컴퓨팅은 고전 확률적 컴퓨팅보다 강력하므로 틀렸습니다</li><li><strong>B. Quantum computing is more powerful than classical probabilistic computing for many problems, but is still weaker than exponential classical parallelism</strong>: 양자 컴퓨팅은 지수적 고전 병렬 처리보다 더 강력하므로 틀렸습니다</li><li><strong>C. Quantum computing is basically the same as exponential classical parallelism</strong>: 양자 컴퓨팅은 지수적 고전 병렬 처리보다 더 강력하므로 틀렸습니다</li><li><strong>D. Quantum computing is basically the same as probabilistic classical computing</strong>: 양자 컴퓨팅은 확률적 고전 컴퓨팅보다 강력하므로 틀렸습니다</li></ul></li><li><p><strong>결론 도출</strong></p><ul><li>양자 컴퓨팅은 고전 확률적 컴퓨팅보다 강력합니다</li><li>양자 컴퓨팅은 지수적 고전 병렬 처리보다도 더 강력합니다</li></ul></li></ol><details class="hint-container details"><summary>최종 답안</summary><p><strong>B. Quantum computing is more powerful than classical probabilistic computing for many problems, but is still weaker than exponential classical parallelism.</strong></p><p>Quantum computer (양자 컴퓨터)는 지수적으로 많은 논리적 상태를 동시에 처리할 수 있는 특별한 종류의 superposition (중첩)을 활용하며, 어떤 classical computer (고전 컴퓨터)도 이를 달성할 수 없습니다. 양자 컴퓨팅은 고전 확률적 컴퓨팅보다 강력하며, 지수적 고전 병렬 처리보다도 더 강력합니다. 하지만 주어진 옵션 중에서는 B가 양자 컴퓨팅이 고전 확률적 컴퓨팅보다 강력하다는 점을 인정하는 유일한 옵션이므로, 가장 적절한 답안입니다.</p></details><h2 id="문제-12-responsible-quantum-computing-책임-있는-양자-컴퓨팅-에-따른-행동" tabindex="-1"><a class="header-anchor" href="#문제-12-responsible-quantum-computing-책임-있는-양자-컴퓨팅-에-따른-행동"><span>문제 12: Responsible Quantum Computing (책임 있는 양자 컴퓨팅)에 따른 행동</span></a></h2><div class="hint-container tip"><p class="hint-container-title">문제 제시</p><p>Responsible Quantum Computing (책임 있는 양자 컴퓨팅)에 따라 행동하기 위해 고려해야 할 행동은 무엇입니까? (하나 이상 선택)</p><p>What actions should you consider taking to act in accordance with Responsible QC?</p><ul><li>A. Before deciding on a use case, consider conducting a stakeholder and impact assessment which includes societal stakeholders and consider not choosing a use case with negative societal impact. (사용 사례를 결정하기 전에, 사회적 이해관계자를 포함한 이해관계자 및 영향 평가를 수행하고, 부정적인 사회적 영향을 가진 사용 사례를 선택하지 않는 것을 고려하세요)</li><li>B. Make sure you speak realistically about your expectations from your QC research and about timelines in which you hope to use QC. (QC 연구에 대한 기대와 QC를 사용하기를 희망하는 타임라인에 대해 현실적으로 말하는지 확인하세요)</li><li>C. Before deciding on a use case, consider conducting a stakeholder and impact assessment which includes societal stakeholders and choosing the one with the highest return on investment. (사용 사례를 결정하기 전에, 사회적 이해관계자를 포함한 이해관계자 및 영향 평가를 수행하고, 가장 높은 투자 수익률을 가진 것을 선택하는 것을 고려하세요)</li><li>D. Inform yourselves about responsible and acceptable use clauses. (책임 있는 사용 및 허용 가능한 사용 조항에 대해 스스로 정보를 얻으세요)</li><li>E. Make sure you have defined clear principles and values for your use case exploration and development. (사용 사례 탐색 및 개발을 위한 명확한 원칙과 가치를 정의했는지 확인하세요)</li></ul></div><h3 id="필요한-기반-지식-11" tabindex="-1"><a class="header-anchor" href="#필요한-기반-지식-11"><span>필요한 기반 지식</span></a></h3><h4 id="_1-responsible-quantum-computing-책임-있는-양자-컴퓨팅-의-정의-1" tabindex="-1"><a class="header-anchor" href="#_1-responsible-quantum-computing-책임-있는-양자-컴퓨팅-의-정의-1"><span>1. Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 정의</span></a></h4><p><strong>핵심 개념:</strong></p><ul><li>Responsible Quantum Computing (책임 있는 양자 컴퓨팅)은 그 힘과 잠재적 영향을 인식하면서 Quantum Computing (양자 컴퓨팅)을 개발하는 것입니다</li><li>사용 사례는 비즈니스 가치를 제공하고 그 개념과 실행에 대해 책임져야 합니다</li><li>이것은 단순히 법률 준수나 높은 ROI를 추구하는 것이 아니라, 양자 컴퓨팅의 힘과 영향을 인식하고 잠재적 해를 완화하는 것입니다</li></ul><h4 id="_2-ibm-quantum의-다섯-가지-원칙" tabindex="-1"><a class="header-anchor" href="#_2-ibm-quantum의-다섯-가지-원칙"><span>2. IBM Quantum의 다섯 가지 원칙</span></a></h4><p><strong>원칙 1: 긍정적인 사회적 영향을 만듭니다</strong></p><ul><li>양자 컴퓨팅이 사회에 긍정적인 영향을 미치도록 해야 합니다</li><li>부정적인 사회적 영향을 가진 사용 사례를 선택하지 않는 것을 고려해야 합니다</li><li>이해관계자 및 영향 평가를 수행할 때 사회적 이해관계자를 포함해야 합니다</li></ul><p><strong>원칙 2: 선견지명으로 사용 사례를 탐색합니다</strong></p><ul><li>사용 사례를 선택할 때 미래의 영향을 고려해야 합니다</li><li>단기적인 ROI만 고려하는 것이 아니라 장기적인 영향을 고려해야 합니다</li></ul><p><strong>원칙 3: 제품을 정확하게 홍보합니다</strong></p><ul><li>양자 컴퓨팅에 대한 기대를 현실적으로 표현해야 합니다</li><li>타임라인에 대해 정확하게 말해야 합니다</li><li>과장된 주장을 피해야 합니다</li></ul><p><strong>원칙 4: 일관되고 투명한 원칙적 결정을 내립니다</strong></p><ul><li>사용 사례 탐색 및 개발을 위한 명확한 원칙과 가치를 정의해야 합니다</li><li>이러한 원칙과 가치에 따라 일관되게 결정을 내려야 합니다</li><li>결정 과정을 투명하게 해야 합니다</li></ul><p><strong>원칙 5: 다양하고 포용적인 quantum community (양자 커뮤니티)를 구축합니다</strong></p><ul><li>양자 컴퓨팅 커뮤니티가 다양하고 포용적이어야 합니다</li><li>다양한 배경과 관점을 가진 사람들을 포함해야 합니다</li></ul><h4 id="_3-responsible-use-책임-있는-사용-및-acceptable-use-허용-가능한-사용-조항" tabindex="-1"><a class="header-anchor" href="#_3-responsible-use-책임-있는-사용-및-acceptable-use-허용-가능한-사용-조항"><span>3. Responsible Use (책임 있는 사용) 및 Acceptable Use (허용 가능한 사용) 조항</span></a></h4><p><strong>계약서의 조항:</strong></p><ul><li>IBM Quantum 고객이 quantum computer (양자 컴퓨터)를 책임 있게 사용하도록 요구하는 언어가 있습니다</li><li>악의적이거나 불법적인 목적으로 quantum computer (양자 컴퓨터)를 사용하지 않도록 요구합니다</li><li>이것을 responsible use (책임 있는 사용) 및 acceptable use (허용 가능한 사용) 조항이라고 합니다</li></ul><p><strong>정보 습득의 중요성:</strong></p><ul><li>이러한 조항에 대해 스스로 정보를 얻어야 합니다</li><li>책임 있는 사용을 위해 이러한 조항을 이해하고 준수해야 합니다</li></ul><h4 id="_4-stakeholder-and-impact-assessment-이해관계자-및-영향-평가" tabindex="-1"><a class="header-anchor" href="#_4-stakeholder-and-impact-assessment-이해관계자-및-영향-평가"><span>4. Stakeholder and Impact Assessment (이해관계자 및 영향 평가)</span></a></h4><p><strong>평가의 범위:</strong></p><ul><li>사용 사례를 결정하기 전에 이해관계자 및 영향 평가를 수행해야 합니다</li><li>사회적 이해관계자를 포함해야 합니다</li><li>부정적인 사회적 영향을 가진 사용 사례를 선택하지 않는 것을 고려해야 합니다</li></ul><p><strong>ROI 중심 접근의 문제점:</strong></p><ul><li>가장 높은 ROI를 가진 사용 사례를 선택하는 것만으로는 충분하지 않습니다</li><li>Responsible Quantum Computing (책임 있는 양자 컴퓨팅)은 ROI보다 사회적 영향을 우선시합니다</li><li>단순히 ROI에만 초점을 맞추는 것은 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 정신과 맞지 않습니다</li></ul><h4 id="_5-현실적인-기대와-타임라인" tabindex="-1"><a class="header-anchor" href="#_5-현실적인-기대와-타임라인"><span>5. 현실적인 기대와 타임라인</span></a></h4><p><strong>정확한 홍보:</strong></p><ul><li>양자 컴퓨팅 연구에 대한 기대를 현실적으로 표현해야 합니다</li><li>타임라인에 대해 정확하게 말해야 합니다</li><li>과장된 주장을 피해야 합니다</li></ul><p><strong>신뢰 구축:</strong></p><ul><li>현실적인 기대와 타임라인을 설정하면 신뢰를 구축할 수 있습니다</li><li>과장된 주장은 신뢰를 훼손할 수 있습니다</li></ul><h4 id="_6-명확한-원칙과-가치의-정의" tabindex="-1"><a class="header-anchor" href="#_6-명확한-원칙과-가치의-정의"><span>6. 명확한 원칙과 가치의 정의</span></a></h4><p><strong>원칙과 가치의 중요성:</strong></p><ul><li>사용 사례 탐색 및 개발을 위한 명확한 원칙과 가치를 정의해야 합니다</li><li>이러한 원칙과 가치에 따라 일관되게 결정을 내려야 합니다</li><li>이것은 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 핵심 요소입니다</li></ul><p><strong>일관성과 투명성:</strong></p><ul><li>명확한 원칙과 가치를 정의하면 일관된 결정을 내릴 수 있습니다</li><li>결정 과정을 투명하게 할 수 있습니다</li></ul><h3 id="풀이-과정-11" tabindex="-1"><a class="header-anchor" href="#풀이-과정-11"><span>풀이 과정</span></a></h3><ol><li><p><strong>Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 원칙 확인</strong></p><ul><li>원칙 1: 긍정적인 사회적 영향을 만듭니다</li><li>원칙 2: 선견지명으로 사용 사례를 탐색합니다</li><li>원칙 3: 제품을 정확하게 홍보합니다</li><li>원칙 4: 일관되고 투명한 원칙적 결정을 내립니다</li><li>원칙 5: 다양하고 포용적인 quantum community (양자 커뮤니티)를 구축합니다</li></ul></li><li><p><strong>각 옵션 분석</strong></p><ul><li><strong>A. 이해관계자 및 영향 평가 수행 (사회적 이해관계자 포함) 및 부정적인 사회적 영향을 가진 사용 사례를 선택하지 않는 것을 고려</strong>: 원칙 1번과 일치합니다.</li><li><strong>B. QC 연구에 대한 기대와 타임라인에 대해 현실적으로 말하기</strong>: 원칙 3번과 일치합니다.</li><li><strong>C. 이해관계자 및 영향 평가 수행 (사회적 이해관계자 포함) 및 가장 높은 ROI를 가진 사용 사례를 선택</strong>: ROI에만 초점을 맞추고 있어서 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 정신과 맞지 않습니다.</li><li><strong>D. 책임 있는 사용 및 허용 가능한 사용 조항에 대해 정보 얻기</strong>: 문서에서 명확히 언급된 내용입니다.</li><li><strong>E. 사용 사례 탐색 및 개발을 위한 명확한 원칙과 가치 정의</strong>: 원칙 4번과 일치합니다.</li></ul></li></ol><details class="hint-container details"><summary>최종 답안</summary><p><strong>결론 도출</strong></p><ul><li>A, B, D, E는 모두 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 원칙과 일치합니다</li><li>C는 ROI에만 초점을 맞추고 있어서 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 정신과 맞지 않습니다</li></ul><p><strong>A. Before deciding on a use case, consider conducting a stakeholder and impact assessment which includes societal stakeholders and consider not choosing a use case with negative societal impact.</strong></p><ul><li>이것은 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 원칙 1번 &quot;긍정적인 사회적 영향을 만듭니다&quot;와 일치합니다. 이해관계자 및 영향 평가를 수행할 때 사회적 이해관계자를 포함하고, 부정적인 사회적 영향을 가진 사용 사례를 선택하지 않는 것을 고려하는 것은 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 핵심 요소입니다.</li></ul><p><strong>B. Make sure you speak realistically about your expectations from your QC research and about timelines in which you hope to use QC.</strong></p><ul><li>이것은 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 원칙 3번 &quot;제품을 정확하게 홍보합니다&quot;와 일치합니다. 양자 컴퓨팅 연구에 대한 기대와 타임라인에 대해 현실적으로 말하는 것은 신뢰를 구축하고 과장된 주장을 피하는 데 중요합니다.</li></ul><p><strong>D. Inform yourselves about responsible and acceptable use clauses.</strong></p><ul><li>문서에서 명확히 언급된 내용입니다. IBM Quantum 고객이 quantum computer (양자 컴퓨터)를 책임 있게 사용하고, 악의적이거나 불법적인 목적으로 사용하지 않도록 요구하는 responsible use (책임 있는 사용) 및 acceptable use (허용 가능한 사용) 조항에 대해 스스로 정보를 얻는 것은 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)에 따라 행동하는 데 필수적입니다.</li></ul><p><strong>E. Make sure you have defined clear principles and values for your use case exploration and development.</strong></p><ul><li>이것은 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 원칙 4번 &quot;일관되고 투명한 원칙적 결정을 내립니다&quot;와 일치합니다. 사용 사례 탐색 및 개발을 위한 명확한 원칙과 가치를 정의하는 것은 일관된 결정을 내리고 결정 과정을 투명하게 하는 데 중요합니다.</li></ul><p><strong>C는</strong> 가장 높은 ROI를 가진 사용 사례를 선택하는 것만으로는 충분하지 않습니다. Responsible Quantum Computing (책임 있는 양자 컴퓨팅)은 ROI보다 사회적 영향을 우선시하며, 단순히 ROI에만 초점을 맞추는 것은 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 정신과 맞지 않습니다.</p></details><h2 id="문제-13-양자-컴퓨팅에서-시뮬레이터-사용에-대한-진술" tabindex="-1"><a class="header-anchor" href="#문제-13-양자-컴퓨팅에서-시뮬레이터-사용에-대한-진술"><span>문제 13: 양자 컴퓨팅에서 시뮬레이터 사용에 대한 진술</span></a></h2><div class="hint-container tip"><p class="hint-container-title">문제 제시</p><p>양자 컴퓨팅에서 시뮬레이터 사용에 대한 다음 진술 중 참인 것은 무엇입니까? (모두 선택)</p><p>Which of the following statements is/are true about using simulators in quantum computing? Select all that apply.</p><ul><li>A. Simulators are useful for initial debugging and small-scale practice calculations. (시뮬레이터는 초기 디버깅과 소규모 연습 계산에 유용합니다)</li><li>B. Simulators play a temporary role in quantum technology. (시뮬레이터는 양자 기술에서 임시적인 역할을 합니다)</li><li>C. No simulator built on any classical computer or GPU can simulate the full functionality of a highly-entangled 127-qubit quantum computer. (고전 컴퓨터나 GPU로 구축된 어떤 시뮬레이터도 고도로 얽힌 127-qubit 양자 컴퓨터의 전체 기능을 시뮬레이션할 수 없습니다)</li><li>D. Simulators are useful for utility-scale (127+ qubit) calculations. (시뮬레이터는 utility-scale (127+ qubit) 계산에 유용합니다)</li></ul></div><h3 id="필요한-기반-지식-12" tabindex="-1"><a class="header-anchor" href="#필요한-기반-지식-12"><span>필요한 기반 지식</span></a></h3><h4 id="_1-quantum-simulator-양자-시뮬레이터-의-정의와-역할" tabindex="-1"><a class="header-anchor" href="#_1-quantum-simulator-양자-시뮬레이터-의-정의와-역할"><span>1. Quantum Simulator (양자 시뮬레이터)의 정의와 역할</span></a></h4><p><strong>정의:</strong></p><ul><li>Quantum simulator (양자 시뮬레이터)는 고전 컴퓨터를 사용하여 양자 컴퓨터의 동작을 시뮬레이션하는 소프트웨어입니다</li><li>양자 알고리즘과 회로를 테스트하고 디버깅하는 데 사용됩니다</li><li>실제 양자 하드웨어에 접근하기 전에 알고리즘을 개발하고 검증하는 데 유용합니다</li></ul><p><strong>역할:</strong></p><ul><li>초기 디버깅과 소규모 연습 계산에 유용합니다</li><li>양자 알고리즘의 논리적 정확성을 검증하는 데 사용됩니다</li><li>교육 및 학습 목적으로 사용됩니다</li></ul><h4 id="_2-quantum-simulator-양자-시뮬레이터-의-한계" tabindex="-1"><a class="header-anchor" href="#_2-quantum-simulator-양자-시뮬레이터-의-한계"><span>2. Quantum Simulator (양자 시뮬레이터)의 한계</span></a></h4><p><strong>지수적 복잡성:</strong></p><ul><li><em>n</em>개의 qubit (큐비트)를 가진 양자 시스템은 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mi>n</mi></msup></mrow><annotation encoding="application/x-tex">2^n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span>개의 상태를 가질 수 있습니다</li><li>고전 컴퓨터는 이러한 지수적으로 많은 상태를 모두 저장하고 처리해야 합니다</li><li>Qubit (큐비트) 수가 증가하면 시뮬레이션에 필요한 메모리와 계산 시간이 지수적으로 증가합니다</li></ul><p><strong>127-Qubit 양자 컴퓨터의 복잡성:</strong></p><ul><li>127 qubit (큐비트)는 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mn>127</mn></msup></mrow><annotation encoding="application/x-tex">2^{127}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">127</span></span></span></span></span></span></span></span></span></span></span></span>개의 상태를 가질 수 있습니다</li><li>이것은 약 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1.7</mn><mo>×</mo><msup><mn>10</mn><mn>38</mn></msup></mrow><annotation encoding="application/x-tex">1.7 \\times 10^{38}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1.7</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">38</span></span></span></span></span></span></span></span></span></span></span></span>개의 상태입니다</li><li>고전 컴퓨터나 GPU로 이러한 모든 상태를 시뮬레이션하는 것은 현실적으로 불가능합니다</li></ul><p><strong>Entanglement (얽힘)의 영향:</strong></p><ul><li>고도로 얽힌 (highly-entangled) 양자 상태는 더 복잡합니다</li><li>Entanglement (얽힘)는 양자 컴퓨팅의 고유한 힘의 핵심이며, 고전 컴퓨터로 시뮬레이션하기 어렵습니다</li><li>Quantum computer (양자 컴퓨터)는 한 번에 지수적으로 많은 논리적 상태를 허용하는 특별한 종류의 superposition (중첩)을 활용하며, 어떤 classical computer (고전 컴퓨터)도 이를 달성할 수 없습니다</li></ul><h4 id="_3-quantum-simulator-양자-시뮬레이터-의-유용성-범위" tabindex="-1"><a class="header-anchor" href="#_3-quantum-simulator-양자-시뮬레이터-의-유용성-범위"><span>3. Quantum Simulator (양자 시뮬레이터)의 유용성 범위</span></a></h4><p><strong>소규모 계산:</strong></p><ul><li>소규모 qubit (큐비트) 수 (예: 20-30 qubit 이하)의 경우 시뮬레이터가 유용합니다</li><li>초기 디버깅과 연습 계산에 적합합니다</li><li>알고리즘의 논리적 정확성을 검증하는 데 사용할 수 있습니다</li></ul><p><strong>대규모 계산의 한계:</strong></p><ul><li>Utility-scale (127+ qubit) 계산은 고전 컴퓨터로 시뮬레이션하기 어렵습니다</li><li>127+ qubit (큐비트)는 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mn>127</mn></msup></mrow><annotation encoding="application/x-tex">2^{127}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">127</span></span></span></span></span></span></span></span></span></span></span></span>개 이상의 상태를 가질 수 있으며, 이것은 고전 컴퓨터의 메모리와 계산 능력을 초과합니다</li><li>실제 양자 하드웨어가 필요합니다</li></ul><h4 id="_4-quantum-simulator-양자-시뮬레이터-의-임시적-역할" tabindex="-1"><a class="header-anchor" href="#_4-quantum-simulator-양자-시뮬레이터-의-임시적-역할"><span>4. Quantum Simulator (양자 시뮬레이터)의 임시적 역할</span></a></h4><p><strong>현재 역할:</strong></p><ul><li>양자 하드웨어가 아직 완전히 발전하지 않은 현재 단계에서 시뮬레이터는 중요한 역할을 합니다</li><li>알고리즘 개발, 교육, 디버깅에 사용됩니다</li></ul><p><strong>미래의 역할:</strong></p><ul><li>양자 하드웨어가 발전하고 더 많은 qubit (큐비트)와 더 나은 성능을 제공하게 되면, 시뮬레이터의 역할이 줄어들 수 있습니다</li><li>하지만 소규모 계산과 교육 목적으로는 계속 유용할 것입니다</li><li>시뮬레이터는 양자 기술의 발전 과정에서 임시적인 역할을 할 수 있습니다</li></ul><h4 id="_5-classical-computer-고전-컴퓨터-의-한계" tabindex="-1"><a class="header-anchor" href="#_5-classical-computer-고전-컴퓨터-의-한계"><span>5. Classical Computer (고전 컴퓨터)의 한계</span></a></h4><p><strong>지수적 복잡성의 문제:</strong></p><ul><li>Quantum computer (양자 컴퓨터)는 지수적으로 많은 논리적 상태를 동시에 처리할 수 있습니다</li><li>어떤 classical computer (고전 컴퓨터)도 이를 달성할 수 없습니다</li><li>고전 컴퓨터는 각 상태를 개별적으로 처리해야 합니다</li></ul><p><strong>GPU의 한계:</strong></p><ul><li>GPU는 병렬 처리를 통해 성능을 향상시킬 수 있지만, 지수적 복잡성의 문제를 해결할 수는 없습니다</li><li>127+ qubit (큐비트)의 고도로 얽힌 양자 시스템을 시뮬레이션하는 것은 GPU로도 불가능합니다</li></ul><h4 id="_6-utility-scale-실용적-규모-의-의미" tabindex="-1"><a class="header-anchor" href="#_6-utility-scale-실용적-규모-의-의미"><span>6. Utility Scale (실용적 규모)의 의미</span></a></h4><p><strong>정의:</strong></p><ul><li>Utility scale은 양자 컴퓨터가 실용적인 문제를 해결할 수 있는 규모를 의미합니다</li><li>127+ qubit (큐비트)는 utility scale의 한 예입니다</li><li>이러한 규모의 양자 컴퓨터는 고전 컴퓨터로 시뮬레이션하기 어렵습니다</li></ul><p><strong>시뮬레이터의 한계:</strong></p><ul><li>Utility-scale (127+ qubit) 계산은 시뮬레이터로 처리하기 어렵습니다</li><li>실제 양자 하드웨어가 필요합니다</li></ul><h3 id="풀이-과정-12" tabindex="-1"><a class="header-anchor" href="#풀이-과정-12"><span>풀이 과정</span></a></h3><ol><li><p><strong>Quantum Simulator (양자 시뮬레이터)의 역할 확인</strong></p><ul><li>시뮬레이터는 초기 디버깅과 소규모 연습 계산에 유용합니다</li><li>양자 알고리즘의 논리적 정확성을 검증하는 데 사용됩니다</li></ul></li><li><p><strong>지수적 복잡성의 문제 확인</strong></p><ul><li><em>n</em>개의 qubit (큐비트)는 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mi>n</mi></msup></mrow><annotation encoding="application/x-tex">2^n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span>개의 상태를 가질 수 있습니다</li><li>127 qubit (큐비트)는 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mn>127</mn></msup></mrow><annotation encoding="application/x-tex">2^{127}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">127</span></span></span></span></span></span></span></span></span></span></span></span>개의 상태를 가질 수 있으며, 이것은 고전 컴퓨터로 시뮬레이션하기 어렵습니다</li><li>어떤 classical computer (고전 컴퓨터)도 지수적으로 많은 논리적 상태를 동시에 처리할 수 없습니다</li></ul></li><li><p><strong>각 옵션 분석</strong></p><ul><li><strong>A. Simulators are useful for initial debugging and small-scale practice calculations</strong>: 시뮬레이터는 초기 디버깅과 소규모 연습 계산에 유용합니다.</li><li><strong>B. Simulators play a temporary role in quantum technology</strong>: 양자 하드웨어가 발전하면 시뮬레이터의 역할이 줄어들 수 있습니다.</li><li><strong>C. No simulator built on any classical computer or GPU can simulate the full functionality of a highly-entangled 127-qubit quantum computer</strong>: 127 qubit (큐비트)는 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mn>127</mn></msup></mrow><annotation encoding="application/x-tex">2^{127}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">127</span></span></span></span></span></span></span></span></span></span></span></span>개의 상태를 가질 수 있으며, 고전 컴퓨터나 GPU로 시뮬레이션하기 어렵습니다.</li><li><strong>D. Simulators are useful for utility-scale (127+ qubit) calculations</strong>: 127+ qubit (큐비트)는 고전 컴퓨터로 시뮬레이션하기 어렵습니다.</li></ul></li></ol><details class="hint-container details"><summary>최종 답안</summary><p><strong>결론 도출</strong></p><ul><li>A, B, C는 모두 양자 시뮬레이터의 역할과 한계를 정확히 반영합니다</li><li>D는 시뮬레이터의 한계를 잘못 이해한 것입니다</li></ul><p><strong>A. Simulators are useful for initial debugging and small-scale practice calculations.</strong></p><ul><li>Quantum simulator (양자 시뮬레이터)는 양자 알고리즘과 회로를 테스트하고 디버깅하는 데 사용됩니다. 초기 디버깅과 소규모 연습 계산에 유용하며, 양자 알고리즘의 논리적 정확성을 검증하는 데 사용할 수 있습니다. 소규모 qubit (큐비트) 수 (예: 20-30 qubit 이하)의 경우 시뮬레이터가 효과적으로 작동합니다.</li></ul><p><strong>B. Simulators play a temporary role in quantum technology.</strong></p><ul><li>양자 하드웨어가 아직 완전히 발전하지 않은 현재 단계에서 시뮬레이터는 중요한 역할을 합니다. 하지만 양자 하드웨어가 발전하고 더 많은 qubit (큐비트)와 더 나은 성능을 제공하게 되면, 시뮬레이터의 역할이 줄어들 수 있습니다. 시뮬레이터는 양자 기술의 발전 과정에서 임시적인 역할을 할 수 있습니다.</li></ul><p><strong>C. No simulator built on any classical computer or GPU can simulate the full functionality of a highly-entangled 127-qubit quantum computer.</strong></p><ul><li>127 qubit (큐비트)는 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mn>127</mn></msup></mrow><annotation encoding="application/x-tex">2^{127}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">127</span></span></span></span></span></span></span></span></span></span></span></span>개의 상태를 가질 수 있으며, 이것은 약 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1.7</mn><mo>×</mo><msup><mn>10</mn><mn>38</mn></msup></mrow><annotation encoding="application/x-tex">1.7 \\times 10^{38}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1.7</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">38</span></span></span></span></span></span></span></span></span></span></span></span>개의 상태입니다. 고전 컴퓨터나 GPU로 이러한 모든 상태를 시뮬레이션하는 것은 현실적으로 불가능합니다. 고도로 얽힌 (highly-entangled) 양자 상태는 더 복잡하며, Quantum computer (양자 컴퓨터)는 한 번에 지수적으로 많은 논리적 상태를 허용하는 특별한 종류의 superposition (중첩)을 활용하며, 어떤 classical computer (고전 컴퓨터)도 이를 달성할 수 없습니다.</li></ul><p><strong>D는</strong> Utility-scale (127+ qubit) 계산은 고전 컴퓨터로 시뮬레이션하기 어렵습니다. 127+ qubit (큐비트)는 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mn>127</mn></msup></mrow><annotation encoding="application/x-tex">2^{127}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">127</span></span></span></span></span></span></span></span></span></span></span></span>개 이상의 상태를 가질 수 있으며, 이것은 고전 컴퓨터의 메모리와 계산 능력을 초과합니다. 이러한 규모의 계산에는 실제 양자 하드웨어가 필요합니다.</p></details><h2 id="문제-14-5k-challenge에-대한-진술" tabindex="-1"><a class="header-anchor" href="#문제-14-5k-challenge에-대한-진술"><span>문제 14: 5k Challenge에 대한 진술</span></a></h2><div class="hint-container tip"><p class="hint-container-title">문제 제시</p><p>5k Challenge에 대한 다음 옵션 중 올바른 것은 무엇입니까? (하나 이상 선택)</p><p>Which of the following options is/are correct regarding the 5k Challenge?</p><ul><li>A. It deals with &quot;utility scale&quot;, a scale at which quantum computing becomes really useful. (이것은 양자 컴퓨팅이 정말로 유용해지는 규모인 &quot;utility scale&quot;과 관련이 있습니다)</li><li>B. It means running calculations using 5,000 gates or more. (5,000개 이상의 게이트를 사용하여 계산을 실행하는 것을 의미합니다)</li><li>C. The challenge is the same thing as &quot;quantum advantage&quot;. (이 챌린지는 &quot;quantum advantage&quot;와 같은 것입니다)</li><li>D. It is a challenge to the quantum community to see what can be done with useful quantum computing. (이것은 유용한 양자 컴퓨팅으로 무엇을 할 수 있는지 보기 위해 양자 커뮤니티에 제시된 챌린지입니다)</li></ul></div><h3 id="필요한-기반-지식-13" tabindex="-1"><a class="header-anchor" href="#필요한-기반-지식-13"><span>필요한 기반 지식</span></a></h3><h4 id="_1-5k-challenge의-정의" tabindex="-1"><a class="header-anchor" href="#_1-5k-challenge의-정의"><span>1. 5k Challenge의 정의</span></a></h4><p><strong>&quot;5k&quot;의 의미:</strong></p><ul><li>&quot;5k&quot;는 &quot;5,000&quot;을 의미합니다</li><li>5k Challenge는 5,000개 이상의 gate (게이트)를 사용하여 계산을 실행하는 챌린지입니다</li><li>이것은 양자 컴퓨팅의 실용성을 탐색하기 위한 챌린지입니다</li></ul><p><strong>챌린지의 목적:</strong></p><ul><li>양자 커뮤니티에 유용한 양자 컴퓨팅으로 무엇을 할 수 있는지 보여주는 것입니다</li><li>Utility scale (실용적 규모)에서 양자 컴퓨팅의 잠재력을 탐색하는 것입니다</li><li>5,000개 이상의 gate (게이트)를 사용하는 복잡한 양자 회로를 실행하는 것입니다</li></ul><h4 id="_2-utility-scale-실용적-규모-의-의미" tabindex="-1"><a class="header-anchor" href="#_2-utility-scale-실용적-규모-의-의미"><span>2. Utility Scale (실용적 규모)의 의미</span></a></h4><p><strong>정의:</strong></p><ul><li>Utility scale은 양자 컴퓨터가 실용적인 문제를 해결할 수 있는 규모를 의미합니다</li><li>127+ qubit (큐비트)는 utility scale의 한 예입니다</li><li>양자 컴퓨팅이 정말로 유용해지는 규모입니다</li></ul><p><strong>5k Challenge와의 관계:</strong></p><ul><li>5k Challenge는 utility scale과 관련이 있습니다</li><li>5,000개 이상의 gate (게이트)를 사용하는 계산은 utility scale의 한 측면입니다</li><li>이것은 양자 컴퓨팅이 실용적인 문제를 해결할 수 있는 규모에 도달했음을 보여줍니다</li></ul><h4 id="_3-quantum-advantage-양자-우위-와의-차이" tabindex="-1"><a class="header-anchor" href="#_3-quantum-advantage-양자-우위-와의-차이"><span>3. Quantum Advantage (양자 우위)와의 차이</span></a></h4><p><strong>Quantum Advantage (양자 우위)의 정의:</strong></p><ul><li>Quantum advantage (양자 우위)는 양자 컴퓨터가 특정 문제에서 고전 컴퓨터보다 상당한 성능 이점을 명확히 입증할 수 있을 때입니다</li><li>구체적으로, quantum computation (양자 계산)이 수백 배 또는 수천 배 더 빠르거나, 메모리의 더 작은 부분만 필요하거나, 불가능해 보이는 것을 가능하게 만들 때입니다</li></ul><p><strong>5k Challenge와의 차이:</strong></p><ul><li>5k Challenge는 5,000개 이상의 gate (게이트)를 사용하는 계산을 실행하는 챌린지입니다</li><li>Quantum advantage (양자 우위)는 양자 컴퓨터가 고전 컴퓨터보다 우수한 성능을 보이는 것을 의미합니다</li><li>5k Challenge는 quantum advantage (양자 우위)와 같은 것이 아닙니다</li><li>5k Challenge는 utility scale에서 양자 컴퓨팅의 잠재력을 탐색하는 것이며, quantum advantage (양자 우위)는 그 결과일 수 있습니다</li></ul><h4 id="_4-gate-게이트-의-역할" tabindex="-1"><a class="header-anchor" href="#_4-gate-게이트-의-역할"><span>4. Gate (게이트)의 역할</span></a></h4><p><strong>Gate (게이트)의 의미:</strong></p><ul><li>Gate (게이트)는 양자 회로에서 기본 연산을 수행하는 단위입니다</li><li>더 많은 gate (게이트)를 사용하면 더 복잡한 양자 회로를 구현할 수 있습니다</li><li>5,000개 이상의 gate (게이트)를 사용하는 것은 복잡한 양자 알고리즘을 실행하는 것을 의미합니다</li></ul><p><strong>5k Challenge의 의미:</strong></p><ul><li>5,000개 이상의 gate (게이트)를 사용하여 계산을 실행하는 것입니다</li><li>이것은 양자 컴퓨팅의 실용성을 탐색하기 위한 챌린지입니다</li><li>Utility scale에서 양자 컴퓨팅의 잠재력을 보여주는 것입니다</li></ul><h4 id="_5-양자-커뮤니티에-대한-챌린지" tabindex="-1"><a class="header-anchor" href="#_5-양자-커뮤니티에-대한-챌린지"><span>5. 양자 커뮤니티에 대한 챌린지</span></a></h4><p><strong>챌린지의 목적:</strong></p><ul><li>양자 커뮤니티에 유용한 양자 컴퓨팅으로 무엇을 할 수 있는지 보여주는 것입니다</li><li>Utility scale에서 양자 컴퓨팅의 잠재력을 탐색하는 것입니다</li><li>5,000개 이상의 gate (게이트)를 사용하는 복잡한 양자 회로를 실행하는 것입니다</li></ul><p><strong>커뮤니티의 참여:</strong></p><ul><li>양자 커뮤니티는 5k Challenge를 통해 유용한 양자 컴퓨팅의 가능성을 탐색합니다</li><li>이것은 양자 컴퓨팅의 실용성을 입증하는 데 도움이 됩니다</li></ul><h4 id="_6-5k-challenge의-중요성" tabindex="-1"><a class="header-anchor" href="#_6-5k-challenge의-중요성"><span>6. 5k Challenge의 중요성</span></a></h4><p><strong>실용성 탐색:</strong></p><ul><li>5k Challenge는 양자 컴퓨팅이 실용적인 문제를 해결할 수 있는 규모에 도달했음을 보여줍니다</li><li>Utility scale에서 양자 컴퓨팅의 잠재력을 탐색하는 것입니다</li><li>양자 커뮤니티에 유용한 양자 컴퓨팅으로 무엇을 할 수 있는지 보여주는 것입니다</li></ul><p><strong>기술 발전:</strong></p><ul><li>5,000개 이상의 gate (게이트)를 사용하는 계산은 양자 컴퓨팅 기술의 발전을 보여줍니다</li><li>이것은 양자 컴퓨팅이 실용적인 단계에 접근하고 있음을 의미합니다</li></ul><h3 id="풀이-과정-13" tabindex="-1"><a class="header-anchor" href="#풀이-과정-13"><span>풀이 과정</span></a></h3><ol><li><p><strong>5k Challenge의 정의 확인</strong></p><ul><li>&quot;5k&quot;는 &quot;5,000&quot;을 의미합니다</li><li>5k Challenge는 5,000개 이상의 gate (게이트)를 사용하여 계산을 실행하는 챌린지입니다</li><li>이것은 양자 컴퓨팅의 실용성을 탐색하기 위한 챌린지입니다</li></ul></li><li><p><strong>Utility Scale과의 관계 확인</strong></p><ul><li>Utility scale은 양자 컴퓨터가 실용적인 문제를 해결할 수 있는 규모를 의미합니다</li><li>5k Challenge는 utility scale과 관련이 있습니다</li><li>5,000개 이상의 gate (게이트)를 사용하는 계산은 utility scale의 한 측면입니다</li></ul></li><li><p><strong>Quantum Advantage와의 차이 확인</strong></p><ul><li>Quantum advantage (양자 우위)는 양자 컴퓨터가 고전 컴퓨터보다 우수한 성능을 보이는 것을 의미합니다</li><li>5k Challenge는 quantum advantage (양자 우위)와 같은 것이 아닙니다</li><li>5k Challenge는 utility scale에서 양자 컴퓨팅의 잠재력을 탐색하는 것이며, quantum advantage (양자 우위)는 그 결과일 수 있습니다</li></ul></li><li><p><strong>각 옵션 분석</strong></p><ul><li><strong>A. It deals with &quot;utility scale&quot;, a scale at which quantum computing becomes really useful</strong>: 5k Challenge는 utility scale과 관련이 있습니다.</li><li><strong>B. It means running calculations using 5,000 gates or more</strong>: &quot;5k&quot;는 &quot;5,000&quot;을 의미하며, 5k Challenge는 5,000개 이상의 gate (게이트)를 사용하여 계산을 실행하는 것입니다.</li><li><strong>C. The challenge is the same thing as &quot;quantum advantage&quot;</strong>: 5k Challenge는 quantum advantage (양자 우위)와 같은 것이 아닙니다.</li><li><strong>D. It is a challenge to the quantum community to see what can be done with useful quantum computing</strong>: 5k Challenge는 양자 커뮤니티에 유용한 양자 컴퓨팅으로 무엇을 할 수 있는지 보여주는 챌린지입니다.</li></ul></li></ol><details class="hint-container details"><summary>최종 답안</summary><p><strong>결론 도출</strong></p><ul><li>A, B, D는 모두 5k Challenge의 정의와 목적을 정확히 반영합니다</li><li>C는 5k Challenge와 quantum advantage (양자 우위)를 혼동한 것입니다</li></ul><p><strong>A. It deals with &quot;utility scale&quot;, a scale at which quantum computing becomes really useful.</strong></p><ul><li>5k Challenge는 utility scale (실용적 규모)와 관련이 있습니다. Utility scale은 양자 컴퓨터가 실용적인 문제를 해결할 수 있는 규모를 의미하며, 양자 컴퓨팅이 정말로 유용해지는 규모입니다. 5,000개 이상의 gate (게이트)를 사용하는 계산은 utility scale의 한 측면이며, 이것은 양자 컴퓨팅이 실용적인 문제를 해결할 수 있는 규모에 도달했음을 보여줍니다.</li></ul><p><strong>B. It means running calculations using 5,000 gates or more.</strong></p><ul><li>&quot;5k&quot;는 &quot;5,000&quot;을 의미하며, 5k Challenge는 5,000개 이상의 gate (게이트)를 사용하여 계산을 실행하는 챌린지입니다. Gate (게이트)는 양자 회로에서 기본 연산을 수행하는 단위이며, 더 많은 gate (게이트)를 사용하면 더 복잡한 양자 회로를 구현할 수 있습니다. 5,000개 이상의 gate (게이트)를 사용하는 것은 복잡한 양자 알고리즘을 실행하는 것을 의미합니다.</li></ul><p><strong>D. It is a challenge to the quantum community to see what can be done with useful quantum computing.</strong></p><ul><li>5k Challenge는 양자 커뮤니티에 유용한 양자 컴퓨팅으로 무엇을 할 수 있는지 보여주는 챌린지입니다. 이것은 utility scale에서 양자 컴퓨팅의 잠재력을 탐색하는 것이며, 양자 컴퓨팅의 실용성을 입증하는 데 도움이 됩니다. 양자 커뮤니티는 5k Challenge를 통해 유용한 양자 컴퓨팅의 가능성을 탐색합니다.</li></ul><p><strong>C는</strong> 5k Challenge는 quantum advantage (양자 우위)와 같은 것이 아닙니다. Quantum advantage (양자 우위)는 양자 컴퓨터가 특정 문제에서 고전 컴퓨터보다 상당한 성능 이점을 명확히 입증할 수 있을 때입니다. 반면, 5k Challenge는 5,000개 이상의 gate (게이트)를 사용하는 계산을 실행하는 챌린지이며, utility scale에서 양자 컴퓨팅의 잠재력을 탐색하는 것입니다. 5k Challenge는 quantum advantage (양자 우위)를 달성하기 위한 한 단계일 수 있지만, 그것과 같은 것은 아닙니다.</p></details><h2 id="문제-15-양자-컴퓨팅에-대한-현실적이고-책임-있는-진술" tabindex="-1"><a class="header-anchor" href="#문제-15-양자-컴퓨팅에-대한-현실적이고-책임-있는-진술"><span>문제 15: 양자 컴퓨팅에 대한 현실적이고 책임 있는 진술</span></a></h2><div class="hint-container tip"><p class="hint-container-title">문제 제시</p><p>양자 컴퓨팅에 대한 다음 옵션 중 현실적이고 책임 있는 진술(과장이나 잘못된 진술이 아닌)은 무엇입니까? (하나 이상 선택)</p><p>Select the option(s) below that are realistic &amp; responsible statements about quantum computing (as opposed to hype or incorrect statements).</p><ul><li>A. Current quantum computers beat classical computers at most things. (현재 양자 컴퓨터는 대부분의 것에서 고전 컴퓨터를 능가합니다)</li><li>B. Quantum computing will fix world hunger. (양자 컴퓨팅이 세계 기아를 해결할 것입니다)</li><li>C. Quantum computing may help humans improve logistics and energy efficiency, thereby reducing our impact on the planet. (양자 컴퓨팅은 인간이 물류와 에너지 효율성을 개선하여 지구에 대한 영향을 줄이는 데 도움이 될 수 있습니다)</li><li>D. Quantum computing will fix global warming. (양자 컴퓨팅이 지구 온난화를 해결할 것입니다)</li><li>E. Quantum computing has applications in chemical simulation, including nitrogen fixation processes, which are critical for agriculture. (양자 컴퓨팅은 농업에 중요한 질소 고정 과정을 포함한 화학 시뮬레이션에 응용이 있습니다)</li><li>F. Quantum computing has reached an era in which we can explore its useful applications. (양자 컴퓨팅은 유용한 애플리케이션을 탐색할 수 있는 시대에 도달했습니다)</li></ul></div><h3 id="필요한-기반-지식-14" tabindex="-1"><a class="header-anchor" href="#필요한-기반-지식-14"><span>필요한 기반 지식</span></a></h3><h4 id="_1-responsible-quantum-computing-책임-있는-양자-컴퓨팅-의-원칙" tabindex="-1"><a class="header-anchor" href="#_1-responsible-quantum-computing-책임-있는-양자-컴퓨팅-의-원칙"><span>1. Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 원칙</span></a></h4><p><strong>원칙 3: 제품을 정확하게 홍보합니다</strong></p><ul><li>Quantum Computing (양자 컴퓨팅)의 능력과 한계를 정확하게 표현합니다</li><li>과장된 주장을 피하고 현실적인 기대를 설정합니다</li><li>양자 컴퓨팅 연구에 대한 기대와 타임라인에 대해 현실적으로 말해야 합니다</li></ul><p><strong>과장된 주장의 문제점:</strong></p><ul><li>과장된 주장은 신뢰를 훼손할 수 있습니다</li><li>현실적인 기대와 타임라인을 설정하면 신뢰를 구축할 수 있습니다</li><li>Responsible Quantum Computing (책임 있는 양자 컴퓨팅)은 과장된 주장을 피하고 현실적인 기대를 설정합니다</li></ul><h4 id="_2-quantum-advantage-양자-우위-의-현재-상태" tabindex="-1"><a class="header-anchor" href="#_2-quantum-advantage-양자-우위-의-현재-상태"><span>2. Quantum Advantage (양자 우위)의 현재 상태</span></a></h4><p><strong>현재 상태:</strong></p><ul><li>Quantum computer (양자 컴퓨터)가 아직 상업적 애플리케이션에서 quantum advantage (양자 우위)에 도달하지 않았습니다</li><li>현재 양자 컴퓨터는 대부분의 문제에서 고전 컴퓨터를 능가하지 못합니다</li><li>Quantum advantage (양자 우위)는 양자 컴퓨터가 특정 문제에서 고전 컴퓨터보다 상당한 성능 이점을 명확히 입증할 수 있을 때입니다</li></ul><p><strong>현실적인 평가:</strong></p><ul><li>현재 양자 컴퓨터는 noisy (잡음이 있는) 상태이며, error mitigation (오류 완화)을 사용해야 합니다</li><li>UC Berkeley와의 작업은 fault tolerance (오류 허용) 시대 이전에 의미 있는 계산과 현실적인 애플리케이션을 탐색하기 위해 현재 사용 가능한 Quantum processor (양자 프로세서)의 힘을 입증합니다</li><li>이것은 양자 컴퓨팅이 유용한 애플리케이션을 탐색할 수 있는 시대에 도달했음을 보여줍니다</li></ul><h4 id="_3-양자-컴퓨팅의-실제-응용-분야" tabindex="-1"><a class="header-anchor" href="#_3-양자-컴퓨팅의-실제-응용-분야"><span>3. 양자 컴퓨팅의 실제 응용 분야</span></a></h4><p><strong>Simulation (시뮬레이션):</strong></p><ul><li>이미 quantum mechanical (양자역학적) 특성을 지닌 물리적 또는 화학적 시스템의 시뮬레이션</li><li>분자 구조 및 화학 반응 시뮬레이션</li><li>신소재 설계 (고용량 배터리, 탄소 포집 등)</li><li>비료와 같은 화학 구조 설계</li><li>질소 고정 과정과 같은 농업에 중요한 화학 과정의 시뮬레이션</li></ul><p><strong>Optimization (최적화):</strong></p><ul><li>복잡한 문제, 일반적으로 최소화 문제로 표현되는 문제에 대한 최적의 해법을 찾는 것</li><li>Supply chain (공급망) 최적화</li><li>Logistics (물류) 최적화</li><li>Global logistics optimization (글로벌 물류 최적화)</li><li>Energy efficiency (에너지 효율성) 개선</li></ul><p><strong>에너지 효율성:</strong></p><ul><li>Energy (에너지) 산업에서의 사용 사례: <ul><li>Emissions reduction (배출 감소)</li><li>Efficient reservoir development (효율적인 저수지 개발)</li><li>Power grid network (전력망 네트워크)</li><li>Renewable energy (재생 에너지)</li><li>Energy trading (에너지 거래)</li></ul></li></ul><h4 id="_4-양자-컴퓨팅의-한계와-현실적-기대" tabindex="-1"><a class="header-anchor" href="#_4-양자-컴퓨팅의-한계와-현실적-기대"><span>4. 양자 컴퓨팅의 한계와 현실적 기대</span></a></h4><p><strong>현실적인 기대:</strong></p><ul><li>양자 컴퓨팅은 특정 문제에서 도움이 될 수 있습니다</li><li>하지만 모든 문제를 해결할 수 있는 만능 솔루션은 아닙니다</li><li>양자 컴퓨팅은 유용한 애플리케이션을 탐색할 수 있는 시대에 도달했습니다</li></ul><p><strong>과장된 주장의 예:</strong></p><ul><li>&quot;양자 컴퓨팅이 세계 기아를 해결할 것입니다&quot; - 이것은 비현실적이고 과장된 주장입니다</li><li>&quot;양자 컴퓨팅이 지구 온난화를 해결할 것입니다&quot; - 이것은 비현실적이고 과장된 주장입니다</li><li>&quot;현재 양자 컴퓨터는 대부분의 것에서 고전 컴퓨터를 능가합니다&quot; - 이것은 잘못된 주장입니다</li></ul><p><strong>책임 있는 진술:</strong></p><ul><li>양자 컴퓨팅은 특정 문제에서 도움이 될 수 있습니다</li><li>양자 컴퓨팅은 물류와 에너지 효율성 개선에 도움이 될 수 있습니다</li><li>양자 컴퓨팅은 화학 시뮬레이션에 응용이 있습니다</li><li>양자 컴퓨팅은 유용한 애플리케이션을 탐색할 수 있는 시대에 도달했습니다</li></ul><h4 id="_5-양자-컴퓨팅의-현재-단계" tabindex="-1"><a class="header-anchor" href="#_5-양자-컴퓨팅의-현재-단계"><span>5. 양자 컴퓨팅의 현재 단계</span></a></h4><p><strong>탐색 단계:</strong></p><ul><li>Quantum advantage (양자 우위)에 도달하지 않았더라도, 많은 기업들이 이미 양자 컴퓨팅을 탐색하고 있습니다</li><li>UC Berkeley와의 작업은 fault tolerance (오류 허용) 시대 이전에 의미 있는 계산과 현실적인 애플리케이션을 탐색하기 위해 현재 사용 가능한 Quantum processor (양자 프로세서)의 힘을 입증합니다</li><li>양자 컴퓨팅은 유용한 애플리케이션을 탐색할 수 있는 시대에 도달했습니다</li></ul><p><strong>현실적인 평가:</strong></p><ul><li>양자 컴퓨팅은 아직 완전히 발전하지 않았지만, 유용한 애플리케이션을 탐색할 수 있는 단계에 있습니다</li><li>현재 양자 컴퓨터는 대부분의 문제에서 고전 컴퓨터를 능가하지 못하지만, 특정 문제에서 도움이 될 수 있습니다</li></ul><h3 id="풀이-과정-14" tabindex="-1"><a class="header-anchor" href="#풀이-과정-14"><span>풀이 과정</span></a></h3><ol><li><p><strong>Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 원칙 확인</strong></p><ul><li>원칙 3: 제품을 정확하게 홍보합니다</li><li>과장된 주장을 피하고 현실적인 기대를 설정합니다</li></ul></li><li><p><strong>Quantum Advantage (양자 우위)의 현재 상태 확인</strong></p><ul><li>Quantum computer (양자 컴퓨터)가 아직 상업적 애플리케이션에서 quantum advantage (양자 우위)에 도달하지 않았습니다</li><li>현재 양자 컴퓨터는 대부분의 문제에서 고전 컴퓨터를 능가하지 못합니다</li></ul></li><li><p><strong>양자 컴퓨팅의 실제 응용 분야 확인</strong></p><ul><li>Simulation (시뮬레이션): 화학 시뮬레이션, 질소 고정 과정 등</li><li>Optimization (최적화): 물류 최적화, 에너지 효율성 개선 등</li></ul></li><li><p><strong>각 옵션 분석</strong></p><ul><li><strong>A. Current quantum computers beat classical computers at most things</strong>: 현재 양자 컴퓨터는 대부분의 문제에서 고전 컴퓨터를 능가하지 못합니다.</li><li><strong>B. Quantum computing will fix world hunger</strong>: 이것은 비현실적이고 과장된 주장입니다.</li><li><strong>C. Quantum computing may help humans improve logistics and energy efficiency, thereby reducing our impact on the planet</strong>: 양자 컴퓨팅은 물류와 에너지 효율성 개선에 도움이 될 수 있습니다.</li><li><strong>D. Quantum computing will fix global warming</strong>: 이것은 비현실적이고 과장된 주장입니다.</li><li><strong>E. Quantum computing has applications in chemical simulation, including nitrogen fixation processes, which are critical for agriculture</strong>: 양자 컴퓨팅은 화학 시뮬레이션에 응용이 있으며, 질소 고정 과정과 같은 농업에 중요한 화학 과정을 시뮬레이션할 수 있습니다.</li><li><strong>F. Quantum computing has reached an era in which we can explore its useful applications</strong>: UC Berkeley와의 작업은 fault tolerance (오류 허용) 시대 이전에 의미 있는 계산과 현실적인 애플리케이션을 탐색하고 있음을 보여줍니다.</li></ul></li></ol><details class="hint-container details"><summary>최종 답안</summary><p><strong>결론 도출</strong></p><ul><li>C, E, F는 모두 현실적이고 책임 있는 진술입니다</li><li>A, B, D는 과장되거나 잘못된 진술입니다</li></ul><p><strong>C. Quantum computing may help humans improve logistics and energy efficiency, thereby reducing our impact on the planet.</strong></p><ul><li>양자 컴퓨팅은 Optimization (최적화) 문제에 적용될 수 있으며, Logistics (물류) 최적화와 Energy efficiency (에너지 효율성) 개선에 도움이 될 수 있습니다. 문서에서 물류 최적화(Global logistics optimization, Supply chain 최적화)와 에너지 효율성(Emissions reduction, Efficient reservoir development, Power grid network, Renewable energy)에 대한 언급이 있습니다. 이것은 현실적이고 책임 있는 진술입니다.</li></ul><p><strong>E. Quantum computing has applications in chemical simulation, including nitrogen fixation processes, which are critical for agriculture.</strong></p><ul><li>양자 컴퓨팅은 Simulation (시뮬레이션)에 응용이 있으며, 이미 quantum mechanical (양자역학적) 특성을 지닌 물리적 또는 화학적 시스템의 시뮬레이션에 사용됩니다. 문서에서 분자 구조 및 화학 반응 시뮬레이션, 비료와 같은 화학 구조 설계에 대한 언급이 있습니다. 질소 고정 과정은 농업에 중요한 화학 과정이며, 양자 컴퓨팅으로 시뮬레이션할 수 있습니다. 이것은 현실적이고 책임 있는 진술입니다.</li></ul><p><strong>F. Quantum computing has reached an era in which we can explore its useful applications.</strong></p><ul><li>UC Berkeley와의 작업은 fault tolerance (오류 허용) 시대 이전에 의미 있는 계산과 현실적인 애플리케이션을 탐색하기 위해 현재 사용 가능한 Quantum processor (양자 프로세서)의 힘을 입증합니다. Quantum advantage (양자 우위)에 도달하지 않았더라도, 많은 기업들이 이미 양자 컴퓨팅을 탐색하고 있습니다. 이것은 현실적이고 책임 있는 진술입니다.</li></ul><p><strong>A는</strong> 현재 양자 컴퓨터는 대부분의 문제에서 고전 컴퓨터를 능가하지 못합니다. Quantum computer (양자 컴퓨터)가 아직 상업적 애플리케이션에서 quantum advantage (양자 우위)에 도달하지 않았으며, 현재 양자 컴퓨터는 noisy (잡음이 있는) 상태이며, error mitigation (오류 완화)을 사용해야 합니다.</p><p><strong>B는</strong> 이것은 비현실적이고 과장된 주장입니다. 양자 컴퓨팅이 세계 기아를 해결할 것이라고 말하는 것은 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 원칙 3번 &quot;제품을 정확하게 홍보합니다&quot;와 모순됩니다. 과장된 주장을 피하고 현실적인 기대를 설정해야 합니다.</p><p><strong>D는</strong> 이것은 비현실적이고 과장된 주장입니다. 양자 컴퓨팅이 지구 온난화를 해결할 것이라고 말하는 것은 Responsible Quantum Computing (책임 있는 양자 컴퓨팅)의 원칙 3번 &quot;제품을 정확하게 홍보합니다&quot;와 모순됩니다. 양자 컴퓨팅은 에너지 효율성 개선에 도움이 될 수 있지만, 지구 온난화를 &quot;해결&quot;할 것이라고 말하는 것은 과장된 주장입니다.</p></details><h2 id="문제-16-양자-컴퓨팅의-비즈니스-케이스를-지지하는-진술" tabindex="-1"><a class="header-anchor" href="#문제-16-양자-컴퓨팅의-비즈니스-케이스를-지지하는-진술"><span>문제 16: 양자 컴퓨팅의 비즈니스 케이스를 지지하는 진술</span></a></h2><div class="hint-container tip"><p class="hint-container-title">문제 제시</p><p>양자 컴퓨팅의 비즈니스 케이스를 지지하는 다음 진술 중 해당하는 것은 무엇입니까? (하나 이상 선택)</p><p>Which of the following statements support(s) a business case for quantum computing? Select all that apply.</p><ul><li>A. Enterprises are evolving from analyzing data to discovering new ways to solve problems. (기업들은 데이터 분석에서 문제를 해결하는 새로운 방법을 발견하는 것으로 진화하고 있습니다)</li><li>B. Industries are facing greater uncertainty and business models are more dependent on new technologies. (산업들은 더 큰 불확실성에 직면하고 있으며, 비즈니스 모델이 새로운 기술에 더 의존하고 있습니다)</li><li>C. Leading enterprises are already experimenting with real quantum computers today, and due to the steep learning curve, an early start on learning and experimentation can prove to be a competitive advantage. (선도 기업들은 이미 오늘날 실제 양자 컴퓨터로 실험하고 있으며, 가파른 학습 곡선 때문에 학습과 실험을 일찍 시작하는 것이 경쟁 우위가 될 수 있습니다)</li></ul></div><h3 id="필요한-기반-지식-15" tabindex="-1"><a class="header-anchor" href="#필요한-기반-지식-15"><span>필요한 기반 지식</span></a></h3><h4 id="_1-quantum-computing-양자-컴퓨팅-의-사업적-타당성" tabindex="-1"><a class="header-anchor" href="#_1-quantum-computing-양자-컴퓨팅-의-사업적-타당성"><span>1. Quantum Computing (양자 컴퓨팅)의 사업적 타당성</span></a></h4><p><strong>비즈니스 도입 평가:</strong></p><ul><li>비즈니스에 Quantum Computing (양자 컴퓨팅)을 도입할지 여부를 평가할 때 여러 사항들을 고려해야 합니다</li><li>Quantum Computing (양자 컴퓨팅)은 새로운 컴퓨팅 패러다임을 제시합니다</li><li>최근 연구 보고서들은 차세대 컴퓨팅의 주요 동인을 설명하고 있습니다</li></ul><h4 id="_2-발견-중심형-기업-discovery-driven-enterprise" tabindex="-1"><a class="header-anchor" href="#_2-발견-중심형-기업-discovery-driven-enterprise"><span>2. 발견 중심형 기업 (Discovery-Driven Enterprise)</span></a></h4><p><strong>기업의 진화:</strong></p><ul><li>기업은 data analysis (데이터 분석)에서 벗어나 문제를 해결하는 새로운 방법을 발견하는 방향으로 진화할 것입니다</li><li>Quantum Computing (양자 컴퓨팅)은 이러한 발견 과정을 가속화할 수 있는 도구를 제공합니다</li><li>이것은 양자 컴퓨팅의 비즈니스 케이스를 지지하는 중요한 요소입니다</li></ul><p><strong>문제 해결의 새로운 방법:</strong></p><ul><li>Quantum Computing (양자 컴퓨팅)은 기업이 문제를 해결하는 새로운 방법을 발견하는 데 도움이 됩니다</li><li>이것은 단순한 데이터 분석을 넘어서는 것입니다</li></ul><h4 id="_3-글로벌-우선순위와-불확실성" tabindex="-1"><a class="header-anchor" href="#_3-글로벌-우선순위와-불확실성"><span>3. 글로벌 우선순위와 불확실성</span></a></h4><p><strong>산업의 불확실성:</strong></p><ul><li>산업 전반이 불확실성에 직면함에 따라 비즈니스 모델은 새로운 기술에 더욱 민감해지고 의존하게 되었습니다</li><li>Quantum Computing (양자 컴퓨팅)은 이러한 불확실성을 해결하는 데 도움을 줄 수 있는 잠재력을 가지고 있습니다</li><li>이것은 양자 컴퓨팅의 비즈니스 케이스를 지지하는 중요한 요소입니다</li></ul><p><strong>새로운 기술에 대한 의존성:</strong></p><ul><li>비즈니스 모델이 새로운 기술에 더 의존하게 되었습니다</li><li>Quantum Computing (양자 컴퓨팅)은 이러한 새로운 기술 중 하나입니다</li></ul><h4 id="_4-선도-기업의-실험과-경쟁-우위" tabindex="-1"><a class="header-anchor" href="#_4-선도-기업의-실험과-경쟁-우위"><span>4. 선도 기업의 실험과 경쟁 우위</span></a></h4><p><strong>실제 양자 컴퓨터로의 실험:</strong></p><ul><li>많은 기업들이 이미 Quantum Computing (양자 컴퓨팅)을 탐색하고 있습니다</li><li>JPMorgan Chase, Goldman Sachs, Daimler Mercedes-Benz, ExxonMobil 등 Fortune 500 기업들이 포함됩니다</li><li>선도 기업들은 이미 실제 양자 컴퓨터로 실험하고 있습니다</li></ul><p><strong>학습 곡선과 경쟁 우위:</strong></p><ul><li>Quantum Computing (양자 컴퓨팅)은 학습 곡선이 가파르기 때문에, 조기에 학습하고 실험하는 것이 경쟁 우위로 이어질 수 있습니다</li><li>지금 뛰어들어 quantum ready (양자 준비)가 되는 조직은 이러한 기술이 발전함에 따라 뚜렷한 이점을 가질 것입니다</li><li>이것은 양자 컴퓨팅의 비즈니스 케이스를 지지하는 중요한 요소입니다</li></ul><p><strong>조기 시작의 이점:</strong></p><ul><li>많은 비즈니스가 인터넷과 같은 어제의 게임 체인저 기술에 초기에 투자할 수 있는 기회를 되돌리고 싶어할 것입니다</li><li>Quantum Computing (양자 컴퓨팅)으로 경쟁에서 앞서 나갈 기회가 다시 왔습니다</li><li>기술이 성숙해지고 있으며, 지금이 양자 기술을 구축하고 계산 집약적 문제를 해결하는 양자의 엄청난 잠재력을 이해할 때입니다</li></ul><h4 id="_5-양자-컴퓨팅의-현재-단계-1" tabindex="-1"><a class="header-anchor" href="#_5-양자-컴퓨팅의-현재-단계-1"><span>5. 양자 컴퓨팅의 현재 단계</span></a></h4><p><strong>탐색 단계:</strong></p><ul><li>전 세계 정부와 산업 리더들은 이미 헬스케어, 재료 과학, machine learning (머신러닝) 등에서 잠재적 사용 사례를 탐색하고 있습니다</li><li>UC Berkeley와의 작업은 fault tolerance (오류 허용) 시대 이전에 의미 있는 계산과 현실적인 애플리케이션을 탐색하기 위해 현재 사용 가능한 Quantum processor (양자 프로세서)의 힘을 입증합니다</li><li>양자 컴퓨팅은 유용한 애플리케이션을 탐색할 수 있는 시대에 도달했습니다</li></ul><p><strong>실험의 중요성:</strong></p><ul><li>상용 Quantum Computing (양자 컴퓨팅)을 예상하여, 선도 기업들은 내부 quantum capability (양자 역량)를 생성하는 사용 사례를 식별하고 테스트하고 있습니다</li><li>사용 사례가 더 효과적으로 설계될수록 비즈니스 가치를 제공할 가능성이 높아집니다</li></ul><h4 id="_6-경쟁-우위의-창출" tabindex="-1"><a class="header-anchor" href="#_6-경쟁-우위의-창출"><span>6. 경쟁 우위의 창출</span></a></h4><p><strong>Quantum Readiness (양자 준비 상태)의 역할:</strong></p><ul><li>Quantum readiness (양자 준비 상태)는 Quantum Computing (양자 컴퓨팅) 전략, 기술 및 운영에서 조직의 숙련도를 지속적으로 진화하는 측정입니다</li><li>이것은 산업을 혁신하고, 경쟁 우위를 창출하며, 양자에 능숙한 경쟁자로부터의 위협에 대응하기 위해 quantum technology (양자 기술)를 활용하는 회사의 점진적 역량을 특징짓습니다</li></ul><p><strong>조기 투자의 이점:</strong></p><ul><li>지금 뛰어들어 quantum ready (양자 준비)가 되는 조직은 이러한 기술이 발전함에 따라 뚜렷한 이점을 가질 것입니다</li><li>Quantum Computing (양자 컴퓨팅)으로 경쟁에서 앞서 나갈 기회가 다시 왔습니다</li></ul><h3 id="풀이-과정-15" tabindex="-1"><a class="header-anchor" href="#풀이-과정-15"><span>풀이 과정</span></a></h3><ol><li><p><strong>발견 중심형 기업 확인</strong></p><ul><li>기업은 data analysis (데이터 분석)에서 벗어나 문제를 해결하는 새로운 방법을 발견하는 방향으로 진화할 것입니다</li><li>Quantum Computing (양자 컴퓨팅)은 이러한 발견 과정을 가속화할 수 있는 도구를 제공합니다</li></ul></li><li><p><strong>글로벌 우선순위와 불확실성 확인</strong></p><ul><li>산업 전반이 불확실성에 직면함에 따라 비즈니스 모델은 새로운 기술에 더욱 민감해지고 의존하게 되었습니다</li><li>Quantum Computing (양자 컴퓨팅)은 이러한 불확실성을 해결하는 데 도움을 줄 수 있는 잠재력을 가지고 있습니다</li></ul></li><li><p><strong>선도 기업의 실험과 경쟁 우위 확인</strong></p><ul><li>많은 기업들이 이미 Quantum Computing (양자 컴퓨팅)을 탐색하고 있습니다</li><li>Quantum Computing (양자 컴퓨팅)은 학습 곡선이 가파르기 때문에, 조기에 학습하고 실험하는 것이 경쟁 우위로 이어질 수 있습니다</li><li>지금 뛰어들어 quantum ready (양자 준비)가 되는 조직은 이러한 기술이 발전함에 따라 뚜렷한 이점을 가질 것입니다</li></ul></li><li><p><strong>각 옵션 분석</strong></p><ul><li><strong>A. Enterprises are evolving from analyzing data to discovering new ways to solve problems</strong>: 기업은 data analysis (데이터 분석)에서 벗어나 문제를 해결하는 새로운 방법을 발견하는 방향으로 진화할 것입니다. 이것은 양자 컴퓨팅의 비즈니스 케이스를 지지합니다.</li><li><strong>B. Industries are facing greater uncertainty and business models are more dependent on new technologies</strong>: 산업 전반이 불확실성에 직면함에 따라 비즈니스 모델은 새로운 기술에 더욱 민감해지고 의존하게 되었습니다. 이것은 양자 컴퓨팅의 비즈니스 케이스를 지지합니다.</li><li><strong>C. Leading enterprises are already experimenting with real quantum computers today, and due to the steep learning curve, an early start on learning and experimentation can prove to be a competitive advantage</strong>: 많은 기업들이 이미 Quantum Computing (양자 컴퓨팅)을 탐색하고 있으며, Quantum Computing (양자 컴퓨팅)은 학습 곡선이 가파르기 때문에, 조기에 학습하고 실험하는 것이 경쟁 우위로 이어질 수 있습니다. 이것은 양자 컴퓨팅의 비즈니스 케이스를 지지합니다.</li></ul></li></ol><details class="hint-container details"><summary>최종 답안</summary><p><strong>결론 도출</strong></p><ul><li>A, B, C는 모두 양자 컴퓨팅의 비즈니스 케이스를 지지하는 진술입니다</li></ul><p><strong>A. Enterprises are evolving from analyzing data to discovering new ways to solve problems.</strong></p><ul><li>기업은 data analysis (데이터 분석)에서 벗어나 문제를 해결하는 새로운 방법을 발견하는 방향으로 진화할 것입니다. Quantum Computing (양자 컴퓨팅)은 이러한 발견 과정을 가속화할 수 있는 도구를 제공합니다. 이것은 양자 컴퓨팅의 비즈니스 케이스를 지지하는 중요한 요소입니다. 기업들이 단순한 데이터 분석을 넘어서 문제를 해결하는 새로운 방법을 발견하는 것은 양자 컴퓨팅의 가치를 보여줍니다.</li></ul><p><strong>B. Industries are facing greater uncertainty and business models are more dependent on new technologies.</strong></p><ul><li>산업 전반이 불확실성에 직면함에 따라 비즈니스 모델은 새로운 기술에 더욱 민감해지고 의존하게 되었습니다. Quantum Computing (양자 컴퓨팅)은 이러한 불확실성을 해결하는 데 도움을 줄 수 있는 잠재력을 가지고 있습니다. 이것은 양자 컴퓨팅의 비즈니스 케이스를 지지하는 중요한 요소입니다. 비즈니스 모델이 새로운 기술에 더 의존하게 되었고, 양자 컴퓨팅은 이러한 새로운 기술 중 하나입니다.</li></ul><p><strong>C. Leading enterprises are already experimenting with real quantum computers today, and due to the steep learning curve, an early start on learning and experimentation can prove to be a competitive advantage.</strong></p><ul><li>많은 기업들(JPMorgan Chase, Goldman Sachs, Daimler Mercedes-Benz, ExxonMobil 등)이 이미 Quantum Computing (양자 컴퓨팅)을 탐색하고 있습니다. Quantum Computing (양자 컴퓨팅)은 학습 곡선이 가파르기 때문에, 조기에 학습하고 실험하는 것이 경쟁 우위로 이어질 수 있습니다. 지금 뛰어들어 quantum ready (양자 준비)가 되는 조직은 이러한 기술이 발전함에 따라 뚜렷한 이점을 가질 것입니다. 이것은 양자 컴퓨팅의 비즈니스 케이스를 지지하는 중요한 요소입니다. 선도 기업들이 이미 실제 양자 컴퓨터로 실험하고 있으며, 조기 시작이 경쟁 우위로 이어질 수 있다는 것은 양자 컴퓨팅의 비즈니스 가치를 보여줍니다.</li></ul></details><h2 id="문제-17-양자-컴퓨팅의-잠재적-응용-분야" tabindex="-1"><a class="header-anchor" href="#문제-17-양자-컴퓨팅의-잠재적-응용-분야"><span>문제 17: 양자 컴퓨팅의 잠재적 응용 분야</span></a></h2><div class="hint-container tip"><p class="hint-container-title">문제 제시</p><p>양자 컴퓨팅의 잠재적 응용 분야는 무엇입니까? (하나 이상 선택)</p><p>Which of the following is/are a potential application for quantum computing? Select all that apply.</p><ul><li>A. Managing risks and opportunities related to financial portfolios (금융 포트폴리오와 관련된 리스크와 기회 관리)</li><li>B. Processing and storing big data (빅 데이터 처리 및 저장)</li><li>C. Discovering new drugs and protein structures (신약 및 단백질 구조 발견)</li><li>D. Simulating quantum dynamics to advance materials discovery (재료 발견을 위한 양자 역학 시뮬레이션)</li></ul></div><h3 id="필요한-기반-지식-16" tabindex="-1"><a class="header-anchor" href="#필요한-기반-지식-16"><span>필요한 기반 지식</span></a></h3><h4 id="_1-quantum-computing-양자-컴퓨팅-의-주요-응용-분야" tabindex="-1"><a class="header-anchor" href="#_1-quantum-computing-양자-컴퓨팅-의-주요-응용-분야"><span>1. Quantum Computing (양자 컴퓨팅)의 주요 응용 분야</span></a></h4><p><strong>Simulation (시뮬레이션):</strong></p><ul><li>이미 quantum mechanical (양자역학적) 특성을 지닌 물리적 또는 화학적 시스템의 시뮬레이션</li><li>분자 구조 및 화학 반응 시뮬레이션</li><li>신소재 설계 (고용량 배터리, 탄소 포집 등)</li><li>비료와 같은 화학 구조 설계</li><li>재료 발견을 위한 양자 역학 시뮬레이션</li></ul><p><strong>Optimization (최적화):</strong></p><ul><li>복잡한 문제, 일반적으로 최소화 문제로 표현되는 문제에 대한 최적의 해법을 찾는 것</li><li>Supply chain (공급망) 최적화</li><li>금융 포트폴리오 최적화</li><li>Logistics (물류) 최적화</li></ul><p><strong>복잡한 구조를 가진 데이터:</strong></p><ul><li>Quantum Computing (양자 컴퓨팅)을 활용하여 machine learning (머신러닝) 및 data science (데이터 과학) 분야의 새로운 모델을 탐구합니다</li><li>Quantum machine learning (양자 머신러닝)</li><li>Pattern recognition (패턴 인식)</li><li>Data analysis (데이터 분석)</li></ul><h4 id="_2-금융-서비스-financial-services-응용" tabindex="-1"><a class="header-anchor" href="#_2-금융-서비스-financial-services-응용"><span>2. 금융 서비스 (Financial Services) 응용</span></a></h4><p><strong>포트폴리오 최적화 및 리스크 관리:</strong></p><ul><li>Banking (은행) 산업에서 Portfolio optimization (포트폴리오 최적화), Corporate risk simulation (기업 리스크 시뮬레이션)이 사용 사례에 포함됩니다</li><li>JPMorgan Chase와 Goldman Sachs와 같은 Wall Street (월스트리트) 거대 기업들은 Quantum Computing (양자 컴퓨팅)이 확률에서 우위를 제공하여 포트폴리오와 관련된 위협과 기회를 더 잘 관리할 수 있기를 희망합니다</li><li>Quantum computer (양자 컴퓨터)는 또한 금융 전문가들이 Monte Carlo simulation (몬테카를로 시뮬레이션)을 개선하는 데 도움을 줄 수 있습니다</li></ul><p><strong>금융 시뮬레이션:</strong></p><ul><li>Monte Carlo simulation (몬테카를로 시뮬레이션)은 복잡한 의사결정 트리의 가능한 결과를 예측하여 이익을 극대화하는 수학적 모델입니다</li><li>연구자들은 전통적인 Monte Carlo sampling (몬테카를로 샘플링) 접근 방식을 능가하는 quantum algorithm (양자 알고리즘)을 개발했습니다</li><li>Financial institution (금융 기관)은 극도로 복잡한 계산을 극적으로 가속화하고 정확도를 개선하기 위해 Quantum Computing (양자 컴퓨팅)을 탐색합니다</li></ul><h4 id="_3-생명과학-life-sciences-응용" tabindex="-1"><a class="header-anchor" href="#_3-생명과학-life-sciences-응용"><span>3. 생명과학 (Life Sciences) 응용</span></a></h4><p><strong>신약 및 단백질 구조 발견:</strong></p><ul><li>Life sciences (생명과학)에서 Quantum Computing (양자 컴퓨팅)은 새로운 약물 및 단백질 구조의 발견을 발전시킬 수 있습니다</li><li>Life Sciences (생명과학) 산업에서 Efficient drug R&amp;D (효율적인 신약 연구개발), Tractable protein folding (처리 가능한 단백질 접힘)이 사용 사례에 포함됩니다</li><li>3차원(3D) 단백질 구조가 신약 발견에서 차지하는 중심 역할은 수년간 연구되어 왔습니다</li><li>아미노산의 1차 서열로부터 3D 구조를 예측하는 것을 protein folding problem (단백질 접힘 문제)이라고 합니다</li><li>연구자들은 Quantum Computing (양자 컴퓨팅)이 이 문제를 해결하는 데 사용될 수 있는 방법을 입증했습니다</li></ul><h4 id="_4-재료-과학-materials-science-응용" tabindex="-1"><a class="header-anchor" href="#_4-재료-과학-materials-science-응용"><span>4. 재료 과학 (Materials Science) 응용</span></a></h4><p><strong>재료 발견을 위한 양자 역학 시뮬레이션:</strong></p><ul><li>Simulation (시뮬레이션)은 이미 quantum mechanical (양자역학적) 특성을 지닌 물리적 또는 화학적 시스템의 시뮬레이션입니다</li><li>신소재 설계 (고용량 배터리, 탄소 포집 등)가 포함됩니다</li><li>Classical supercomputer (고전 슈퍼컴퓨터)는 분자 행동 모델링과 같이 많은 변수가 복잡한 방식으로 상호작용하는 문제를 해결하는 데 어려움을 겪습니다</li><li>Quantum (양자)은 복잡성의 장벽을 넘어서는 데 도움을 줄 수 있습니다</li><li>Quantum (양자)은 natural system (자연 시스템)의 시뮬레이션, 유용한 신소재의 창조와 같은 영역에서 가장 큰 영향을 미칠 것으로 예상됩니다</li></ul><p><strong>재료 개발 사례:</strong></p><ul><li>Daimler Mercedes-Benz는 운송 물류 및 차량 배터리의 화학을 최적화하기 위해 Quantum Computing (양자 컴퓨팅)을 사용했습니다</li><li>모든 다양한 분자 특성과 행동을 시뮬레이션하는 것은 오늘날의 supercomputer (슈퍼컴퓨터)의 현재 컴퓨팅 능력을 넘어서는 것입니다</li><li>Quantum Computing (양자 컴퓨팅)은 시뮬레이션 프로세스를 가속화하는 잠재적 방법을 제공합니다</li></ul><h4 id="_5-빅-데이터-처리의-한계" tabindex="-1"><a class="header-anchor" href="#_5-빅-데이터-처리의-한계"><span>5. 빅 데이터 처리의 한계</span></a></h4><p><strong>Poor Choices (나쁜 선택)의 특성:</strong></p><ul><li>Poor choices (나쁜 선택)에는 &quot;Involve the use of large volumes of data for inputs or processing (입력 또는 처리에 대용량 데이터 사용이 필요)&quot;가 포함됩니다</li><li>양자 컴퓨터는 현재 제한된 데이터 처리 능력을 가지고 있습니다</li><li>빅 데이터 처리 및 저장은 양자 컴퓨팅의 잠재적 응용 분야가 아닙니다</li></ul><p><strong>양자 컴퓨팅의 데이터 처리 한계:</strong></p><ul><li>양자 컴퓨팅은 특정 유형의 문제(시뮬레이션, 최적화 등)에 강점을 가지고 있습니다</li><li>하지만 대용량 데이터 처리 및 저장에는 적합하지 않습니다</li><li>이것은 양자 컴퓨팅의 한계 중 하나입니다</li></ul><h4 id="_6-양자-컴퓨팅의-강점과-한계" tabindex="-1"><a class="header-anchor" href="#_6-양자-컴퓨팅의-강점과-한계"><span>6. 양자 컴퓨팅의 강점과 한계</span></a></h4><p><strong>양자 컴퓨팅의 강점:</strong></p><ul><li>Simulation (시뮬레이션): 양자역학적 시스템의 시뮬레이션</li><li>Optimization (최적화): 복잡한 최적화 문제 해결</li><li>특정 알고리즘: Monte Carlo simulation (몬테카를로 시뮬레이션) 개선 등</li></ul><p><strong>양자 컴퓨팅의 한계:</strong></p><ul><li>대용량 데이터 처리 및 저장에는 적합하지 않습니다</li><li>모든 문제에 적용할 수 있는 만능 솔루션은 아닙니다</li><li>특정 유형의 문제에만 강점을 가지고 있습니다</li></ul><h3 id="풀이-과정-16" tabindex="-1"><a class="header-anchor" href="#풀이-과정-16"><span>풀이 과정</span></a></h3><ol><li><p><strong>금융 서비스 응용 확인</strong></p><ul><li>Banking (은행) 산업에서 Portfolio optimization (포트폴리오 최적화), Corporate risk simulation (기업 리스크 시뮬레이션)이 사용 사례에 포함됩니다</li><li>JPMorgan Chase와 Goldman Sachs는 포트폴리오와 관련된 위협과 기회를 더 잘 관리하기를 희망합니다</li><li>이것은 양자 컴퓨팅의 잠재적 응용 분야입니다</li></ul></li><li><p><strong>생명과학 응용 확인</strong></p><ul><li>Life sciences (생명과학)에서 Quantum Computing (양자 컴퓨팅)은 새로운 약물 및 단백질 구조의 발견을 발전시킬 수 있습니다</li><li>Efficient drug R&amp;D (효율적인 신약 연구개발), Tractable protein folding (처리 가능한 단백질 접힘)이 사용 사례에 포함됩니다</li><li>이것은 양자 컴퓨팅의 잠재적 응용 분야입니다</li></ul></li><li><p><strong>재료 과학 응용 확인</strong></p><ul><li>Simulation (시뮬레이션)은 이미 quantum mechanical (양자역학적) 특성을 지닌 물리적 또는 화학적 시스템의 시뮬레이션입니다</li><li>신소재 설계 (고용량 배터리, 탄소 포집 등)가 포함됩니다</li><li>재료 발견을 위한 양자 역학 시뮬레이션은 양자 컴퓨팅의 잠재적 응용 분야입니다</li></ul></li><li><p><strong>빅 데이터 처리의 한계 확인</strong></p><ul><li>Poor choices (나쁜 선택)에는 &quot;Involve the use of large volumes of data for inputs or processing&quot;가 포함됩니다</li><li>양자 컴퓨터는 현재 제한된 데이터 처리 능력을 가지고 있습니다</li><li>빅 데이터 처리 및 저장은 양자 컴퓨팅의 잠재적 응용 분야가 아닙니다</li></ul></li><li><p><strong>각 옵션 분석</strong></p><ul><li><strong>A. Managing risks and opportunities related to financial portfolios</strong>: Banking (은행) 산업에서 Portfolio optimization (포트폴리오 최적화), Corporate risk simulation (기업 리스크 시뮬레이션)이 사용 사례에 포함됩니다.</li><li><strong>B. Processing and storing big data</strong>: Poor choices (나쁜 선택)에는 &quot;Involve the use of large volumes of data for inputs or processing&quot;가 포함됩니다. 양자 컴퓨터는 현재 제한된 데이터 처리 능력을 가지고 있습니다.</li><li><strong>C. Discovering new drugs and protein structures</strong>: Life sciences (생명과학)에서 Quantum Computing (양자 컴퓨팅)은 새로운 약물 및 단백질 구조의 발견을 발전시킬 수 있습니다.</li><li><strong>D. Simulating quantum dynamics to advance materials discovery</strong>: Simulation (시뮬레이션)은 이미 quantum mechanical (양자역학적) 특성을 지닌 물리적 또는 화학적 시스템의 시뮬레이션입니다. 신소재 설계가 포함됩니다.</li></ul></li></ol><details class="hint-container details"><summary>최종 답안</summary><p><strong>결론 도출</strong></p><ul><li>A, C, D는 모두 양자 컴퓨팅의 잠재적 응용 분야입니다</li><li>B는 양자 컴퓨팅의 한계에 해당합니다</li></ul><p><strong>A. Managing risks and opportunities related to financial portfolios.</strong></p><ul><li>Banking (은행) 산업에서 Portfolio optimization (포트폴리오 최적화), Corporate risk simulation (기업 리스크 시뮬레이션)이 사용 사례에 포함됩니다. JPMorgan Chase와 Goldman Sachs와 같은 Wall Street (월스트리트) 거대 기업들은 Quantum Computing (양자 컴퓨팅)이 확률에서 우위를 제공하여 포트폴리오와 관련된 위협과 기회를 더 잘 관리할 수 있기를 희망합니다. Quantum computer (양자 컴퓨터)는 또한 금융 전문가들이 Monte Carlo simulation (몬테카를로 시뮬레이션)을 개선하는 데 도움을 줄 수 있습니다. 이것은 양자 컴퓨팅의 잠재적 응용 분야입니다.</li></ul><p><strong>C. Discovering new drugs and protein structures.</strong></p><ul><li>Life sciences (생명과학)에서 Quantum Computing (양자 컴퓨팅)은 새로운 약물 및 단백질 구조의 발견을 발전시킬 수 있습니다. Life Sciences (생명과학) 산업에서 Efficient drug R&amp;D (효율적인 신약 연구개발), Tractable protein folding (처리 가능한 단백질 접힘)이 사용 사례에 포함됩니다. 3차원(3D) 단백질 구조가 신약 발견에서 차지하는 중심 역할은 수년간 연구되어 왔으며, 아미노산의 1차 서열로부터 3D 구조를 예측하는 것을 protein folding problem (단백질 접힘 문제)이라고 합니다. 연구자들은 Quantum Computing (양자 컴퓨팅)이 이 문제를 해결하는 데 사용될 수 있는 방법을 입증했습니다. 이것은 양자 컴퓨팅의 잠재적 응용 분야입니다.</li></ul><p><strong>D. Simulating quantum dynamics to advance materials discovery.</strong></p><ul><li>Simulation (시뮬레이션)은 이미 quantum mechanical (양자역학적) 특성을 지닌 물리적 또는 화학적 시스템의 시뮬레이션입니다. 신소재 설계 (고용량 배터리, 탄소 포집 등)가 포함됩니다. Classical supercomputer (고전 슈퍼컴퓨터)는 분자 행동 모델링과 같이 많은 변수가 복잡한 방식으로 상호작용하는 문제를 해결하는 데 어려움을 겪습니다. Quantum (양자)은 복잡성의 장벽을 넘어서는 데 도움을 줄 수 있으며, natural system (자연 시스템)의 시뮬레이션, 유용한 신소재의 창조와 같은 영역에서 가장 큰 영향을 미칠 것으로 예상됩니다. 재료 발견을 위한 양자 역학 시뮬레이션은 양자 컴퓨팅의 잠재적 응용 분야입니다.</li></ul><p><strong>B는</strong> Poor choices (나쁜 선택)에는 &quot;Involve the use of large volumes of data for inputs or processing (입력 또는 처리에 대용량 데이터 사용이 필요)&quot;가 포함됩니다. 양자 컴퓨터는 현재 제한된 데이터 처리 능력을 가지고 있습니다. 빅 데이터 처리 및 저장은 양자 컴퓨팅의 잠재적 응용 분야가 아닙니다. 양자 컴퓨팅은 특정 유형의 문제(시뮬레이션, 최적화 등)에 강점을 가지고 있지만, 대용량 데이터 처리 및 저장에는 적합하지 않습니다.</p></details><h2 id="문제-18-양자-컴퓨터에서-monte-carlo-샘플링-시뮬레이션-결과" tabindex="-1"><a class="header-anchor" href="#문제-18-양자-컴퓨터에서-monte-carlo-샘플링-시뮬레이션-결과"><span>문제 18: 양자 컴퓨터에서 Monte Carlo 샘플링 시뮬레이션 결과</span></a></h2><div class="hint-container tip"><p class="hint-container-title">문제 제시</p><p>양자 컴퓨터에서 Monte Carlo 샘플링을 시뮬레이션한 결과, 연구자들은 무엇을 발견했습니까? (하나 이상 선택)</p><p>By simulating Monte Carlo sampling on a quantum computer, researchers found:</p><ul><li>A. A quantum computer requires more samples than a classical computer would. (양자 컴퓨터는 고전 컴퓨터보다 더 많은 샘플이 필요합니다)</li><li>B. For a fixed amount of time, a quantum computer can give you more confidence in your answer than a classical Monte Carlo simulation would. (고정된 시간에 양자 컴퓨터는 고전 Monte Carlo 시뮬레이션보다 답에 대해 더 많은 신뢰를 제공할 수 있습니다)</li><li>C. You can get to a fixed confidence level faster with a quantum computer. (양자 컴퓨터로 고정된 신뢰 수준에 더 빠르게 도달할 수 있습니다)</li><li>D. Quantum computers could help improve mathematical models that predict possible outcomes of complicated decision trees to maximize profit in the financial industry. (양자 컴퓨터는 금융 산업에서 복잡한 의사결정 트리의 가능한 결과를 예측하여 이익을 극대화하는 수학적 모델을 개선하는 데 도움이 될 수 있습니다)</li></ul></div><h3 id="필요한-기반-지식-17" tabindex="-1"><a class="header-anchor" href="#필요한-기반-지식-17"><span>필요한 기반 지식</span></a></h3><h4 id="_1-monte-carlo-simulation-몬테카를로-시뮬레이션-의-정의" tabindex="-1"><a class="header-anchor" href="#_1-monte-carlo-simulation-몬테카를로-시뮬레이션-의-정의"><span>1. Monte Carlo Simulation (몬테카를로 시뮬레이션)의 정의</span></a></h4><p><strong>정의:</strong></p><ul><li>Monte Carlo simulation (몬테카를로 시뮬레이션)은 복잡한 의사결정 트리의 가능한 결과를 예측하여 이익을 극대화하는 수학적 모델입니다</li><li>Monte Carlo simulation (몬테카를로 시뮬레이션)에서 컴퓨터는 주어진 확률 분포에서 많은 무작위 샘플을 취하여 어떤 결과가 가장 가능성이 높은지 확인합니다</li><li>이것은 금융 산업에서 널리 사용됩니다</li></ul><p><strong>금융 산업에서의 사용:</strong></p><ul><li>Banking (은행), financial market (금융 시장), insurance (보험) 회사는 리스크 관리에 관한 것입니다</li><li>JPMorgan Chase와 Goldman Sachs와 같은 Wall Street (월스트리트) 거대 기업들은 Quantum Computing (양자 컴퓨팅)이 확률에서 우위를 제공하여 포트폴리오와 관련된 위협과 기회를 더 잘 관리할 수 있기를 희망합니다</li><li>Quantum computer (양자 컴퓨터)는 또한 금융 전문가들이 Monte Carlo simulation (몬테카를로 시뮬레이션)을 개선하는 데 도움을 줄 수 있습니다</li></ul><h4 id="_2-quantum-algorithm-양자-알고리즘-의-우위" tabindex="-1"><a class="header-anchor" href="#_2-quantum-algorithm-양자-알고리즘-의-우위"><span>2. Quantum Algorithm (양자 알고리즘)의 우위</span></a></h4><p><strong>연구 결과:</strong></p><ul><li>연구자들은 전통적인 Monte Carlo sampling (몬테카를로 샘플링) 접근 방식을 능가하는 quantum algorithm (양자 알고리즘)을 개발했습니다</li><li>Monte Carlo simulation (몬테카를로 시뮬레이션)의 예측 결과 오류를 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi mathvariant="normal">/</mi><mi>X</mi></mrow><annotation encoding="application/x-tex">1/X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/</span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span>만큼 줄이려면: <ul><li>전통적인 샘플이 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">X^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span>개 더 필요합니다</li><li>Quantum sample (양자 샘플)은 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi></mrow><annotation encoding="application/x-tex">X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span>개만 더 필요합니다</li></ul></li></ul><p><strong>Quadratic Speedup (2차 속도 향상):</strong></p><ul><li>이것은 quadratic speedup (2차 속도 향상)을 의미합니다</li><li>양자 알고리즘은 고전 알고리즘보다 훨씬 효율적입니다</li><li>샘플 수가 증가함에 따라 Quantum algorithm (양자 알고리즘)은 Monte Carlo (몬테카를로) 방법보다 훨씬 빠르게 오류를 줄입니다</li></ul><h4 id="_3-양자-컴퓨터의-두-가지-이점" tabindex="-1"><a class="header-anchor" href="#_3-양자-컴퓨터의-두-가지-이점"><span>3. 양자 컴퓨터의 두 가지 이점</span></a></h4><p><strong>이점 1: 고정된 신뢰 수준에 더 빠르게 도달</strong></p><ul><li>Quantum computer (양자 컴퓨터)로 고정된 신뢰 수준에 더 빠르게 도달할 수 있습니다</li><li>같은 신뢰 수준을 달성하는 데 필요한 샘플 수가 적기 때문입니다</li><li>전통적인 샘플이 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">X^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span>개 더 필요하지만, quantum sample (양자 샘플)은 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi></mrow><annotation encoding="application/x-tex">X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span>개만 더 필요합니다</li></ul><p><strong>이점 2: 고정된 시간에 더 많은 신뢰 제공</strong></p><ul><li>고정된 시간에 quantum computer (양자 컴퓨터)는 classical Monte Carlo solution (고전 몬테카를로 솔루션)보다 답에 대해 더 많은 신뢰를 제공할 수 있습니다</li><li>같은 시간에 더 많은 샘플을 처리할 수 있기 때문입니다</li><li>또는 같은 샘플 수로 더 정확한 결과를 얻을 수 있습니다</li></ul><h4 id="_4-성능-비교" tabindex="-1"><a class="header-anchor" href="#_4-성능-비교"><span>4. 성능 비교</span></a></h4><p><strong>실제 성능:</strong></p><ul><li>특히 16개 샘플 이후에는 Quantum algorithm (양자 알고리즘)이 더 낮은 estimation error (추정 오류)를 달성합니다</li><li>예를 들어, 128개 샘플에서 Quantum algorithm (양자 알고리즘)의 오류는 약 0.03인 반면, Monte Carlo (몬테카를로) 방법의 오류는 약 0.09입니다</li><li>이것은 양자 알고리즘이 고전 알고리즘보다 훨씬 정확함을 보여줍니다</li></ul><h4 id="_5-금융-산업에서의-응용" tabindex="-1"><a class="header-anchor" href="#_5-금융-산업에서의-응용"><span>5. 금융 산업에서의 응용</span></a></h4><p><strong>수학적 모델 개선:</strong></p><ul><li>Monte Carlo simulation (몬테카를로 시뮬레이션)은 복잡한 의사결정 트리의 가능한 결과를 예측하여 이익을 극대화하는 수학적 모델입니다</li><li>Quantum computers (양자 컴퓨터)는 이러한 수학적 모델을 개선하는 데 도움이 될 수 있습니다</li><li>Financial institution (금융 기관)은 극도로 복잡한 계산을 극적으로 가속화하고 정확도를 개선하기 위해 Quantum Computing (양자 컴퓨팅)을 탐색합니다</li></ul><p><strong>실제 사용 사례:</strong></p><ul><li>연구자들은 option pricing (옵션 가격 책정)을 위한 quantum finance simulator (양자 금융 시뮬레이터)를 만들었습니다</li><li>Quantum Network 회원들이 finance와 Quantum Computing (양자 컴퓨팅)을 실험하고 있습니다</li><li>JPMorgan Chase는 IBM Quantum과 파트너십을 맺어 금융 옵션의 가격을 예측하고 사기 탐지 및 신용도 결정을 개선했습니다</li></ul><h4 id="_6-샘플-수의-비교" tabindex="-1"><a class="header-anchor" href="#_6-샘플-수의-비교"><span>6. 샘플 수의 비교</span></a></h4><p><strong>양자 vs 고전:</strong></p><ul><li>Monte Carlo simulation (몬테카를로 시뮬레이션)의 예측 결과 오류를 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi mathvariant="normal">/</mi><mi>X</mi></mrow><annotation encoding="application/x-tex">1/X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/</span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span>만큼 줄이려면: <ul><li>전통적인 샘플이 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">X^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span>개 더 필요합니다</li><li>Quantum sample (양자 샘플)은 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi></mrow><annotation encoding="application/x-tex">X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span>개만 더 필요합니다</li></ul></li><li>이것은 양자 컴퓨터가 고전 컴퓨터보다 더 적은 샘플이 필요함을 의미합니다</li><li>양자 컴퓨터가 고전 컴퓨터보다 더 많은 샘플이 필요하다는 것은 틀렸습니다</li></ul><h3 id="풀이-과정-17" tabindex="-1"><a class="header-anchor" href="#풀이-과정-17"><span>풀이 과정</span></a></h3><ol><li><p><strong>Monte Carlo Simulation (몬테카를로 시뮬레이션)의 정의 확인</strong></p><ul><li>Monte Carlo simulation (몬테카를로 시뮬레이션)은 복잡한 의사결정 트리의 가능한 결과를 예측하여 이익을 극대화하는 수학적 모델입니다</li><li>이것은 금융 산업에서 널리 사용됩니다</li></ul></li><li><p><strong>Quantum Algorithm (양자 알고리즘)의 우위 확인</strong></p><ul><li>Monte Carlo simulation (몬테카를로 시뮬레이션)의 예측 결과 오류를 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi mathvariant="normal">/</mi><mi>X</mi></mrow><annotation encoding="application/x-tex">1/X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/</span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span>만큼 줄이려면: <ul><li>전통적인 샘플이 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">X^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span>개 더 필요합니다</li><li>Quantum sample (양자 샘플)은 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi></mrow><annotation encoding="application/x-tex">X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span>개만 더 필요합니다</li></ul></li><li>이것은 양자 컴퓨터가 고전 컴퓨터보다 더 적은 샘플이 필요함을 의미합니다</li></ul></li><li><p><strong>양자 컴퓨터의 두 가지 이점 확인</strong></p><ul><li>(1) Quantum computer (양자 컴퓨터)로 고정된 신뢰 수준에 더 빠르게 도달할 수 있습니다</li><li>(2) 고정된 시간에 quantum computer (양자 컴퓨터)는 classical Monte Carlo solution (고전 몬테카를로 솔루션)보다 답에 대해 더 많은 신뢰를 제공할 수 있습니다</li></ul></li><li><p><strong>금융 산업에서의 응용 확인</strong></p><ul><li>Quantum computers (양자 컴퓨터)는 복잡한 의사결정 트리의 가능한 결과를 예측하여 이익을 극대화하는 수학적 모델을 개선하는 데 도움이 될 수 있습니다</li><li>이것은 금융 산업에서의 실제 응용입니다</li></ul></li><li><p><strong>각 옵션 분석</strong></p><ul><li><strong>A. A quantum computer requires more samples than a classical computer would</strong>: Monte Carlo simulation (몬테카를로 시뮬레이션)의 예측 결과 오류를 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi mathvariant="normal">/</mi><mi>X</mi></mrow><annotation encoding="application/x-tex">1/X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/</span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span>만큼 줄이려면 전통적인 샘플이 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">X^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span>개 더 필요하지만, quantum sample (양자 샘플)은 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi></mrow><annotation encoding="application/x-tex">X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span>개만 더 필요합니다. 이것은 양자 컴퓨터가 고전 컴퓨터보다 더 적은 샘플이 필요함을 의미합니다.</li><li><strong>B. For a fixed amount of time, a quantum computer can give you more confidence in your answer than a classical Monte Carlo simulation would</strong>: 고정된 시간에 quantum computer (양자 컴퓨터)는 classical Monte Carlo solution (고전 몬테카를로 솔루션)보다 답에 대해 더 많은 신뢰를 제공할 수 있습니다. 이것은 문서에서 명확히 언급된 내용입니다.</li><li><strong>C. You can get to a fixed confidence level faster with a quantum computer</strong>: Quantum computer (양자 컴퓨터)로 고정된 신뢰 수준에 더 빠르게 도달할 수 있습니다. 이것은 문서에서 명확히 언급된 내용입니다.</li><li><strong>D. Quantum computers could help improve mathematical models that predict possible outcomes of complicated decision trees to maximize profit in the financial industry</strong>: Monte Carlo simulation (몬테카를로 시뮬레이션)은 복잡한 의사결정 트리의 가능한 결과를 예측하여 이익을 극대화하는 수학적 모델입니다. Quantum computers (양자 컴퓨터)는 이러한 수학적 모델을 개선하는 데 도움이 될 수 있습니다. 이것은 금융 산업에서의 실제 응용입니다.</li></ul></li></ol><details class="hint-container details"><summary>최종 답안</summary><p><strong>결론 도출</strong></p><ul><li>B, C, D는 모두 양자 컴퓨터에서 Monte Carlo 샘플링 시뮬레이션 결과를 정확히 반영합니다</li><li>A는 양자 컴퓨터와 고전 컴퓨터의 샘플 수 요구사항을 반대로 설명한 것입니다</li></ul><p><strong>B. For a fixed amount of time, a quantum computer can give you more confidence in your answer than a classical Monte Carlo simulation would.</strong></p><ul><li>고정된 시간에 quantum computer (양자 컴퓨터)는 classical Monte Carlo solution (고전 몬테카를로 솔루션)보다 답에 대해 더 많은 신뢰를 제공할 수 있습니다. 이것은 문서에서 명확히 언급된 양자 컴퓨터의 두 가지 이점 중 하나입니다. Monte Carlo simulation (몬테카를로 시뮬레이션)의 예측 결과 오류를 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi mathvariant="normal">/</mi><mi>X</mi></mrow><annotation encoding="application/x-tex">1/X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/</span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span>만큼 줄이려면 전통적인 샘플이 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">X^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span>개 더 필요하지만, quantum sample (양자 샘플)은 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi></mrow><annotation encoding="application/x-tex">X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span>개만 더 필요합니다. 같은 시간에 더 많은 샘플을 처리하거나 같은 샘플 수로 더 정확한 결과를 얻을 수 있기 때문에, 고정된 시간에 양자 컴퓨터는 더 많은 신뢰를 제공할 수 있습니다.</li></ul><p><strong>C. You can get to a fixed confidence level faster with a quantum computer.</strong></p><ul><li>Quantum computer (양자 컴퓨터)로 고정된 신뢰 수준에 더 빠르게 도달할 수 있습니다. 이것은 문서에서 명확히 언급된 양자 컴퓨터의 두 가지 이점 중 하나입니다. Monte Carlo simulation (몬테카를로 시뮬레이션)의 예측 결과 오류를 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi mathvariant="normal">/</mi><mi>X</mi></mrow><annotation encoding="application/x-tex">1/X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/</span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span>만큼 줄이려면 전통적인 샘플이 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">X^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span>개 더 필요하지만, quantum sample (양자 샘플)은 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi></mrow><annotation encoding="application/x-tex">X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span>개만 더 필요합니다. 같은 신뢰 수준을 달성하는 데 필요한 샘플 수가 적기 때문에, 양자 컴퓨터로 고정된 신뢰 수준에 더 빠르게 도달할 수 있습니다.</li></ul><p><strong>D. Quantum computers could help improve mathematical models that predict possible outcomes of complicated decision trees to maximize profit in the financial industry.</strong></p><ul><li>Monte Carlo simulation (몬테카를로 시뮬레이션)은 복잡한 의사결정 트리의 가능한 결과를 예측하여 이익을 극대화하는 수학적 모델입니다. Quantum computers (양자 컴퓨터)는 이러한 수학적 모델을 개선하는 데 도움이 될 수 있습니다. Quantum computer (양자 컴퓨터)는 또한 금융 전문가들이 Monte Carlo simulation (몬테카를로 시뮬레이션)을 개선하는 데 도움을 줄 수 있으며, Financial institution (금융 기관)은 극도로 복잡한 계산을 극적으로 가속화하고 정확도를 개선하기 위해 Quantum Computing (양자 컴퓨팅)을 탐색합니다. 이것은 금융 산업에서의 실제 응용입니다.</li></ul><p><strong>A는</strong> Monte Carlo simulation (몬테카를로 시뮬레이션)의 예측 결과 오류를 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi mathvariant="normal">/</mi><mi>X</mi></mrow><annotation encoding="application/x-tex">1/X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/</span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span>만큼 줄이려면 전통적인 샘플이 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">X^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span>개 더 필요하지만, quantum sample (양자 샘플)은 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi></mrow><annotation encoding="application/x-tex">X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span>개만 더 필요합니다. 이것은 양자 컴퓨터가 고전 컴퓨터보다 더 적은 샘플이 필요함을 의미합니다. 양자 컴퓨터가 고전 컴퓨터보다 더 많은 샘플이 필요하다는 것은 틀렸습니다. 양자 알고리즘은 고전 알고리즘보다 훨씬 효율적이며, quadratic speedup (2차 속도 향상)을 제공합니다.</p></details><h2 id="문제-19-양자-물리학의-반직관적인-개념" tabindex="-1"><a class="header-anchor" href="#문제-19-양자-물리학의-반직관적인-개념"><span>문제 19: 양자 물리학의 반직관적인 개념</span></a></h2><div class="hint-container tip"><p class="hint-container-title">문제 제시</p><p>양자 물리학에는 다음과 같은 반직관적인 개념들이 포함되어 있습니다: (하나 이상 선택)</p><p>Quantum physics contains some counterintuitive ideas, such as:</p><ul><li>A. Qubits can only represent a 0 or 1. (큐비트는 0 또는 1만 나타낼 수 있습니다)</li><li>B. Two systems that are too far apart to influence each other are somehow strongly correlated. (서로 영향을 미치기에는 너무 멀리 떨어져 있는 두 시스템이 어떻게든 강하게 상관관계를 가집니다)</li><li>C. A physical system in a definite state can still behave randomly. (명확한 상태에 있는 물리적 시스템이 여전히 무작위로 행동할 수 있습니다)</li><li>D. It is possible to have a state in a quantum system that cannot be described as the product of the independent components of the qubits that make up the state. (상태를 구성하는 큐비트의 독립적인 구성 요소의 곱으로 설명할 수 없는 양자 시스템의 상태가 가능합니다)</li></ul></div><h3 id="필요한-기반-지식-18" tabindex="-1"><a class="header-anchor" href="#필요한-기반-지식-18"><span>필요한 기반 지식</span></a></h3><h4 id="_1-qubit-큐비트-의-특성" tabindex="-1"><a class="header-anchor" href="#_1-qubit-큐비트-의-특성"><span>1. Qubit (큐비트)의 특성</span></a></h4><p><strong>Qubit (큐비트) vs Bit (비트):</strong></p><ul><li>Classical information (고전 정보)의 주요 단위인 bit (비트)는 0 또는 1의 값을 가질 수 있습니다</li><li>Quantum information (양자 정보)의 주요 단위인 qubit (큐비트)는 0, 1, 또는 둘 다의 조합을 나타낼 수 있으며, 이는 superposition (중첩)이라는 속성입니다</li><li>Qubit (큐비트)는 0과 1만 나타낼 수 있는 것이 아닙니다</li></ul><p><strong>Superposition (중첩)의 의미:</strong></p><ul><li><strong>Superposition (중첩)</strong>은 두 개 이상의 상태의 가중 합 또는 차이입니다</li><li>Quantum computer (양자 컴퓨터)는 한 번에 지수적으로 많은 논리적 상태를 허용하는 특별한 종류의 superposition (중첩)을 활용합니다</li><li>이것은 강력한 업적이며, 어떤 classical computer (고전 컴퓨터)도 이를 달성할 수 없습니다</li></ul><p><strong>측정의 특성:</strong></p><ul><li>상태의 superposition (중첩)에 있는 시스템을 측정할 때 시스템이 순수한 상태 중 하나로 붕괴됩니다</li><li>이것은 양자 측정의 확률적 특성을 나타냅니다</li></ul><h4 id="_2-entanglement-얽힘-의-개념" tabindex="-1"><a class="header-anchor" href="#_2-entanglement-얽힘-의-개념"><span>2. Entanglement (얽힘)의 개념</span></a></h4><p><strong>Entanglement (얽힘)의 정의:</strong></p><ul><li><strong>Entanglement (얽힘)</strong>은 quantum mechanics (양자 역학)의 또 다른 핵심 개념입니다</li><li>두 개 이상의 qubit (큐비트)가 얽혀 있을 때, 그들의 상태는 개별적으로 설명할 수 없게 됩니다</li><li>대신, 전체 시스템의 상태만이 의미가 있습니다</li></ul><p><strong>Entanglement (얽힘)의 반직관적 특성:</strong></p><ul><li>이러한 quantum superposition (양자 중첩)의 대부분과 quantum computation (양자 계산)에 가장 유용한 것들은 entangled (얽혀 있습니다)—이는 개별 qubit (큐비트)의 digital (디지털) 또는 analog (아날로그) 상태의 할당에 해당하지 않는 전체 컴퓨터의 상태입니다</li><li>두 시스템이 서로 영향을 미치기에는 너무 멀리 떨어져 있어도, 얽힌 상태에서는 강하게 상관관계를 가집니다</li><li>이것은 양자 물리학의 반직관적인 개념 중 하나입니다</li></ul><p><strong>Entanglement (얽힘)의 계산 능력:</strong></p><ul><li>Entanglement (얽힘)는 quantum computer (양자 컴퓨터)에 강력한 계산 능력을 제공합니다</li><li>얽힌 qubit (큐비트)는 독립적으로 작동하는 qubit (큐비트)보다 훨씬 더 많은 정보를 저장하고 처리할 수 있습니다</li></ul><h4 id="_3-양자-측정의-확률적-특성" tabindex="-1"><a class="header-anchor" href="#_3-양자-측정의-확률적-특성"><span>3. 양자 측정의 확률적 특성</span></a></h4><p><strong>명확한 상태와 무작위 행동:</strong></p><ul><li>양자 시스템은 명확한 상태(superposition 상태)에 있을 수 있지만, 측정할 때 무작위로 행동합니다</li><li>상태의 superposition (중첩)에 있는 시스템을 측정할 때 시스템이 순수한 상태 중 하나로 붕괴됩니다</li><li>이것은 양자 물리학의 반직관적인 개념 중 하나입니다</li></ul><p><strong>Classical vs Quantum Probability (고전 vs 양자 확률):</strong></p><ul><li>Classical probability (고전 확률)과 quantum probability (양자 확률)의 차이를 이해하는 것이 중요합니다</li><li>Classical probability (고전 확률)는 우리가 모르는 정보에 대한 불확실성을 나타내는 반면, quantum probability (양자 확률)는 시스템이 실제로 여러 상태의 superposition (중첩)에 있다는 것을 나타냅니다</li></ul><h4 id="_4-product-state-곱-상태-vs-entangled-state-얽힘-상태" tabindex="-1"><a class="header-anchor" href="#_4-product-state-곱-상태-vs-entangled-state-얽힘-상태"><span>4. Product State (곱 상태) vs Entangled State (얽힘 상태)</span></a></h4><p><strong>Product State (곱 상태):</strong></p><ul><li>Product state (곱 상태)는 각 qubit (큐비트)의 독립적인 상태의 곱으로 설명할 수 있는 상태입니다</li><li>예를 들어, <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi mathvariant="normal">∣</mi><mn>0</mn><mo stretchy="false">⟩</mo><mo>⊗</mo><mi mathvariant="normal">∣</mi><mn>1</mn><mo stretchy="false">⟩</mo></mrow><annotation encoding="application/x-tex">|0\\rangle \\otimes |1\\rangle</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣0</span><span class="mclose">⟩</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⊗</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣1</span><span class="mclose">⟩</span></span></span></span>은 product state (곱 상태)입니다</li></ul><p><strong>Entangled State (얽힘 상태):</strong></p><ul><li>Entangled state (얽힘 상태)는 각 qubit (큐비트)의 독립적인 상태의 곱으로 설명할 수 없는 상태입니다</li><li>이러한 quantum superposition (양자 중첩)의 대부분과 quantum computation (양자 계산)에 가장 유용한 것들은 entangled (얽혀 있습니다)—이는 개별 qubit (큐비트)의 digital (디지털) 또는 analog (아날로그) 상태의 할당에 해당하지 않는 전체 컴퓨터의 상태입니다</li><li>이것은 양자 물리학의 반직관적인 개념 중 하나입니다</li></ul><h4 id="_5-양자-물리학의-반직관적-특성" tabindex="-1"><a class="header-anchor" href="#_5-양자-물리학의-반직관적-특성"><span>5. 양자 물리학의 반직관적 특성</span></a></h4><p><strong>반직관적인 아이디어:</strong></p><ul><li>Quantum physics (양자 물리학)가 어려운 이유는 단순하지만 직관에 반하는 아이디어를 내재화해야 하기 때문입니다</li><li>Quantum computer (양자 컴퓨터)가 존재하는 이유는 우리가 최근에 이 세상에 항상 존재해 왔던 것을 제어하는 방법을 알아냈기 때문입니다: superposition (중첩), entanglement (얽힘), interference (간섭)이라는 quantum phenomenon (양자 현상)입니다</li></ul><p><strong>반직관적인 개념의 예:</strong></p><ul><li>Superposition (중첩): 뒤집힌 동전이 한 번에 앞면과 뒷면 모두의 혼합 상태에 있는 것처럼</li><li>Entanglement (얽힘): 서로 멀리 떨어져 있어도 강하게 상관관계를 가집니다</li><li>측정의 확률적 특성: 명확한 상태에 있어도 무작위로 행동합니다</li><li>Entangled state (얽힘 상태): 개별 구성 요소의 곱으로 설명할 수 없는 상태</li></ul><h3 id="풀이-과정-18" tabindex="-1"><a class="header-anchor" href="#풀이-과정-18"><span>풀이 과정</span></a></h3><ol><li><p><strong>Qubit (큐비트)의 특성 확인</strong></p><ul><li>Qubit (큐비트)는 0, 1, 또는 둘 다의 조합을 나타낼 수 있으며, 이는 superposition (중첩)이라는 속성입니다</li><li>Qubit (큐비트)는 0과 1만 나타낼 수 있는 것이 아닙니다</li><li>이것은 반직관적인 개념이 아니라, 오히려 고전 비트의 특성입니다</li></ul></li><li><p><strong>Entanglement (얽힘)의 개념 확인</strong></p><ul><li>두 개 이상의 qubit (큐비트)가 얽혀 있을 때, 그들의 상태는 개별적으로 설명할 수 없게 됩니다</li><li>두 시스템이 서로 영향을 미치기에는 너무 멀리 떨어져 있어도, 얽힌 상태에서는 강하게 상관관계를 가집니다</li><li>이것은 양자 물리학의 반직관적인 개념 중 하나입니다</li></ul></li><li><p><strong>양자 측정의 확률적 특성 확인</strong></p><ul><li>양자 시스템은 명확한 상태(superposition 상태)에 있을 수 있지만, 측정할 때 무작위로 행동합니다</li><li>상태의 superposition (중첩)에 있는 시스템을 측정할 때 시스템이 순수한 상태 중 하나로 붕괴됩니다</li><li>이것은 양자 물리학의 반직관적인 개념 중 하나입니다</li></ul></li><li><p><strong>Product State (곱 상태) vs Entangled State (얽힘 상태) 확인</strong></p><ul><li>Entangled state (얽힘 상태)는 각 qubit (큐비트)의 독립적인 상태의 곱으로 설명할 수 없는 상태입니다</li><li>이것은 양자 물리학의 반직관적인 개념 중 하나입니다</li></ul></li><li><p><strong>각 옵션 분석</strong></p><ul><li><strong>A. Qubits can only represent a 0 or 1</strong>: Qubit (큐비트)는 0, 1, 또는 둘 다의 조합을 나타낼 수 있으며, 이는 superposition (중첩)이라는 속성입니다. Qubit (큐비트)는 0과 1만 나타낼 수 있는 것이 아닙니다. 이것은 반직관적인 개념이 아니라, 오히려 고전 비트의 특성입니다.</li><li><strong>B. Two systems that are too far apart to influence each other are somehow strongly correlated</strong>: 두 개 이상의 qubit (큐비트)가 얽혀 있을 때, 그들의 상태는 개별적으로 설명할 수 없게 됩니다. 두 시스템이 서로 영향을 미치기에는 너무 멀리 떨어져 있어도, 얽힌 상태에서는 강하게 상관관계를 가집니다. 이것은 양자 물리학의 반직관적인 개념 중 하나입니다.</li><li><strong>C. A physical system in a definite state can still behave randomly</strong>: 양자 시스템은 명확한 상태(superposition 상태)에 있을 수 있지만, 측정할 때 무작위로 행동합니다. 상태의 superposition (중첩)에 있는 시스템을 측정할 때 시스템이 순수한 상태 중 하나로 붕괴됩니다. 이것은 양자 물리학의 반직관적인 개념 중 하나입니다.</li><li><strong>D. It is possible to have a state in a quantum system that cannot be described as the product of the independent components of the qubits that make up the state</strong>: Entangled state (얽힘 상태)는 각 qubit (큐비트)의 독립적인 상태의 곱으로 설명할 수 없는 상태입니다. 이러한 quantum superposition (양자 중첩)의 대부분과 quantum computation (양자 계산)에 가장 유용한 것들은 entangled (얽혀 있습니다)—이는 개별 qubit (큐비트)의 digital (디지털) 또는 analog (아날로그) 상태의 할당에 해당하지 않는 전체 컴퓨터의 상태입니다. 이것은 양자 물리학의 반직관적인 개념 중 하나입니다.</li></ul></li></ol><details class="hint-container details"><summary>최종 답안</summary><p><strong>결론 도출</strong></p><ul><li>B, C, D는 모두 양자 물리학의 반직관적인 개념을 정확히 반영합니다</li><li>A는 고전 비트의 특성을 설명한 것이며, 양자 물리학의 반직관적인 개념이 아닙니다</li></ul><p><strong>B. Two systems that are too far apart to influence each other are somehow strongly correlated.</strong></p><ul><li><strong>Entanglement (얽힘)</strong>은 quantum mechanics (양자 역학)의 또 다른 핵심 개념입니다. 두 개 이상의 qubit (큐비트)가 얽혀 있을 때, 그들의 상태는 개별적으로 설명할 수 없게 됩니다. 대신, 전체 시스템의 상태만이 의미가 있습니다. 두 시스템이 서로 영향을 미치기에는 너무 멀리 떨어져 있어도, 얽힌 상태에서는 강하게 상관관계를 가집니다. 이것은 양자 물리학의 반직관적인 개념 중 하나입니다. Quantum physics (양자 물리학)가 어려운 이유는 단순하지만 직관에 반하는 아이디어를 내재화해야 하기 때문입니다.</li></ul><p><strong>C. A physical system in a definite state can still behave randomly.</strong></p><ul><li>양자 시스템은 명확한 상태(superposition 상태)에 있을 수 있지만, 측정할 때 무작위로 행동합니다. 상태의 superposition (중첩)에 있는 시스템을 측정할 때 시스템이 순수한 상태 중 하나로 붕괴됩니다. 이것은 양자 물리학의 반직관적인 개념 중 하나입니다. Classical probability (고전 확률)과 quantum probability (양자 확률)의 차이를 이해하는 것이 중요합니다. Classical probability (고전 확률)는 우리가 모르는 정보에 대한 불확실성을 나타내는 반면, quantum probability (양자 확률)는 시스템이 실제로 여러 상태의 superposition (중첩)에 있다는 것을 나타냅니다.</li></ul><p><strong>D. It is possible to have a state in a quantum system that cannot be described as the product of the independent components of the qubits that make up the state.</strong></p><ul><li>Entangled state (얽힘 상태)는 각 qubit (큐비트)의 독립적인 상태의 곱으로 설명할 수 없는 상태입니다. 이러한 quantum superposition (양자 중첩)의 대부분과 quantum computation (양자 계산)에 가장 유용한 것들은 entangled (얽혀 있습니다)—이는 개별 qubit (큐비트)의 digital (디지털) 또는 analog (아날로그) 상태의 할당에 해당하지 않는 전체 컴퓨터의 상태입니다. 이것은 양자 물리학의 반직관적인 개념 중 하나입니다. Entanglement (얽힘)는 quantum computer (양자 컴퓨터)에 강력한 계산 능력을 제공하며, 얽힌 qubit (큐비트)는 독립적으로 작동하는 qubit (큐비트)보다 훨씬 더 많은 정보를 저장하고 처리할 수 있습니다.</li></ul><p><strong>A는 틀린 답입니다.</strong> Qubit (큐비트)는 0, 1, 또는 둘 다의 조합을 나타낼 수 있으며, 이는 superposition (중첩)이라는 속성입니다. Quantum computer (양자 컴퓨터)는 한 번에 지수적으로 많은 논리적 상태를 허용하는 특별한 종류의 superposition (중첩)을 활용합니다. 이것은 강력한 업적이며, 어떤 classical computer (고전 컴퓨터)도 이를 달성할 수 없습니다. Qubit (큐비트)는 0과 1만 나타낼 수 있는 것이 아닙니다. 이것은 반직관적인 개념이 아니라, 오히려 고전 비트의 특성입니다. 양자 물리학의 반직관적인 개념은 superposition (중첩), entanglement (얽힘), interference (간섭)과 같은 양자 현상입니다.</p></details><h2 id="문제-20-n개의-qubit을-가진-양자-시스템의-중첩-가능-상태-수" tabindex="-1"><a class="header-anchor" href="#문제-20-n개의-qubit을-가진-양자-시스템의-중첩-가능-상태-수"><span>문제 20: n개의 qubit을 가진 양자 시스템의 중첩 가능 상태 수</span></a></h2><div class="hint-container tip"><p class="hint-container-title">문제 제시</p><p>n개의 qubit을 가진 양자 시스템은 동시에 몇 개의 서로 다른 고전 상태의 중첩에 있을 수 있습니까?</p><p>A quantum system with n qubits can be in a superposition of how many distinct classical states simultaneously?</p><ul><li>A. 1</li><li>B. n</li><li>C. 2n</li><li>D. n²</li><li>E. 2ⁿ</li></ul></div><h3 id="필요한-기반-지식-19" tabindex="-1"><a class="header-anchor" href="#필요한-기반-지식-19"><span>필요한 기반 지식</span></a></h3><h4 id="_1-qubit-큐비트-시스템의-상태-공간" tabindex="-1"><a class="header-anchor" href="#_1-qubit-큐비트-시스템의-상태-공간"><span>1. Qubit (큐비트) 시스템의 상태 공간</span></a></h4><p><strong>n개의 qubit (큐비트) 시스템의 가능한 상태:</strong></p><ul><li><em>n</em>개의 qubit (큐비트) 시스템은 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mi>n</mi></msup></mrow><annotation encoding="application/x-tex">2^n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span>개의 가능한 상태 중 하나로 측정될 수 있습니다</li><li>이것은 classical computer bit (고전 컴퓨터 비트) 또는 실제로 <em>n</em>개의 이진 결과의 모음에도 해당합니다</li></ul><p><strong>동전 비유:</strong></p><ul><li>동전 하나를 뒤집으면 두 가지 가능한 상태가 있습니다: H (앞면) 또는 T (뒷면)</li><li>동전 두 개를 뒤집으면 네 가지 가능한 상태가 있습니다: HH, HT, TH, TT</li><li>동전 세 개의 경우, 여덟 가지 상태를 찾습니다: HHH, HHT, HTH, HTT, THH, THT, TTH, TTT</li><li>이러한 추세는 계속됩니다. 동전을 하나 더 추가할 때마다 가능한 결과의 수가 두 배가 됩니다</li><li>따라서 <em>n</em>개의 이러한 이진 변수 시스템의 결과 수는 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mi>n</mi></msup></mrow><annotation encoding="application/x-tex">2^n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span>입니다</li></ul><h4 id="_2-classical-computer-고전-컴퓨터-vs-quantum-computer-양자-컴퓨터" tabindex="-1"><a class="header-anchor" href="#_2-classical-computer-고전-컴퓨터-vs-quantum-computer-양자-컴퓨터"><span>2. Classical Computer (고전 컴퓨터) vs Quantum Computer (양자 컴퓨터)</span></a></h4><p><strong>Classical Computer (고전 컴퓨터)의 상태:</strong></p><ul><li>Classical computer (고전 컴퓨터)는 한 번에 그 상태 중 하나에만 있을 수 있습니다</li><li><em>n</em>개의 bit (비트)를 가진 컴퓨터는 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mi>n</mi></msup></mrow><annotation encoding="application/x-tex">2^n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span>개의 가능한 상태 중 하나에 존재할 수 있습니다</li><li>이는 00...0 (<em>n</em>개의 0의 시퀀스)부터 11...1 (<em>n</em>개의 1의 시퀀스)까지의 범위입니다</li></ul><p><strong>Quantum Computer (양자 컴퓨터)의 상태:</strong></p><ul><li>Classical (고전)과 quantum (양자) 컴퓨터 모두 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mi>n</mi></msup></mrow><annotation encoding="application/x-tex">2^n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span>개의 가능한 상태 공간에 접근할 수 있습니다</li><li>하지만 quantum computer (양자 컴퓨터)는 한 번에 <strong>모든</strong> 이러한 상태의 superposition (중첩)에 있을 수 있습니다</li><li>이것이 quantum computer (양자 컴퓨터)를 특별하게 만드는 것입니다</li></ul><h4 id="_3-superposition-중첩-의-의미" tabindex="-1"><a class="header-anchor" href="#_3-superposition-중첩-의-의미"><span>3. Superposition (중첩)의 의미</span></a></h4><p><strong>Superposition (중첩)의 정의:</strong></p><ul><li><strong>Superposition (중첩)</strong>은 두 개 이상의 상태의 가중 합 또는 차이입니다</li><li>Quantum computer (양자 컴퓨터)는 한 번에 지수적으로 많은 논리적 상태를 허용하는 특별한 종류의 superposition (중첩)을 활용합니다</li><li>이것은 강력한 업적이며, 어떤 classical computer (고전 컴퓨터)도 이를 달성할 수 없습니다</li></ul><p><strong>Superposition (중첩)의 계산 능력:</strong></p><ul><li>Quantum computer (양자 컴퓨터)는 모든 가능한 상태의 superposition (중첩)에 있을 수 있으므로, 모든 가능한 입력 상태에 대해 한 번에 연산을 수행할 수 있습니다</li><li>이것은 매우 큰 해결책 공간이나 계산적으로 매우 비용이 많이 드는 단계가 있는 문제의 경우, 게임 체인저가 될 수 있습니다</li></ul><h4 id="_4-지수적-성장-exponential-growth" tabindex="-1"><a class="header-anchor" href="#_4-지수적-성장-exponential-growth"><span>4. 지수적 성장 (Exponential Growth)</span></a></h4><p><strong>이진 변수 시스템의 성장:</strong></p><ul><li>각 qubit (큐비트)는 두 가지 가능한 상태 (0 또는 1)를 가질 수 있습니다</li><li><em>n</em>개의 qubit (큐비트)가 있으면, 각 qubit (큐비트)는 독립적으로 두 가지 상태 중 하나를 가질 수 있습니다</li><li>따라서 전체 시스템의 가능한 상태 수는 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn><mo>×</mo><mn>2</mn><mo>×</mo><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mo>×</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">2 \\times 2 \\times ... \\times 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord">...</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> (n번) = <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mi>n</mi></msup></mrow><annotation encoding="application/x-tex">2^n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span>입니다</li></ul><p><strong>지수적 성장의 예:</strong></p><ul><li>1 qubit: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mn>1</mn></msup><mo>=</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">2^1 = 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span>개의 상태</li><li>2 qubits: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mn>2</mn></msup><mo>=</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">2^2 = 4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span>개의 상태</li><li>3 qubits: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mn>3</mn></msup><mo>=</mo><mn>8</mn></mrow><annotation encoding="application/x-tex">2^3 = 8</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">3</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span></span></span></span>개의 상태</li><li>10 qubits: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mn>10</mn></msup><mo>=</mo><mn>1</mn><mo separator="true">,</mo><mn>024</mn></mrow><annotation encoding="application/x-tex">2^{10} = 1,024</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">10</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">024</span></span></span></span>개의 상태</li><li>20 qubits: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mn>20</mn></msup><mo>=</mo><mn>1</mn><mo separator="true">,</mo><mn>048</mn><mo separator="true">,</mo><mn>576</mn></mrow><annotation encoding="application/x-tex">2^{20} = 1,048,576</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">20</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">048</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">576</span></span></span></span>개의 상태</li><li>50 qubits: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mn>50</mn></msup><mo>≈</mo><mn>1.1</mn><mo>×</mo><msup><mn>10</mn><mn>15</mn></msup></mrow><annotation encoding="application/x-tex">2^{50} \\approx 1.1 \\times 10^{15}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">50</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1.1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">15</span></span></span></span></span></span></span></span></span></span></span></span>개의 상태</li></ul><h4 id="_5-양자-컴퓨팅의-힘" tabindex="-1"><a class="header-anchor" href="#_5-양자-컴퓨팅의-힘"><span>5. 양자 컴퓨팅의 힘</span></a></h4><p><strong>지수적 중첩 (Exponential Superposition):</strong></p><ul><li>Quantum computer (양자 컴퓨터)는 한 번에 지수적으로 많은 논리적 상태를 허용하는 특별한 종류의 superposition (중첩)을 활용합니다</li><li><em>n</em>개의 qubit (큐비트)는 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mi>n</mi></msup></mrow><annotation encoding="application/x-tex">2^n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span>개의 상태를 동시에 중첩할 수 있습니다</li><li>이것은 어떤 classical computer (고전 컴퓨터)도 달성할 수 없는 능력입니다</li></ul><p><strong>계산 능력:</strong></p><ul><li>Quantum computer (양자 컴퓨터)는 모든 가능한 상태의 superposition (중첩)에 있을 수 있으므로, 모든 가능한 입력 상태에 대해 한 번에 연산을 수행할 수 있습니다</li><li>이것은 매우 큰 해결책 공간을 탐색하는 데 특히 유용합니다</li></ul><h3 id="풀이-과정-19" tabindex="-1"><a class="header-anchor" href="#풀이-과정-19"><span>풀이 과정</span></a></h3><ol><li><p><strong>n개의 qubit (큐비트) 시스템의 가능한 상태 수 확인</strong></p><ul><li><em>n</em>개의 qubit (큐비트) 시스템은 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mi>n</mi></msup></mrow><annotation encoding="application/x-tex">2^n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span>개의 가능한 상태 중 하나로 측정될 수 있습니다</li><li>동전을 하나 더 추가할 때마다 가능한 결과의 수가 두 배가 됩니다</li><li>따라서 <em>n</em>개의 이러한 이진 변수 시스템의 결과 수는 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mi>n</mi></msup></mrow><annotation encoding="application/x-tex">2^n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span>입니다</li></ul></li><li><p><strong>Superposition (중첩)의 의미 확인</strong></p><ul><li>Quantum computer (양자 컴퓨터)는 한 번에 <strong>모든</strong> 이러한 상태의 superposition (중첩)에 있을 수 있습니다</li><li>이것이 quantum computer (양자 컴퓨터)를 특별하게 만드는 것입니다</li></ul></li><li><p><strong>각 옵션 분석</strong></p><ul><li><strong>A. 1</strong>: 이것은 classical computer (고전 컴퓨터)의 특성입니다. 한 번에 하나의 상태에만 있을 수 있습니다. 틀린 답입니다.</li><li><strong>B. n</strong>: 이것은 qubit (큐비트)의 개수입니다. 가능한 상태의 수가 아닙니다. 틀린 답입니다.</li><li><strong>C. 2n</strong>: 이것은 선형 성장을 나타냅니다. 하지만 이진 변수 시스템은 지수적으로 성장합니다. 틀린 답입니다.</li><li><strong>D. n²</strong>: 이것은 2차 성장을 나타냅니다. 하지만 이진 변수 시스템은 지수적으로 성장합니다. 틀린 답입니다.</li><li><strong>E. 2ⁿ</strong>: 이것은 정확한 답입니다. <em>n</em>개의 qubit (큐비트) 시스템은 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mi>n</mi></msup></mrow><annotation encoding="application/x-tex">2^n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span>개의 가능한 상태를 동시에 중첩할 수 있습니다. 올바른 답입니다.</li></ul></li></ol><details class="hint-container details"><summary>최종 답안</summary><p><strong>결론 도출</strong></p><ul><li>E. 2ⁿ이 정확한 답입니다</li><li><em>n</em>개의 qubit (큐비트) 시스템은 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mi>n</mi></msup></mrow><annotation encoding="application/x-tex">2^n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span>개의 가능한 상태를 동시에 중첩할 수 있습니다</li><li>이것은 양자 컴퓨팅의 지수적 힘을 보여줍니다</li></ul><p><em>n</em>개의 qubit (큐비트) 시스템은 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mi>n</mi></msup></mrow><annotation encoding="application/x-tex">2^n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span>개의 가능한 상태 중 하나로 측정될 수 있습니다. 이것은 classical computer bit (고전 컴퓨터 비트) 또는 실제로 <em>n</em>개의 이진 결과의 모음에도 해당합니다. 동전을 하나 더 추가할 때마다 가능한 결과의 수가 두 배가 되므로, <em>n</em>개의 이러한 이진 변수 시스템의 결과 수는 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mi>n</mi></msup></mrow><annotation encoding="application/x-tex">2^n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span>입니다.</p><p>Classical (고전)과 quantum (양자) 컴퓨터 모두 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mi>n</mi></msup></mrow><annotation encoding="application/x-tex">2^n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span>개의 가능한 상태 공간에 접근할 수 있습니다. 하지만 classical computer (고전 컴퓨터)는 한 번에 그 상태 중 하나에만 있을 수 있는 반면, quantum computer (양자 컴퓨터)는 한 번에 <strong>모든</strong> 이러한 상태의 superposition (중첩)에 있을 수 있습니다. 이것이 quantum computer (양자 컴퓨터)를 특별하게 만드는 것입니다.</p><p>Quantum computer (양자 컴퓨터)는 한 번에 지수적으로 많은 논리적 상태를 허용하는 특별한 종류의 superposition (중첩)을 활용합니다. 이것은 강력한 업적이며, 어떤 classical computer (고전 컴퓨터)도 이를 달성할 수 없습니다. <em>n</em>개의 qubit (큐비트)는 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mi>n</mi></msup></mrow><annotation encoding="application/x-tex">2^n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span></span></span></span></span></span></span>개의 상태를 동시에 중첩할 수 있으며, 이것은 양자 컴퓨팅의 지수적 힘을 보여줍니다.</p><p><strong>A, B, C, D는 모두 틀린 답입니다.</strong> A는 classical computer (고전 컴퓨터)의 특성이며, B, C, D는 이진 변수 시스템의 지수적 성장을 올바르게 반영하지 못합니다. 이진 변수 시스템은 선형적으로 또는 2차적으로 성장하는 것이 아니라 지수적으로 성장합니다.</p></details>`,673)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};